                                </SelectTrigger>
                              </FormControl>
                              <SelectContent className="bg-navy-700 border-navy-600">
                                {trades.map((trade) => (
                                  <SelectItem key={trade} value={trade.toLowerCase().replace(/\s+/g, '-')} className="text-white hover:bg-navy-600">
                                    {trade}
