client/src/components/RecommendationForm.content:
import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { apiRequest } from "@/lib/queryClient";
import { ThumbsUp, ThumbsDown, Clock, MessageSquare, Star } from "lucide-react";
import { Link } from "wouter";

const recommendationSchema = z.object({
  recommendationType: z.enum(['positive', 'negative']),
  comment: z.string().min(10, 'Please provide at least 10 characters of feedback'),
  projectType: z.string().optional(),
  projectValue: z.string().optional(),
  workQuality: z.number().min(1).max(5).optional(),
  timeliness: z.number().min(1).max(5).optional(),
  communication: z.number().min(1).max(5).optional(),
  wouldHireAgain: z.boolean().optional(),
  customerName: z.string().min(2, 'Name is required'),
  customerEmail: z.string().email('Valid email is required'),
  customerPhone: z.string().optional(),
});

type RecommendationFormData = z.infer<typeof recommendationSchema>;

interface RecommendationFormProps {
  contractorId: string;
  contractorName: string;
  onSuccess?: () => void;
}

export function RecommendationForm({ contractorId, contractorName, onSuccess }: RecommendationFormProps) {
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showForm, setShowForm] = useState(false);

  const form = useForm<RecommendationFormData>({
    resolver: zodResolver(recommendationSchema),
    defaultValues: {
      recommendationType: 'positive',
      customerName: user?.firstName && user?.lastName ? `${user.firstName} ${user.lastName}` : '',
      customerEmail: user?.email || '',
      comment: '',
      projectType: '',
      projectValue: '',
      workQuality: 5,
      timeliness: 5,
      communication: 5,
      wouldHireAgain: true,
      customerPhone: '',
    },
  });

  const submitRecommendation = useMutation({
    mutationFn: async (data: RecommendationFormData) => {
      const response = await fetch(`/api/contractors/${contractorId}/recommendations`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.message || 'Failed to submit recommendation');
      }

      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Recommendation Submitted",
        description: "Your recommendation has been submitted and will be reviewed before publishing.",
      });
      form.reset();
      setShowForm(false);
      onSuccess?.();
      // Invalidate contractor data to refresh recommendations
      queryClient.invalidateQueries({ queryKey: [`/api/contractors/${contractorId}`] });
    },
    onError: (error: any) => {
      toast({
        title: "Submission Failed", 
        description: error.message || "Failed to submit recommendation. Please try again.",
        variant: "destructive",
      });
    },
  });

  if (!isAuthenticated) {
    return (
      <Card className="bg-navy-700 border-navy-600">
        <CardContent className="p-6">
          <div className="text-center">
            <MessageSquare className="h-12 w-12 text-orange-500 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-white mb-2">Share Your Experience</h3>
            <p className="text-gray-300 mb-4">
              Help other homeowners by sharing your experience with {contractorName}
            </p>
            <Link href="/api/login">
              <Button className="bg-orange-500 hover:bg-orange-600" data-testid="button-login-to-recommend">
                Sign In to Leave Recommendation
              </Button>
            </Link>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!showForm) {
    return (
      <Card className="bg-navy-700 border-navy-600">
        <CardContent className="p-6">
          <div className="text-center">
            <MessageSquare className="h-12 w-12 text-orange-500 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-white mb-2">Share Your Experience</h3>
            <p className="text-gray-300 mb-4">
              Help other homeowners by sharing your experience with {contractorName}
            </p>
            <Button 
              onClick={() => setShowForm(true)}
              className="bg-orange-500 hover:bg-orange-600"
              data-testid="button-write-recommendation"
            >
              Write a Recommendation
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="bg-navy-700 border-navy-600">
      <CardHeader>
        <CardTitle className="text-white flex items-center">
          <MessageSquare className="h-5 w-5 mr-2 text-orange-500" />
          Recommend {contractorName}
        </CardTitle>
      </CardHeader>
      <CardContent className="p-6">
        <Form {...form}>
          <form onSubmit={form.handleSubmit((data) => submitRecommendation.mutate(data))} className="space-y-6">
            {/* Recommendation Type */}
            <FormField
              control={form.control}
              name="recommendationType"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-white">Would you recommend this contractor?</FormLabel>
                  <FormControl>
                    <RadioGroup
                      onValueChange={field.onChange}
                      defaultValue={field.value}
                      className="flex gap-6"
                      data-testid="radio-recommendation-type"
                    >
                      <div className="flex items-center space-x-2">
                        <RadioGroupItem value="positive" id="positive" />
                        <label htmlFor="positive" className="flex items-center text-green-400 cursor-pointer">
                          <ThumbsUp className="h-4 w-4 mr-1" />
                          Yes, I recommend
                        </label>
                      </div>
                      <div className="flex items-center space-x-2">
                        <RadioGroupItem value="negative" id="negative" />
                        <label htmlFor="negative" className="flex items-center text-red-400 cursor-pointer">
                          <ThumbsDown className="h-4 w-4 mr-1" />
                          No, I don't recommend
                        </label>
                      </div>
                    </RadioGroup>
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Customer Information */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="customerName"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-white">Your Name</FormLabel>
                    <FormControl>
                      <Input 
                        {...field} 
                        className="bg-navy-800 border-navy-600 text-white"
                        data-testid="input-customer-name"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="customerEmail"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-white">Your Email</FormLabel>
                    <FormControl>
                      <Input 
                        {...field} 
                        type="email"
                        className="bg-navy-800 border-navy-600 text-white"
                        data-testid="input-customer-email"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Project Details */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField
                control={form.control}
                name="projectType"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-white">Project Type</FormLabel>
                    <FormControl>
                      <Input 
                        {...field} 
                        placeholder="e.g., Kitchen Remodel, Roof Repair"
                        className="bg-navy-800 border-navy-600 text-white"
                        data-testid="input-project-type"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />

              <FormField
                control={form.control}
                name="projectValue"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-white">Project Value (Optional)</FormLabel>
                    <Select onValueChange={field.onChange} defaultValue={field.value}>
                      <FormControl>
                        <SelectTrigger className="bg-navy-800 border-navy-600 text-white" data-testid="select-project-value">
                          <SelectValue placeholder="Select range" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="under-1000">Under $1,000</SelectItem>
                        <SelectItem value="1000-5000">$1,000 - $5,000</SelectItem>
                        <SelectItem value="5000-15000">$5,000 - $15,000</SelectItem>
                        <SelectItem value="15000-50000">$15,000 - $50,000</SelectItem>
                        <SelectItem value="over-50000">Over $50,000</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
            </div>

            {/* Detailed Comment */}
            <FormField
              control={form.control}
              name="comment"
              render={({ field }) => (
                <FormItem>
                  <FormLabel className="text-white">Your Experience</FormLabel>
                  <FormControl>
                    <Textarea
                      {...field}
                      placeholder="Share details about your experience with this contractor..."
                      className="bg-navy-800 border-navy-600 text-white min-h-24"
                      data-testid="textarea-comment"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />

            {/* Optional Ratings */}
            {form.watch('recommendationType') === 'positive' && (
              <div className="space-y-4">
                <h4 className="text-white font-medium">Rate Your Experience (Optional)</h4>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <FormField
                    control={form.control}
                    name="workQuality"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white text-sm">Work Quality</FormLabel>
                        <FormControl>
                          <Select onValueChange={(value) => field.onChange(parseInt(value))} defaultValue={field.value?.toString()}>
                            <SelectTrigger className="bg-navy-800 border-navy-600 text-white" data-testid="select-work-quality">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              {[5,4,3,2,1].map(num => (
                                <SelectItem key={num} value={num.toString()}>
                                  {num} Star{num !== 1 ? 's' : ''}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </FormControl>
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="timeliness"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white text-sm">Timeliness</FormLabel>
                        <FormControl>
                          <Select onValueChange={(value) => field.onChange(parseInt(value))} defaultValue={field.value?.toString()}>
                            <SelectTrigger className="bg-navy-800 border-navy-600 text-white" data-testid="select-timeliness">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              {[5,4,3,2,1].map(num => (
                                <SelectItem key={num} value={num.toString()}>
                                  {num} Star{num !== 1 ? 's' : ''}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </FormControl>
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="communication"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel className="text-white text-sm">Communication</FormLabel>
                        <FormControl>
                          <Select onValueChange={(value) => field.onChange(parseInt(value))} defaultValue={field.value?.toString()}>
                            <SelectTrigger className="bg-navy-800 border-navy-600 text-white" data-testid="select-communication">
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              {[5,4,3,2,1].map(num => (
                                <SelectItem key={num} value={num.toString()}>
                                  {num} Star{num !== 1 ? 's' : ''}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </FormControl>
                      </FormItem>
                    )}
                  />
                </div>
              </div>
            )}

            {/* Form Actions */}
            <div className="flex gap-4">
              <Button
                type="submit"
                disabled={submitRecommendation.isPending}
                className="bg-orange-500 hover:bg-orange-600 flex-1"
                data-testid="button-submit-recommendation"
              >
                {submitRecommendation.isPending ? "Submitting..." : "Submit Recommendation"}
              </Button>
              <Button
                type="button"
                variant="outline"
                onClick={() => setShowForm(false)}
                className="border-navy-600 text-white hover:bg-navy-600"
                data-testid="button-cancel-recommendation"
              >
                Cancel
              </Button>
            </div>
          </form>
        </Form>
      </CardContent>
    </Card>
  );
}

client/src/components/HelperProfileModal.content:
import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { 
  Star, 
  MapPin, 
  Clock, 
  DollarSign, 
  Calendar, 
  Briefcase, 
  GraduationCap,
  Award,
  MessageSquare,
  Shield,
  CheckCircle,
  Building,
  User
} from "lucide-react";

interface WorkExperience {
  jobTitle: string;
  company: string;
  startDate: string;
  endDate?: string;
  description: string;
  isCurrentJob: boolean;
  fromPlatform: boolean;
  taskId?: string;
}

interface Education {
  degree: string;
  school: string;
  graduationYear?: number;
  fieldOfStudy?: string;
}

interface Certification {
  name: string;
  issuer: string;
  issueDate: string;
  expirationDate?: string;
  credentialId?: string;
}

interface PortfolioItem {
  title: string;
  description: string;
  imageUrl?: string;
  completionDate: string;
  skills: string[];
  fromPlatform: boolean;
  taskId?: string;
}

interface Helper {
  id: string;
  firstName: string;
  lastName: string;
  profileImageUrl?: string;
  bio?: string;
  skills?: string[];
  hourlyRate?: string;
  averageRating?: string;
  totalJobsCompleted: number;
  isIdVerified: boolean;
  isBackgroundChecked: boolean;
  verificationStatus: string;
  workExperience?: WorkExperience[];
  education?: Education[];
  certifications?: Certification[];
  portfolioItems?: PortfolioItem[];
  city?: string;
  transportationMethod?: string;
  maxTravelDistance?: number;
  isAvailable: boolean;
}

interface HelperProfileModalProps {
  helper: Helper;
  isOpen: boolean;
  onClose: () => void;
}

export function HelperProfileModal({ helper, isOpen, onClose }: HelperProfileModalProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'experience' | 'portfolio' | 'reviews'>('overview');

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', { 
      month: 'short', 
      year: 'numeric' 
    });
  };

  const getInitials = (firstName: string, lastName: string) => {
    return `${firstName.charAt(0)}${lastName.charAt(0)}`;
  };

  const platformJobs = helper.workExperience?.filter(exp => exp.fromPlatform) || [];
  const otherJobs = helper.workExperience?.filter(exp => !exp.fromPlatform) || [];

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto bg-navy-800 border-navy-600">
        <DialogHeader className="pb-6">
          <div className="flex items-start gap-4">
            <Avatar className="h-20 w-20">
              <AvatarImage src={helper.profileImageUrl} />
              <AvatarFallback className="bg-orange-500 text-white text-lg">
                {getInitials(helper.firstName, helper.lastName)}
              </AvatarFallback>
            </Avatar>

            <div className="flex-1">
              <DialogTitle className="text-2xl font-bold text-white mb-2">
                {helper.firstName} {helper.lastName}
              </DialogTitle>

              <div className="flex items-center gap-4 mb-3">
                {helper.averageRating && (
                  <div className="flex items-center">
                    <Star className="h-4 w-4 text-yellow-400 fill-current mr-1" />
                    <span className="text-white font-medium">{helper.averageRating}</span>
                    <span className="text-gray-400 ml-1">({helper.totalJobsCompleted} jobs)</span>
                  </div>
                )}

                <div className="flex items-center gap-2">
                  {helper.isIdVerified && (
                    <Badge className="bg-green-500/20 text-green-400 border-green-500/50">
                      <Shield className="h-3 w-3 mr-1" />
                      ID Verified
                    </Badge>
                  )}
                  {helper.isBackgroundChecked && (
                    <Badge className="bg-blue-500/20 text-blue-400 border-blue-500/50">
                      <CheckCircle className="h-3 w-3 mr-1" />
                      Background Checked
                    </Badge>
                  )}
                  {helper.isAvailable && (
                    <Badge className="bg-green-500/20 text-green-400 border-green-500/50">
                      Available
                    </Badge>
                  )}
                </div>
              </div>

              <div className="flex items-center gap-4 text-sm text-gray-300">
                {helper.city && (
                  <div className="flex items-center">
                    <MapPin className="h-4 w-4 mr-1" />
                    <span>{helper.city}</span>
                  </div>
                )}
                {helper.hourlyRate && (
                  <div className="flex items-center">
                    <DollarSign className="h-4 w-4 mr-1" />
                    <span>${helper.hourlyRate}/hr</span>
                  </div>
                )}
                {helper.maxTravelDistance && (
                  <div className="flex items-center">
                    <Clock className="h-4 w-4 mr-1" />
                    <span>Travels {helper.maxTravelDistance} miles</span>
                  </div>
                )}
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <Button className="bg-orange-500 hover:bg-orange-600">
                <MessageSquare className="h-4 w-4 mr-2" />
                Contact Helper
              </Button>
              <Button variant="outline" className="border-orange-500 text-orange-500 hover:bg-orange-500 hover:text-white">
                Hire for Job
              </Button>
            </div>
          </div>
        </DialogHeader>

        {/* Tab Navigation */}
        <div className="flex border-b border-navy-600 mb-6">
          <button
            onClick={() => setActiveTab('overview')}
            className={`px-4 py-2 font-medium ${
              activeTab === 'overview'
                ? 'text-orange-500 border-b-2 border-orange-500'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            Overview
          </button>
          <button
            onClick={() => setActiveTab('experience')}
            className={`px-4 py-2 font-medium ${
              activeTab === 'experience'
                ? 'text-orange-500 border-b-2 border-orange-500'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            Experience
          </button>
          <button
            onClick={() => setActiveTab('portfolio')}
            className={`px-4 py-2 font-medium ${
              activeTab === 'portfolio'
                ? 'text-orange-500 border-b-2 border-orange-500'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            Portfolio
          </button>
          <button
            onClick={() => setActiveTab('reviews')}
            className={`px-4 py-2 font-medium ${
              activeTab === 'reviews'
                ? 'text-orange-500 border-b-2 border-orange-500'
                : 'text-gray-400 hover:text-white'
            }`}
          >
            Reviews
          </button>
        </div>

        {/* Tab Content */}
        <div className="space-y-6">
          {activeTab === 'overview' && (
            <>
              {/* Bio */}
              {helper.bio && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-3">About</h3>
                  <p className="text-gray-300 leading-relaxed">{helper.bio}</p>
                </div>
              )}

              {/* Skills */}
              {helper.skills && helper.skills.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-3">Skills</h3>
                  <div className="flex flex-wrap gap-2">
                    {helper.skills.map((skill, index) => (
                      <Badge key={index} variant="secondary" className="bg-navy-600 text-gray-300">
                        {skill}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}

              {/* Transportation */}
              {helper.transportationMethod && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-3">Transportation</h3>
                  <div className="text-gray-300">
                    <p>Method: {helper.transportationMethod}</p>
                    {helper.maxTravelDistance && (
                      <p>Travel radius: {helper.maxTravelDistance} miles</p>
                    )}
                  </div>
                </div>
              )}

              {/* Recent Platform Jobs */}
              {platformJobs.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-3">Recent TradeScout Jobs</h3>
                  <div className="space-y-3">
                    {platformJobs.slice(0, 3).map((job, index) => (
                      <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <h4 className="font-medium text-white">{job.jobTitle}</h4>
                            <p className="text-orange-400 text-sm">{job.company}</p>
                          </div>
                          <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/50">
                            TradeScout
                          </Badge>
                        </div>
                        <p className="text-gray-300 text-sm mb-2">{job.description}</p>
                        <p className="text-gray-400 text-xs">
                          {formatDate(job.startDate)} - {job.endDate ? formatDate(job.endDate) : 'Present'}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          )}

          {activeTab === 'experience' && (
            <div className="space-y-6">
              {/* Platform Jobs */}
              {platformJobs.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                    <Briefcase className="h-5 w-5 mr-2 text-orange-500" />
                    TradeScout Experience
                  </h3>
                  <div className="space-y-4">
                    {platformJobs.map((job, index) => (
                      <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <h4 className="font-medium text-white">{job.jobTitle}</h4>
                            <p className="text-orange-400">{job.company}</p>
                          </div>
                          <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/50">
                            Platform Job
                          </Badge>
                        </div>
                        <p className="text-gray-300 mb-3">{job.description}</p>
                        <p className="text-gray-400 text-sm">
                          {formatDate(job.startDate)} - {job.endDate ? formatDate(job.endDate) : 'Present'}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Other Work Experience */}
              {otherJobs.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                    <Building className="h-5 w-5 mr-2 text-blue-500" />
                    Other Experience
                  </h3>
                  <div className="space-y-4">
                    {otherJobs.map((job, index) => (
                      <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <h4 className="font-medium text-white">{job.jobTitle}</h4>
                            <p className="text-blue-400">{job.company}</p>
                          </div>
                          {job.isCurrentJob && (
                            <Badge className="bg-green-500/20 text-green-400 border-green-500/50">
                              Current
                            </Badge>
                          )}
                        </div>
                        <p className="text-gray-300 mb-3">{job.description}</p>
                        <p className="text-gray-400 text-sm">
                          {formatDate(job.startDate)} - {job.endDate ? formatDate(job.endDate) : 'Present'}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Education */}
              {helper.education && helper.education.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                    <GraduationCap className="h-5 w-5 mr-2 text-purple-500" />
                    Education
                  </h3>
                  <div className="space-y-3">
                    {helper.education.map((edu, index) => (
                      <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                        <h4 className="font-medium text-white">{edu.degree}</h4>
                        <p className="text-purple-400">{edu.school}</p>
                        {edu.fieldOfStudy && (
                          <p className="text-gray-300 text-sm">{edu.fieldOfStudy}</p>
                        )}
                        {edu.graduationYear && (
                          <p className="text-gray-400 text-sm">Graduated {edu.graduationYear}</p>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Certifications */}
              {helper.certifications && helper.certifications.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-white mb-4 flex items-center">
                    <Award className="h-5 w-5 mr-2 text-yellow-500" />
                    Certifications
                  </h3>
                  <div className="space-y-3">
                    {helper.certifications.map((cert, index) => (
                      <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                        <h4 className="font-medium text-white">{cert.name}</h4>
                        <p className="text-yellow-400">{cert.issuer}</p>
                        <div className="flex items-center justify-between mt-2">
                          <p className="text-gray-400 text-sm">
                            Issued: {formatDate(cert.issueDate)}
                          </p>
                          {cert.expirationDate && (
                            <p className="text-gray-400 text-sm">
                              Expires: {formatDate(cert.expirationDate)}
                            </p>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {activeTab === 'portfolio' && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Portfolio</h3>
              {helper.portfolioItems && helper.portfolioItems.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {helper.portfolioItems.map((item, index) => (
                    <div key={index} className="bg-navy-700 p-4 rounded-lg border border-navy-600">
                      {item.imageUrl && (
                        <img 
                          src={item.imageUrl} 
                          alt={item.title}
                          className="w-full h-48 object-cover rounded-lg mb-3"
                        />
                      )}
                      <div className="flex items-start justify-between mb-2">
                        <h4 className="font-medium text-white">{item.title}</h4>
                        {item.fromPlatform && (
                          <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/50">
                            TradeScout
                          </Badge>
                        )}
                      </div>
                      <p className="text-gray-300 text-sm mb-3">{item.description}</p>
                      <div className="flex flex-wrap gap-1 mb-2">
                        {item.skills.map((skill, skillIndex) => (
                          <Badge key={skillIndex} variant="secondary" className="text-xs bg-navy-600 text-gray-300">
                            {skill}
                          </Badge>
                        ))}
                      </div>
                      <p className="text-gray-400 text-xs">
                        Completed: {formatDate(item.completionDate)}
                      </p>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8">
                  <User className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                  <p className="text-gray-400">No portfolio items yet</p>
                </div>
              )}
            </div>
          )}

          {activeTab === 'reviews' && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-4">Reviews & Ratings</h3>
              <div className="text-center py-8">
                <Star className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <p className="text-gray-400">Reviews will be loaded here</p>
                <p className="text-gray-500 text-sm">This feature connects to the worker reviews system</p>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

