import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useAuth } from "@/hooks/useAuth";
import { Users, MessageSquare, Plus, Search, MapPin, Tag, Heart, MessageCircle, Crown } from "lucide-react";
import { useState } from "react";
import { useToast } from "@/hooks/use-toast";
import { Link } from "wouter";

interface Group {
  id: string;
  name: string;
  description: string;
  type: string;
  countyFips?: string;
  memberCount: number;
  isPublic: boolean;
  tags: string[];
  createdBy: string;
  admins: string[];
  rules: string[];
  coverImageUrl?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export default function Groups() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedType, setSelectedType] = useState('all');
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [newGroup, setNewGroup] = useState({
    name: '',
    description: '',
    type: 'county_community',
    isPublic: true,
    tags: '',
    rules: ''
  });

  const { data: groups = [], isLoading: groupsLoading } = useQuery({
    queryKey: ['/api/groups', searchQuery, selectedType],
    queryFn: () => {
      const params = new URLSearchParams();
      if (searchQuery) params.append('search', searchQuery);
      if (selectedType !== 'all') params.append('type', selectedType);
      return fetch(`/api/groups?${params}`).then(res => res.json());
    }
  });

  const { data: userGroups = [] } = useQuery<Group[]>({
    queryKey: ['/api/groups/user'],
  });

  const joinGroupMutation = useMutation({
    mutationFn: async (groupId: string) => {
      const response = await fetch(`/api/groups/${groupId}/join`, {
        method: 'POST',
      });
      if (!response.ok) throw new Error('Failed to join group');
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Joined Group!",
        description: "You've successfully joined the group and can now participate in discussions.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/groups/user'] });
    },
    onError: () => {
      toast({
        title: "Join Failed",
        description: "Unable to join group. Please try again.",
        variant: "destructive",
      });
    },
  });

  const createGroupMutation = useMutation({
    mutationFn: async (groupData: any) => {
      const response = await fetch('/api/groups', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...groupData,
          tags: groupData.tags.split(',').map((t: string) => t.trim()).filter(Boolean),
          rules: groupData.rules.split('\n').map((r: string) => r.trim()).filter(Boolean)
        })
      });
      if (!response.ok) throw new Error('Failed to create group');
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Group Created!",
        description: "Your new group has been created and you are now an admin.",
      });
      setIsCreateDialogOpen(false);
      setNewGroup({
        name: '',
        description: '',
        type: 'county_community',
        isPublic: true,
        tags: '',
        rules: ''
      });
      queryClient.invalidateQueries({ queryKey: ['/api/groups'] });
      queryClient.invalidateQueries({ queryKey: ['/api/groups/user'] });
    },
    onError: () => {
      toast({
        title: "Creation Failed",
        description: "Unable to create group. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleJoinGroup = (groupId: string) => {
    joinGroupMutation.mutate(groupId);
  };

  const handleCreateGroup = () => {
    createGroupMutation.mutate(newGroup);
  };

  const isUserMember = (groupId: string) => {
    return userGroups.some((group: any) => group.id === groupId);
  };

  const getTypeDisplayName = (type: string) => {
    switch (type) {
      case 'county_community': return 'County Community';
      case 'specialty_trade': return 'Trade Specialty';
      case 'interest_based': return 'Interest Based';
      default: return type;
    }
  };

  if (groupsLoading) {
    return (
      <div className="min-h-screen gradient-bg p-6">
        <div className="max-w-7xl mx-auto">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-orange-500 mx-auto"></div>
            <p className="mt-2 text-slate-400">Loading groups...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen gradient-bg p-6" data-testid="groups-page">
      <div className="max-w-7xl mx-auto space-y-8">
        {/* Header */}
        <div className="text-center space-y-4">
          <div className="flex items-center justify-center space-x-3">
            <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl flex items-center justify-center">
              <Users className="w-6 h-6 text-white" />
            </div>
            <h1 className="text-4xl font-bold text-white">Community Groups</h1>
          </div>
          <p className="text-xl text-slate-300 max-w-3xl mx-auto">
            Connect with homeowners and contractors in your area. Share experiences, get advice, and build relationships.
          </p>
        </div>

        {/* Search and Filter Controls */}
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
            <Input
              placeholder="Search groups by name or keywords..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 bg-slate-800/50 border-slate-700 text-white placeholder-slate-400"
              data-testid="search-groups"
            />
          </div>
          <Select value={selectedType} onValueChange={setSelectedType}>
            <SelectTrigger className="w-full md:w-48 bg-slate-800/50 border-slate-700 text-white">
              <SelectValue placeholder="Filter by type" />
            </SelectTrigger>
            <SelectContent className="bg-slate-800 border-slate-700">
              <SelectItem value="all">All Types</SelectItem>
              <SelectItem value="county_community">County Community</SelectItem>
              <SelectItem value="specialty_trade">Trade Specialty</SelectItem>
              <SelectItem value="interest_based">Interest Based</SelectItem>
            </SelectContent>
          </Select>
          <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
            <DialogTrigger asChild>
              <Button className="bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700" data-testid="create-group-button">
                <Plus className="w-4 h-4 mr-2" />
                Create Group
              </Button>
            </DialogTrigger>
            <DialogContent className="bg-slate-800 border-slate-700 text-white max-w-2xl">
              <DialogHeader>
                <DialogTitle>Create a New Group</DialogTitle>
              </DialogHeader>
              <div className="space-y-4">
                <Input
                  placeholder="Group name"
                  value={newGroup.name}
                  onChange={(e) => setNewGroup({ ...newGroup, name: e.target.value })}
                  className="bg-slate-700 border-slate-600"
                  data-testid="group-name-input"
                />
                <Textarea
                  placeholder="Group description"
                  value={newGroup.description}
                  onChange={(e) => setNewGroup({ ...newGroup, description: e.target.value })}
                  className="bg-slate-700 border-slate-600 min-h-24"
                  data-testid="group-description-input"
                />
                <Select value={newGroup.type} onValueChange={(value) => setNewGroup({ ...newGroup, type: value })}>
                  <SelectTrigger className="bg-slate-700 border-slate-600">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="bg-slate-800 border-slate-700">
                    <SelectItem value="county_community">County Community</SelectItem>
                    <SelectItem value="specialty_trade">Trade Specialty</SelectItem>
                    <SelectItem value="interest_based">Interest Based</SelectItem>
                  </SelectContent>
                </Select>
                <Input
                  placeholder="Tags (comma separated)"
                  value={newGroup.tags}
                  onChange={(e) => setNewGroup({ ...newGroup, tags: e.target.value })}
                  className="bg-slate-700 border-slate-600"
                  data-testid="group-tags-input"
                />
                <Textarea
                  placeholder="Group rules (one per line)"
                  value={newGroup.rules}
                  onChange={(e) => setNewGroup({ ...newGroup, rules: e.target.value })}
                  className="bg-slate-700 border-slate-600 min-h-24"
                  data-testid="group-rules-input"
                />
                <Button 
                  onClick={handleCreateGroup} 
                  disabled={createGroupMutation.isPending || !newGroup.name.trim()}
                  className="w-full bg-gradient-to-r from-blue-500 to-purple-600"
                  data-testid="submit-create-group"
                >
                  {createGroupMutation.isPending ? 'Creating...' : 'Create Group'}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>

        {/* My Groups Section */}
        {userGroups.length > 0 && (
          <div className="space-y-4">
            <h2 className="text-2xl font-bold text-white flex items-center space-x-2">
              <Crown className="w-6 h-6 text-yellow-500" />
              <span>My Groups</span>
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.isArray(userGroups) ? userGroups.map((group: Group) => (
                <Card key={group.id} className="bg-slate-800/50 border-slate-700 hover:border-blue-500/50 transition-all duration-300">
                  <CardHeader className="pb-3">
                    <div className="flex items-start justify-between">
                      <div className="space-y-1">
                        <CardTitle className="text-white text-lg">{group.name}</CardTitle>
                        <Badge variant="secondary" className="bg-blue-500/20 text-blue-400">
                          {getTypeDisplayName(group.type)}
                        </Badge>
                      </div>
                      <Badge variant="outline" className="border-yellow-500 text-yellow-500">
                        Member
                      </Badge>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-4">
                    <p className="text-slate-300 text-sm line-clamp-2">{group.description}</p>
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-slate-400 flex items-center">
                        <Users className="w-4 h-4 mr-1" />
                        {group.memberCount} members
                      </span>
                    </div>
                    <Link href={`/groups/${group.id}`}>
                      <Button variant="outline" className="w-full" data-testid={`view-group-${group.id}`}>
                        <MessageSquare className="w-4 h-4 mr-2" />
                        View Group
                      </Button>
                    </Link>
                  </CardContent>
                </Card>
              )) : null}
            </div>
          </div>
        )}

        {/* All Groups Section */}
        <div className="space-y-4">
          <h2 className="text-2xl font-bold text-white flex items-center space-x-2">
            <Search className="w-6 h-6 text-orange-500" />
            <span>Discover Groups</span>
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {Array.isArray(groups) ? groups.map((group: Group) => (
              <Card 
                key={group.id} 
                className="bg-slate-800/50 border-slate-700 hover:border-orange-500/50 transition-all duration-300"
                data-testid={`group-card-${group.id}`}
              >
                <CardHeader className="pb-3">
                  <div className="space-y-2">
                    <CardTitle className="text-white text-lg">{group.name}</CardTitle>
                    <div className="flex items-center space-x-2">
                      <Badge variant="secondary" className="bg-orange-500/20 text-orange-400">
                        {getTypeDisplayName(group.type)}
                      </Badge>
                      {group.countyFips && (
                        <Badge variant="outline" className="border-slate-600 text-slate-300">
                          <MapPin className="w-3 h-3 mr-1" />
                          Local
                        </Badge>
                      )}
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  <p className="text-slate-300 text-sm leading-relaxed line-clamp-3">{group.description}</p>

                  {Array.isArray(group.tags) && group.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {group.tags.slice(0, 3).map((tag, index) => (
                        <Badge key={index} variant="outline" className="text-xs border-slate-600 text-slate-400">
                          <Tag className="w-3 h-3 mr-1" />
                          {tag}
                        </Badge>
                      ))}
                      {group.tags.length > 3 && (
                        <Badge variant="outline" className="text-xs border-slate-600 text-slate-400">
                          +{group.tags.length - 3} more
                        </Badge>
                      )}
                    </div>
                  )}

                  <div className="flex items-center justify-between text-sm">
                    <span className="text-slate-400 flex items-center">
                      <Users className="w-4 h-4 mr-1" />
                      {group.memberCount} members
                    </span>
                    <span className="text-slate-400">
                      {group.isPublic ? 'Public' : 'Private'}
                    </span>
                  </div>

                  {isUserMember(group.id) ? (
                    <Link href={`/groups/${group.id}`}>
                      <Button variant="outline" className="w-full" data-testid={`view-joined-group-${group.id}`}>
                        <MessageSquare className="w-4 h-4 mr-2" />
                        View Group
                      </Button>
                    </Link>
                  ) : (
                    <Button 
                      className="w-full bg-gradient-to-r from-orange-500 to-red-600 hover:from-orange-600 hover:to-red-700 text-white font-medium"
                      onClick={() => handleJoinGroup(group.id)}
                      disabled={joinGroupMutation.isPending}
                      data-testid={`join-group-${group.id}`}
                    >
                      {joinGroupMutation.isPending ? (
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      ) : (
                        <Plus className="w-4 h-4 mr-2" />
                      )}
                      Join Group
                    </Button>
                  )}
                </CardContent>
              </Card>
            )) : null}
          </div>
        </div>

        {groups.length === 0 && !groupsLoading && (
          <div className="text-center py-12">
            <Users className="w-16 h-16 text-slate-500 mx-auto mb-4" />
            <h3 className="text-xl font-semibold text-white mb-2">No Groups Found</h3>
            <p className="text-slate-400 mb-6">
              {searchQuery ? 'Try adjusting your search terms or filters.' : 'Be the first to create a group in your area!'}
            </p>
            <Button 
              onClick={() => setIsCreateDialogOpen(true)}
              className="bg-gradient-to-r from-blue-500 to-purple-600"
            >
              <Plus className="w-4 h-4 mr-2" />
              Create First Group
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

