/**
 * EnhancedAdSystem - Advanced advertising system for revenue generation
 * Supports multiple ad formats while maintaining excellent user experience
 */

import { useState, useEffect } from 'react';
import { Card, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { X, ExternalLink, Heart, MapPin, Clock, Star } from 'lucide-react';

interface AdContent {
  id: string;
  title: string;
  description: string;
  imageUrl?: string;
  ctaText: string;
  targetUrl: string;
  advertiser: string;
  category: 'contractor' | 'tool' | 'material' | 'service' | 'insurance';
  location?: {
    state?: string;
    county?: string;
  };
  targeting: {
    projectTypes: string[];
    userTypes: ('homeowner' | 'contractor')[];
    demographics?: string[];
  };
  format: 'banner' | 'card' | 'native' | 'video' | 'carousel';
  priority: 'low' | 'medium' | 'high' | 'premium';
  isSponsored: boolean;
  pricing: {
    model: 'cpm' | 'cpc' | 'cpa';
    rate: number;
  };
}

interface EnhancedAdSystemProps {
  placement: 'header' | 'sidebar' | 'footer' | 'inline' | 'modal' | 'banner';
  context?: {
    projectType?: string;
    location?: { state?: string; county?: string };
    userType?: 'homeowner' | 'contractor';
    pageType?: string;
  };
  maxAds?: number;
  allowDismiss?: boolean;
}

export function EnhancedAdSystem({ 
  placement, 
  context, 
  maxAds = 1, 
  allowDismiss = true 
}: EnhancedAdSystemProps) {
  const [ads, setAds] = useState<AdContent[]>([]);
  const [dismissedAds, setDismissedAds] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchTargetedAds();
  }, [placement, context]);

  const fetchTargetedAds = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/ads/targeted', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          placement,
          context,
          maxAds,
          excludeIds: dismissedAds
        })
      });

      if (response.ok) {
        const adData = await response.json();
        setAds(Array.isArray(adData) ? adData : []);
      }
    } catch (error) {
      console.error('Error fetching ads:', error);
      // Fallback to contextual ads
      setAds(getContextualAds(placement, context, maxAds));
    } finally {
      setLoading(false);
    }
  };

  const handleAdClick = (ad: AdContent) => {
    // Track ad interaction for revenue attribution
    trackAdClick(ad.id, placement);
    window.open(ad.targetUrl, '_blank', 'noopener,noreferrer');
  };

  const handleAdDismiss = (adId: string) => {
    setDismissedAds(prev => [...prev, adId]);
    setAds(prev => prev.filter(ad => ad.id !== adId));

    // Track dismissal for optimization
    trackAdDismiss(adId, placement);
  };

  const trackAdClick = (adId: string, placement: string) => {
    fetch('/api/analytics/ad-click', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ adId, placement, timestamp: Date.now() })
    }).catch(console.error);
  };

  const trackAdDismiss = (adId: string, placement: string) => {
    fetch('/api/analytics/ad-dismiss', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ adId, placement, timestamp: Date.now() })
    }).catch(console.error);
  };

  if (loading || ads.length === 0) {
    return null;
  }

  const renderAd = (ad: AdContent) => {
    switch (ad.format) {
      case 'banner':
        return <BannerAd ad={ad} onDismiss={allowDismiss ? () => handleAdDismiss(ad.id) : undefined} onClick={() => handleAdClick(ad)} />;
      case 'card':
        return <CardAd ad={ad} onDismiss={allowDismiss ? () => handleAdDismiss(ad.id) : undefined} onClick={() => handleAdClick(ad)} />;
      case 'native':
        return <NativeAd ad={ad} onDismiss={allowDismiss ? () => handleAdDismiss(ad.id) : undefined} onClick={() => handleAdClick(ad)} />;
      default:
        return <CardAd ad={ad} onDismiss={allowDismiss ? () => handleAdDismiss(ad.id) : undefined} onClick={() => handleAdClick(ad)} />;
    }
  };

  return (
    <div className="ad-container" data-placement={placement}>
      {Array.isArray(ads) ? ads.map(renderAd) : null}
    </div>
  );
}

function BannerAd({ ad, onDismiss, onClick }: { ad: AdContent; onDismiss?: () => void; onClick: () => void }) {
  return (
    <div className="relative bg-gradient-to-r from-blue-600 to-blue-500 text-white rounded-lg p-4 mb-4 cursor-pointer hover:from-blue-700 hover:to-blue-600 transition-all" onClick={onClick}>
      {onDismiss && (
        <Button
          variant="ghost"
          size="sm"
          className="absolute top-2 right-2 text-white hover:bg-white/20"
          onClick={(e) => {
            e.stopPropagation();
            onDismiss();
          }}
        >
          <X className="h-4 w-4" />
        </Button>
      )}

      <div className="flex items-center justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <Badge variant="secondary" className="text-xs">Sponsored</Badge>
            <span className="text-sm opacity-90">{ad.advertiser}</span>
          </div>
          <h4 className="font-semibold text-lg mb-1">{ad.title}</h4>
          <p className="text-sm opacity-90 mb-3">{ad.description}</p>
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium">{ad.ctaText}</span>
            <ExternalLink className="h-4 w-4" />
          </div>
        </div>

        {ad.imageUrl && (
          <div className="ml-4 w-20 h-20 bg-white/10 rounded-lg flex-shrink-0 overflow-hidden">
            <img src={ad.imageUrl} alt={ad.title} className="w-full h-full object-cover" />
          </div>
        )}
      </div>
    </div>
  );
}

function CardAd({ ad, onDismiss, onClick }: { ad: AdContent; onDismiss?: () => void; onClick: () => void }) {
  return (
    <Card className="bg-navy-700 border-navy-600 hover:border-orange-500 transition-all cursor-pointer mb-4" onClick={onClick}>
      <CardContent className="p-4 relative">
        {onDismiss && (
          <Button
            variant="ghost"
            size="sm"
            className="absolute top-2 right-2 text-gray-400 hover:text-white"
            onClick={(e) => {
              e.stopPropagation();
              onDismiss();
            }}
          >
            <X className="h-4 w-4" />
          </Button>
        )}

        <div className="flex items-start gap-3">
          {ad.imageUrl && (
            <div className="w-16 h-16 bg-gray-300 rounded-lg flex-shrink-0 overflow-hidden">
              <img src={ad.imageUrl} alt={ad.title} className="w-full h-full object-cover" />
            </div>
          )}

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-2">
              <Badge variant="outline" className="text-xs border-orange-500 text-orange-500">
                {ad.isSponsored ? 'Sponsored' : 'Partner'}
              </Badge>
              <span className="text-gray-400 text-sm">{ad.advertiser}</span>
            </div>

            <h4 className="text-white font-medium mb-2">{ad.title}</h4>
            <p className="text-gray-300 text-sm mb-3 line-clamp-2">{ad.description}</p>

            <div className="flex items-center justify-between">
              <Button variant="outline" size="sm" className="border-orange-500 text-orange-500 hover:bg-orange-500 hover:text-white">
                {ad.ctaText}
              </Button>
              {ad.location && (
                <div className="flex items-center text-gray-400 text-xs">
                  <MapPin className="h-3 w-3 mr-1" />
                  {ad.location.county}, {ad.location.state}
                </div>
              )}
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function NativeAd({ ad, onDismiss, onClick }: { ad: AdContent; onDismiss?: () => void; onClick: () => void }) {
  return (
    <div className="bg-navy-600 rounded-lg p-4 mb-4 hover:bg-navy-500 transition-colors cursor-pointer relative" onClick={onClick}>
      {onDismiss && (
        <Button
          variant="ghost"
          size="sm"
          className="absolute top-2 right-2 text-gray-400 hover:text-white"
          onClick={(e) => {
            e.stopPropagation();
            onDismiss();
          }}
        >
          <X className="h-4 w-4" />
        </Button>
      )}

      <div className="flex items-start gap-3">
        <div className="w-12 h-12 bg-orange-500 rounded-full flex items-center justify-center text-white font-bold text-lg flex-shrink-0">
          {ad.advertiser.charAt(0)}
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-white font-medium">{ad.advertiser}</span>
