import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  FormDescription,
} from "@/components/ui/form";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { isUnauthorizedError } from "@/lib/authUtils";
import { apiRequest } from "@/lib/queryClient";
import { 
  ArrowLeft, 
  AlertCircle, 
  CheckCircle, 
  Home, 
  Shield,
  FileText,
  Award,
  MapPin,
  DollarSign,
  Star,
  Info
} from "lucide-react";

const realtorApplicationSchema = z.object({
  licenseNumber: z.string().min(5, "License number is required"),
  brokerageName: z.string().min(2, "Brokerage name is required"),
  mlsId: z.string().optional(),
  specializations: z.array(z.string()).min(1, "Select at least one specialization"),
  yearsExperience: z.string().min(1, "Years of experience is required"),
  licenseState: z.string().min(2, "License state is required"),
  licenseExpiration: z.string().min(1, "License expiration date is required"),
  serviceCounties: z.array(z.string()).min(1, "Select at least one service area"),
  serviceCities: z.array(z.string()).optional(),
  serviceZipCodes: z.array(z.string()).optional(),
});

type RealtorApplicationForm = z.infer<typeof realtorApplicationSchema>;

const realEstateSpecializations = [
  "Residential Sales",
  "Commercial Real Estate", 
  "Luxury Properties",
  "First-Time Homebuyers",
  "Investment Properties",
  "New Construction",
  "Condominiums",
  "Land/Lots",
  "Foreclosures/REO",
  "Short Sales",
  "Property Management",
  "Relocation Services"
];

const states = [
  "AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "FL", "GA",
  "HI", "ID", "IL", "IN", "IA", "KS", "KY", "LA", "ME", "MD",
  "MA", "MI", "MN", "MS", "MO", "MT", "NE", "NV", "NH", "NJ",
  "NM", "NY", "NC", "ND", "OH", "OK", "OR", "PA", "RI", "SC",
  "SD", "TN", "TX", "UT", "VT", "VA", "WA", "WV", "WI", "WY"
];

export default function RealtorApplication() {
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedSpecializations, setSelectedSpecializations] = useState<string[]>([]);
  const [serviceCounties, setServiceCounties] = useState<string[]>([]);

  const form = useForm<RealtorApplicationForm>({
    resolver: zodResolver(realtorApplicationSchema),
    defaultValues: {
      licenseNumber: "",
      brokerageName: "",
      mlsId: "",
      specializations: [],
      yearsExperience: "",
      licenseState: "",
      licenseExpiration: "",
      serviceCounties: [],
      serviceCities: [],
      serviceZipCodes: [],
    },
  });

  const submitApplicationMutation = useMutation({
    mutationFn: async (data: RealtorApplicationForm) => {
      return apiRequest("POST", "/api/realtor/application", {
        ...data,
        userId: user?.id,
        serviceAreas: {
          counties: serviceCounties,
          cities: data.serviceCities || [],
          zipCodes: data.serviceZipCodes || [],
        },
        specializations: selectedSpecializations,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });
      toast({
        title: "Application Submitted Successfully!",
        description: "Your realtor application has been submitted for review. You'll be notified once verified.",
      });
      form.reset();
    },
    onError: (error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Application Failed",
        description: "There was an error submitting your application. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: RealtorApplicationForm) => {
    submitApplicationMutation.mutate(data);
  };

  const handleSpecializationToggle = (specialization: string) => {
    setSelectedSpecializations(prev => 
      prev.includes(specialization) 
        ? prev.filter(s => s !== specialization)
        : [...prev, specialization]
    );
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
        <Card className="max-w-md">
          <CardContent className="p-6 text-center">
            <AlertCircle className="h-12 w-12 text-orange-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Login Required</h2>
            <p className="text-gray-600 mb-4">You need to be logged in to apply as a realtor.</p>
            <Button asChild className="bg-orange-600 hover:bg-orange-700">
              <Link href="/api/login">Log In</Link>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Button variant="ghost" asChild>
            <Link href="/marketplace" className="flex items-center gap-2">
              <ArrowLeft className="h-4 w-4" />
              Back to Marketplace
            </Link>
          </Button>
        </div>

        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2 flex items-center gap-2">
            <Home className="h-8 w-8 text-blue-500" />
            Realtor Network Application
          </h1>
          <p className="text-gray-400">
            Join our verified realtor network and sell properties with a professional badge
          </p>
        </div>

        {/* Benefits Section */}
        <Card className="mb-8 bg-gradient-to-r from-blue-900/20 to-indigo-900/20 border-blue-500/20">
          <CardContent className="p-6">
            <h3 className="text-xl font-semibold mb-4 flex items-center gap-2">
              <Star className="h-5 w-5 text-yellow-400" />
              Realtor Network Benefits
            </h3>
            <div className="grid md:grid-cols-2 gap-4">
              <div className="flex items-start gap-3">
                <Shield className="h-5 w-5 text-blue-400 mt-1" />
                <div>
                  <h4 className="font-medium">Verified Realtor Badge</h4>
                  <p className="text-sm text-gray-300">Display your professional credentials</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <MapPin className="h-5 w-5 text-green-400 mt-1" />
                <div>
                  <h4 className="font-medium">Geographic Specialization</h4>
                  <p className="text-sm text-gray-300">Target your service areas</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <DollarSign className="h-5 w-5 text-emerald-400 mt-1" />
                <div>
                  <h4 className="font-medium">Professional Listings</h4>
                  <p className="text-sm text-gray-300">Higher conversion rates</p>
                </div>
              </div>
              <div className="flex items-start gap-3">
                <Award className="h-5 w-5 text-purple-400 mt-1" />
                <div>
                  <h4 className="font-medium">Trust & Credibility</h4>
                  <p className="text-sm text-gray-300">Build client confidence</p>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Application Form */}
        <Card className="bg-navy-800 border-navy-600">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="h-5 w-5 text-blue-500" />
              Realtor Verification Application
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* License Information */}
                <div className="space-y-4">
                  <h3 className="text-lg font-semibold text-blue-400">License Information</h3>

                  <div className="grid md:grid-cols-2 gap-6">
                    <FormField
                      control={form.control}
                      name="licenseNumber"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Real Estate License Number</FormLabel>
                          <FormControl>
                            <Input placeholder="Enter license number" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="licenseState"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>License State</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select state" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              {states.map((state) => (
                                <SelectItem key={state} value={state}>
                                  {state}
                                </SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>

                  <div className="grid md:grid-cols-2 gap-6">
                    <FormField
                      control={form.control}
                      name="licenseExpiration"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>License Expiration Date</FormLabel>
                          <FormControl>
                            <Input type="date" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="yearsExperience"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Years of Experience</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="Years" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                </div>

                {/* Brokerage Information */}
                <div className="space-y-4">
                  <h3 className="text-lg font-semibold text-blue-400">Brokerage Information</h3>

                  <div className="grid md:grid-cols-2 gap-6">
                    <FormField
                      control={form.control}
                      name="brokerageName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Brokerage Name</FormLabel>
                          <FormControl>
                            <Input placeholder="Enter brokerage name" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <FormField
                      control={form.control}
                      name="mlsId"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>MLS ID (Optional)</FormLabel>
                          <FormControl>
                            <Input placeholder="Enter MLS ID" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                </div>

                {/* Specializations */}
                <div className="space-y-4">
                  <h3 className="text-lg font-semibold text-blue-400">Specializations</h3>
                  <p className="text-sm text-gray-400">Select your areas of expertise</p>

                  <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                    {realEstateSpecializations.map((specialization) => (
                      <div key={specialization} className="flex items-center space-x-2">
                        <Checkbox
                          id={specialization}
                          checked={selectedSpecializations.includes(specialization)}
                          onCheckedChange={() => handleSpecializationToggle(specialization)}
                        />
                        <label 
                          htmlFor={specialization}
                          className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                        >
                          {specialization}
                        </label>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Service Areas */}
                <div className="space-y-4">
                  <h3 className="text-lg font-semibold text-blue-400">Service Areas</h3>
                  <p className="text-sm text-gray-400">Define your geographic coverage</p>

                  <FormField
                    control={form.control}
                    name="serviceCounties"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Primary Counties (comma-separated)</FormLabel>
                        <FormControl>
                          <Input 
                            placeholder="e.g., Los Angeles County, Orange County"
                            value={serviceCounties.join(", ")}
                            onChange={(e) => setServiceCounties(e.target.value.split(",").map(s => s.trim()))}
                          />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                {/* Professional Tips */}
                <div className="mt-8 p-6 bg-gradient-to-r from-blue-100 to-indigo-100 dark:from-blue-900/20 dark:to-indigo-900/20 rounded-lg">
                  <div className="flex items-start gap-4">
                    <div className="flex-shrink-0">
                      <Info className="h-6 w-6 text-blue-600" />
                    </div>
                    <div className="flex-1">
                      <h4 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">
                        Application Tips
                      </h4>
                      <ul className="text-blue-800 dark:text-blue-200 text-sm space-y-1">
                        <li>• Ensure your license is current and in good standing</li>
                        <li>• Provide accurate brokerage affiliation information</li>
                        <li>• Select specializations that match your expertise</li>
                        <li>• Define realistic service areas for better connection quality</li>
                        <li>• Verification typically takes 2-3 business days</li>
                      </ul>
                    </div>
                  </div>
                </div>

                {/* Action Buttons */}
                <div className="flex gap-4 pt-4">
                  <Button
                    type="submit"
                    disabled={submitApplicationMutation.isPending || selectedSpecializations.length === 0}
                    className="bg-blue-600 hover:bg-blue-700 flex-1"
                  >
                    {submitApplicationMutation.isPending ? (
                      <>
                        <Shield className="h-4 w-4 mr-2 animate-spin" />
                        Submitting Application...
                      </>
                    ) : (
                      <>
                        <CheckCircle className="h-4 w-4 mr-2" />
                        Submit Application
                      </>
                    )}
                  </Button>

                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => form.reset()}
                    disabled={submitApplicationMutation.isPending}
                  >
                    Clear Form
                  </Button>
                </div>
              </form>
            </Form>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/UserSatisfactionWi.content:
import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { 
  Star, 
  Smile, 
  Meh, 
  Frown,
  ThumbsUp,
  MessageSquare,
  X,
  Gift
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";

interface UserSatisfactionWidgetProps {
  onClose?: () => void;
  trigger?: 'time' | 'action' | 'manual';
  context?: string;
}

export function UserSatisfactionWidget({ 
  onClose,
  trigger = 'manual',
  context = 'general'
}: UserSatisfactionWidgetProps) {
  const [step, setStep] = useState<'rating' | 'feedback' | 'thanks'>('rating');
  const [rating, setRating] = useState(0);
  const [satisfaction, setSatisfaction] = useState<'happy' | 'neutral' | 'sad' | null>(null);
  const [feedback, setFeedback] = useState('');
  const { toast } = useToast();

  const handleRatingSubmit = () => {
    if (rating > 0 || satisfaction) {
      setStep('feedback');
    }
  };

  const handleFeedbackSubmit = async () => {
    // Submit feedback to backend
    try {
      await fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          rating,
          satisfaction,
          feedback,
          context,
          trigger
        })
      });

      setStep('thanks');

      // Show reward if high rating
      if (rating >= 4) {
        toast({
          title: "Thank you! 🎉",
          description: "Your positive feedback helps us improve. Check your notifications for a small reward!",
        });
      }
    } catch (error) {
      toast({
        title: "Thanks for your feedback!",
        description: "Your input helps us make TradeScout better.",
      });
      setStep('thanks');
    }
  };

  const getSatisfactionColor = (type: string) => {
    switch (type) {
      case 'happy': return 'text-green-500 bg-green-500/20 border-green-500/30';
      case 'neutral': return 'text-yellow-500 bg-yellow-500/20 border-yellow-500/30';
      case 'sad': return 'text-red-500 bg-red-500/20 border-red-500/30';
      default: return 'text-gray-500 bg-gray-500/20 border-gray-500/30';
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-50 w-80 notification-bounce">
      <Card className="bg-navy-700 border-navy-600 shadow-2xl">
        <CardContent className="p-6">
          {/* Close Button */}
          {onClose && (
            <button
              onClick={onClose}
              className="absolute top-2 right-2 text-gray-400 hover:text-white"
            >
              <X className="h-4 w-4" />
            </button>
          )}

          {step === 'rating' && (
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-white">
                How was your experience?
              </h3>

              {/* Star Rating */}
              <div className="space-y-2">
                <p className="text-sm text-gray-300">Rate your experience:</p>
                <div className="flex space-x-1">
                  {[1, 2, 3, 4, 5].map((star) => (
                    <button
                      key={star}
                      onClick={() => setRating(star)}
                      className="transition-all hover:scale-110"
                    >
                      <Star
                        className={cn(
                          "h-6 w-6",
                          star <= rating ? "text-yellow-500 fill-current" : "text-gray-500"
                        )}
                      />
                    </button>
                  ))}
                </div>
              </div>

              {/* Emoji Satisfaction */}
              <div className="space-y-2">
                <p className="text-sm text-gray-300">Quick feedback:</p>
                <div className="flex space-x-3">
                  {[
                    { type: 'happy', icon: Smile, label: 'Great!' },
                    { type: 'neutral', icon: Meh, label: 'Okay' },
                    { type: 'sad', icon: Frown, label: 'Poor' }
                  ].map(({ type, icon: Icon, label }) => (
                    <button
                      key={type}
                      onClick={() => setSatisfaction(type as any)}
                      className={cn(
                        "flex flex-col items-center p-3 rounded-lg border transition-all",
                        satisfaction === type 
                          ? getSatisfactionColor(type)
                          : "text-gray-500 bg-gray-500/10 border-gray-500/20 hover:border-gray-500/40"
                      )}
                    >
                      <Icon className="h-6 w-6 mb-1" />
                      <span className="text-xs">{label}</span>
                    </button>
                  ))}
                </div>
              </div>

              <Button 
                onClick={handleRatingSubmit}
                disabled={rating === 0 && !satisfaction}
                className="w-full"
              >
                Continue
              </Button>
            </div>
          )}

          {step === 'feedback' && (
            <div className="space-y-4">
              <h3 className="text-lg font-semibold text-white">
                Tell us more (optional)
              </h3>

              <textarea
                value={feedback}
                onChange={(e) => setFeedback(e.target.value)}
                placeholder="What could we improve? Any specific features you love?"
                className="w-full p-3 bg-navy-800 border border-navy-600 rounded-lg text-white text-sm resize-none"
                rows={4}
              />

              <div className="flex space-x-2">
                <Button 
                  onClick={() => setStep('rating')}
                  variant="outline"
                  size="sm"
                  className="flex-1"
                >
                  Back
                </Button>
                <Button 
                  onClick={handleFeedbackSubmit}
                  size="sm"
                  className="flex-1"
                >
                  Submit
                </Button>
              </div>
            </div>
          )}

          {step === 'thanks' && (
            <div className="text-center space-y-4">
              <div className="flex justify-center">
                {rating >= 4 ? (
                  <div className="w-16 h-16 bg-green-500/20 rounded-full flex items-center justify-center">
                    <Gift className="h-8 w-8 text-green-500" />
                  </div>
                ) : (
                  <div className="w-16 h-16 bg-blue-500/20 rounded-full flex items-center justify-center">
                    <ThumbsUp className="h-8 w-8 text-blue-500" />
                  </div>
                )}
              </div>

              <div>
                <h3 className="text-lg font-semibold text-white mb-2">
                  Thank you!
                </h3>
                <p className="text-sm text-gray-300">
                  Your feedback helps us make TradeScout better for everyone.
                </p>
                {rating >= 4 && (
                  <Badge className="bg-green-500/20 text-green-400 mt-2">
                    <Gift className="h-3 w-3 mr-1" />
                    Reward earned!
                  </Badge>
                )}
              </div>

              <Button 
                onClick={onClose}
                size="sm" 
                className="w-full"
              >
                Done
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// Hook to trigger satisfaction widget based on user actions
export function useSatisfactionTracking() {
  const [showWidget, setShowWidget] = useState(false);

  const triggerSatisfactionWidget = (context?: string) => {
    // Show widget based on certain conditions
    const shouldShow = Math.random() < 0.3; // 30% chance
    if (shouldShow) {
      setShowWidget(true);
    }
  };

  useEffect(() => {
    // Trigger after certain time on site
    const timer = setTimeout(() => {
      triggerSatisfactionWidget('time-based');
    }, 120000); // 2 minutes

    return () => clearTimeout(timer);
  }, []);

  return {
    showWidget,
    setShowWidget,
    triggerSatisfactionWidget
  };
}

server/routes/admin/ui-issues.ts.content:
import type { Express } from "express";
import { isAuthenticated } from "../../auth";
import { aiCodeFixingService } from "../../ai-code-fixes";

interface UIIssue {
  id: string;
  type: 'bug' | 'ux_issue' | 'performance' | 'accessibility' | 'layout';
  severity: 'low' | 'medium' | 'high' | 'critical';
  title: string;
  description: string;
  element?: string;
  location: string;
  timestamp: Date;
  userAgent: string;
  suggestions: string[];
  status?: 'new' | 'investigating' | 'resolved' | 'ignored';
}

interface UIIssuesStore {
  issues: UIIssue[];
  stats: {
    totalIssues: number;
    resolvedIssues: number;
    criticalIssues: number;
    lastAnalysis: Date;
  };
}

// In-memory store for demo - in production, use database
let uiIssuesStore: UIIssuesStore = {
  issues: [],
  stats: {
    totalIssues: 0,
    resolvedIssues: 0,
    criticalIssues: 0,
    lastAnalysis: new Date()
  }
};

export function registerUIIssuesRoutes(app: Express) {
  // Get all UI issues and stats
  app.get("/api/admin/ui-issues", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;

      // Only allow admin users to access UI monitoring
      if (!user || !['head_admin', 'ops_admin'].includes(user.role)) {
        return res.status(403).json({ message: "Admin access required" });
      }

      // Calculate stats
      const totalIssues = uiIssuesStore.issues.length;
      const resolvedIssues = uiIssuesStore.issues.filter(issue => issue.status === 'resolved').length;
      const criticalIssues = uiIssuesStore.issues.filter(issue => issue.severity === 'critical').length;

      // Group issues by type and severity
      const byType: Record<string, number> = {};
      const bySeverity: Record<string, number> = {};
      const byStatus: Record<string, number> = {};

      uiIssuesStore.issues.forEach(issue => {
        byType[issue.type] = (byType[issue.type] || 0) + 1;
        bySeverity[issue.severity] = (bySeverity[issue.severity] || 0) + 1;
        byStatus[issue.status || 'new'] = (byStatus[issue.status || 'new'] || 0) + 1;
      });

      const response = {
        issues: uiIssuesStore.issues.sort((a, b) => 
          new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
        ),
        stats: {
          totalIssues,
          resolvedIssues,
          criticalIssues,
          lastAnalysis: new Date()
        },
        summary: {
          total: totalIssues,
          byType,
          bySeverity,
          byStatus
        }
      };

      res.json(response);
    } catch (error) {
      console.error("Error fetching UI issues:", error);
      res.status(500).json({ message: "Failed to fetch UI issues" });
    }
  });

  // Submit new UI issues from client-side monitoring
  app.post("/api/admin/ui-issues", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;

      // Only allow admin users to submit issues
      if (!user || !['head_admin', 'ops_admin'].includes(user.role)) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { issues } = req.body;

      if (!Array.isArray(issues)) {
        return res.status(400).json({ message: "Issues must be an array" });
      }

      // Process and store new issues
      const newIssues = issues.map(issue => ({
        ...issue,
        id: issue.id || `issue-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        timestamp: new Date(issue.timestamp || new Date()),
        status: issue.status || 'new'
      }));

      // Add to store (avoid duplicates)
      newIssues.forEach(newIssue => {
        const existingIssue = uiIssuesStore.issues.find(existing => 
          existing.title === newIssue.title && 
          existing.location === newIssue.location &&
          Math.abs(new Date(existing.timestamp).getTime() - new Date(newIssue.timestamp).getTime()) < 60000
        );

        if (!existingIssue) {
          uiIssuesStore.issues.push(newIssue);
        }
      });

      // Update stats
      uiIssuesStore.stats.lastAnalysis = new Date();
      uiIssuesStore.stats.totalIssues = uiIssuesStore.issues.length;
      uiIssuesStore.stats.resolvedIssues = uiIssuesStore.issues.filter(issue => issue.status === 'resolved').length;
      uiIssuesStore.stats.criticalIssues = uiIssuesStore.issues.filter(issue => issue.severity === 'critical').length;

      console.log(`📊 AI Monitoring: Received ${newIssues.length} new issues`);

      // Auto-analyze new issues for potential fixes
      for (const issue of newIssues) {
        if (issue.severity === 'high' || issue.severity === 'critical') {
          try {
            const fix = await aiCodeFixingService.analyzeAndFixIssue(issue.description, issue.location);
            if (fix && fix.confidence >= 0.9) {
              console.log(`🤖 AI Generated High-Confidence Fix: ${fix.description}`);
              // Auto-apply critical fixes with very high confidence
              if (issue.severity === 'critical' && fix.confidence >= 0.95) {
                setTimeout(() => aiCodeFixingService.applyFix(fix.id), 2000);
                console.log(`🚀 Auto-Applied Critical Fix: ${fix.description}`);
              }
            }
          } catch (error) {
            console.error(`AI Fix Analysis Error for issue ${issue.id}:`, error);
          }
        }
      }

      res.json({ 
        message: "Issues received successfully",
        count: newIssues.length,
        total: uiIssuesStore.issues.length
      });
    } catch (error) {
      console.error("Error storing UI issues:", error);
      res.status(500).json({ message: "Failed to store UI issues" });
    }
  });

  // Update issue status
  app.patch("/api/admin/ui-issues/:issueId", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;

      if (!user || !['head_admin', 'ops_admin'].includes(user.role)) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { issueId } = req.params;
      const { status } = req.body;

      const issue = uiIssuesStore.issues.find(issue => issue.id === issueId);

      if (!issue) {
        return res.status(404).json({ message: "Issue not found" });
      }

      issue.status = status;

      // Update stats
      uiIssuesStore.stats.resolvedIssues = uiIssuesStore.issues.filter(issue => issue.status === 'resolved').length;

      res.json({ message: "Issue updated successfully", issue });
    } catch (error) {
      console.error("Error updating UI issue:", error);
      res.status(500).json({ message: "Failed to update UI issue" });
    }
  });

  // Delete issue
  app.delete("/api/admin/ui-issues/:issueId", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;

      if (!user || !['head_admin', 'ops_admin'].includes(user.role)) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { issueId } = req.params;

      const issueIndex = uiIssuesStore.issues.findIndex(issue => issue.id === issueId);

      if (issueIndex === -1) {
        return res.status(404).json({ message: "Issue not found" });
      }

      uiIssuesStore.issues.splice(issueIndex, 1);

      // Update stats
      uiIssuesStore.stats.totalIssues = uiIssuesStore.issues.length;
      uiIssuesStore.stats.resolvedIssues = uiIssuesStore.issues.filter(issue => issue.status === 'resolved').length;
      uiIssuesStore.stats.criticalIssues = uiIssuesStore.issues.filter(issue => issue.severity === 'critical').length;

      res.json({ message: "Issue deleted successfully" });
    } catch (error) {
      console.error("Error deleting UI issue:", error);
      res.status(500).json({ message: "Failed to delete UI issue" });
    }
  });

  // Get AI analysis and recommendations
  app.get("/api/admin/ui-analysis", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user;

      if (!user || !['head_admin', 'ops_admin'].includes(user.role)) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const issues = uiIssuesStore.issues;
      const totalIssues = issues.length;
      const resolvedIssues = issues.filter(issue => issue.status === 'resolved').length;
      const criticalIssues = issues.filter(issue => issue.severity === 'critical').length;
      const unresolvedIssues = totalIssues - resolvedIssues;

      // Calculate resolution rate
      const resolutionRate = totalIssues > 0 ? ((resolvedIssues / totalIssues) * 100).toFixed(1) : '0';

      // Analyze patterns
      const pageIssues: Record<string, number> = {};
      const typeCount: Record<string, number> = {};
      const elementIssues: Record<string, number> = {};

      issues.forEach(issue => {
        // Count issues per page
        pageIssues[issue.location] = (pageIssues[issue.location] || 0) + 1;

        // Count by type
        typeCount[issue.type] = (typeCount[issue.type] || 0) + 1;

        // Count by element
        if (issue.element) {
          elementIssues[issue.element] = (elementIssues[issue.element] || 0) + 1;
        }
      });

      // Get top problematic pages
      const topProblematicPages = Object.entries(pageIssues)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 5)
        .map(([page, count]) => ({ page, issueCount: count }));

      // Get common problematic elements
      const commonElements = Object.entries(elementIssues)
        .sort(([,a], [,b]) => b - a)
        .slice(0, 5)
        .map(([element, count]) => ({ element, issueCount: count }));

      // Generate priorities
      const priorities = [];

      if (criticalIssues > 0) {
        priorities.push({
          level: 'critical',
          title: 'Critical Issues Need Immediate Attention',
          description: `${criticalIssues} critical issues detected that may impact user experience`,
          action: 'Review and fix critical issues first'
        });
      }

      if (unresolvedIssues > 10) {
        priorities.push({
          level: 'high',
          title: 'High Volume of Unresolved Issues',
          description: `${unresolvedIssues} issues remain unresolved`,
          action: 'Prioritize issue resolution workflow'
        });
      }

      if (typeCount.accessibility > 0) {
        priorities.push({
          level: 'medium',
          title: 'Accessibility Improvements Needed',
          description: `${typeCount.accessibility} accessibility issues found`,
          action: 'Improve site accessibility for all users'
        });
      }

      // Generate recommendations
      const recommendations = [
        'Regularly monitor and address critical issues to maintain user experience',
        'Implement automated testing to catch issues before they reach users',
        'Focus on the most problematic pages to maximize impact',
        'Set up alerts for critical and high-severity issues',
        'Review accessibility standards compliance regularly'
      ];

      // Add specific recommendations based on patterns
      if (typeCount.performance > 0) {
        recommendations.push('Optimize page load times and JavaScript performance');
      }

      if (typeCount.ux_issue > 0) {
        recommendations.push('Conduct user testing to identify UX pain points');
      }

      if (topProblematicPages.length > 0) {
        recommendations.push(`Focus attention on ${topProblematicPages[0].page} which has the most issues`);
      }

      const analysis = {
        summary: {
          totalIssues,
          criticalIssues,
          unresolvedIssues,
          resolutionRate
        },
        patterns: {
          topProblematicPages,
          commonIssueTypes: typeCount,
          commonElements
        },
        priorities,
        recommendations
      };

      res.json(analysis);
    } catch (error) {
      console.error("Error generating UI analysis:", error);
      res.status(500).json({ message: "Failed to generate analysis" });
    }
  });
}

