import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";
import { Facebook, User, UserPlus, LogIn } from "lucide-react";
import { useLocation } from "wouter";

interface AuthButtonsProps {
  title?: string;
  description?: string;
  showSignUp?: boolean;
  showGuestOption?: boolean;
  onGuestContinue?: () => void;
  className?: string;
}

export function AuthButtons({ 
  title = "Join TradeScout", 
  description = "Connect with verified contractors or grow your business",
  showSignUp = true,
  showGuestOption = true,
  onGuestContinue,
  className = ""
}: AuthButtonsProps) {
  const [, setLocation] = useLocation();

  const handleFacebookLogin = () => {
    // Facebook auth is available - redirect to the endpoint
    window.location.href = "/api/auth/facebook";
  };

  const handleGoogleLogin = () => {
    // Check if Google auth is available, otherwise show error
    try {
      if (process.env.NODE_ENV === 'development') {
        // In development, show message that OAuth needs to be configured
        alert("Google OAuth is not configured. Please check server configuration.");
        return;
      }
      window.location.href = "/auth/google";
    } catch (error) {
      console.error("Google login not available:", error);
      alert("Google login is currently unavailable. Please try email login.");
    }
  };

  const handleEmailSignUp = () => {
    setLocation("/register");
  };

  const handleEmailLogin = () => {
    setLocation("/login");
  };

  return (
    <Card className={`bg-navy-800 border-navy-700 ${className}`}>
      <CardHeader className="text-center">
        <CardTitle className="text-white text-xl">{title}</CardTitle>
        <CardDescription className="text-gray-300">{description}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Social Login Buttons */}
        <div className="space-y-2 md:space-y-3">
          <Button
            onClick={handleFacebookLogin}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 md:py-6 text-sm md:text-base"
          >
            <Facebook className="w-5 h-5 mr-3" />
            Continue with Facebook
          </Button>

          <Button
            onClick={handleGoogleLogin}
            variant="outline"
            className="w-full border-gray-600 text-gray-200 hover:bg-gray-700 font-medium py-3 md:py-6 text-sm md:text-base"
          >
            <svg className="w-5 h-5 mr-3" viewBox="0 0 24 24">
              <path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
              <path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
              <path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
              <path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
            </svg>
            Continue with Google
          </Button>
        </div>

        {/* Divider */}
        <div className="relative">
          <Separator className="bg-navy-600" />
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="bg-navy-800 px-3 text-sm text-gray-400">or</span>
          </div>
        </div>

        {/* Email Options */}
        <div className="space-y-3">
          {showSignUp && (
            <Button
              onClick={handleEmailSignUp}
              className="w-full bg-orange-500 hover:bg-orange-600 text-white font-medium py-6 text-base"
            >
              <UserPlus className="w-5 h-5 mr-3" />
              Create Account with Email
            </Button>
