import { Badge } from "@/components/ui/badge";
import { getRoleDisplayName, ROLE_HIERARCHY } from "@shared/roles";
import type { UserRole } from "@shared/roles";
import { Shield, Crown, Star, Users, Wrench, Home, Building } from "lucide-react";

interface RoleBadgeProps {
  role: UserRole;
  showIcon?: boolean;
  variant?: "default" | "secondary" | "destructive" | "outline";
  size?: "sm" | "md" | "lg";
}

function getRoleIcon(role: UserRole) {
  const level = ROLE_HIERARCHY[role];

  if (level >= 90) return <Crown className="h-3 w-3" />; // Super/Head Admin
  if (level >= 50) return <Shield className="h-3 w-3" />; // Admin/Moderator
  if (level >= 30) return <Star className="h-3 w-3" />; // Staff
  if (level >= 20) return <Users className="h-3 w-3" />; // Community
  if (level >= 10) return <Wrench className="h-3 w-3" />; // Service Provider
  return <Home className="h-3 w-3" />; // Customer
}

function getRoleVariant(role: UserRole): "default" | "secondary" | "destructive" | "outline" {
  const level = ROLE_HIERARCHY[role];

  if (level >= 90) return "destructive"; // Super/Head Admin - Red
  if (level >= 50) return "default"; // Admin/Moderator - Primary
  if (level >= 30) return "secondary"; // Staff - Secondary
  if (level >= 20) return "outline"; // Community - Outline
  return "secondary"; // Others - Secondary
}

function getRoleColor(role: UserRole): string {
  const level = ROLE_HIERARCHY[role];

  if (level >= 100) return "bg-red-600 text-white"; // Head Admin
  if (level >= 90) return "bg-red-500 text-white"; // Super Admin
  if (level >= 70) return "bg-purple-600 text-white"; // Ops Admin
  if (level >= 50) return "bg-blue-600 text-white"; // Moderator
  if (level >= 40) return "bg-green-600 text-white"; // Senior Staff
  if (level >= 30) return "bg-yellow-600 text-black"; // Staff
  if (level >= 25) return "bg-orange-600 text-white"; // Community Leader
  if (level >= 20) return "bg-gray-600 text-white"; // Community
  if (level >= 15) return "bg-indigo-600 text-white"; // Accelerator
  if (level >= 10) return "bg-teal-600 text-white"; // Service Provider
  return "bg-slate-600 text-white"; // Customer
}

export function RoleBadge({ 
  role, 
  showIcon = true, 
  variant,
  size = "md"
}: RoleBadgeProps) {
  const displayName = getRoleDisplayName(role);
  const icon = showIcon ? getRoleIcon(role) : null;
  const badgeVariant = variant || getRoleVariant(role);

  const sizeClasses = {
    sm: "text-xs px-1.5 py-0.5",
    md: "text-sm px-2 py-1", 
    lg: "text-base px-3 py-1.5"
  };

  return (
    <Badge 
      variant={badgeVariant}
      className={`${sizeClasses[size]} ${getRoleColor(role)} flex items-center gap-1 font-medium`}
    >
      {icon}
      {displayName}
    </Badge>
  );
}

// Role hierarchy indicator component
interface RoleHierarchyProps {
  role: UserRole;
  showLevel?: boolean;
}

export function RoleHierarchy({ role, showLevel = false }: RoleHierarchyProps) {
  const level = ROLE_HIERARCHY[role];
  const maxLevel = 5;
  const filledLevels = Math.min(Math.floor(level / 20), maxLevel);

  return (
    <div className="flex items-center gap-1">
      {Array.from({ length: maxLevel }).map((_, i) => (
        <div
          key={i}
          className={`h-2 w-2 rounded-full ${
            i < filledLevels 
              ? level >= 90 ? "bg-red-500" 
                : level >= 50 ? "bg-blue-500"
                : level >= 30 ? "bg-green-500"
                : level >= 20 ? "bg-yellow-500"
                : "bg-gray-500"
              : "bg-gray-300"
          }`}
        />
      ))}
      {showLevel && (
        <span className="text-xs text-muted-foreground ml-1">
          Level {level}
        </span>
      )}
    </div>
  );
}

// Permission indicator component
interface PermissionIndicatorProps {
  hasPermission: boolean;
  permissionName: string;
  size?: "sm" | "md";
}

export function PermissionIndicator({ 
  hasPermission, 
  permissionName,
  size = "md"
}: PermissionIndicatorProps) {
  const sizeClasses = {
    sm: "h-3 w-3",
    md: "h-4 w-4"
  };

  return (
    <div className="flex items-center gap-1">
      <div
        className={`${sizeClasses[size]} rounded-full ${
          hasPermission ? "bg-green-500" : "bg-red-500"
        }`}
      />
      <span className={`${size === "sm" ? "text-xs" : "text-sm"} text-muted-foreground`}>
        {permissionName}
      </span>
    </div>
  );
}

client/src/components/ui/toggle-group.ts.content:
"use client"

import * as React from "react"
import * as ToggleGroupPrimitive from "@radix-ui/react-toggle-group"
import { type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"
import { toggleVariants } from "@/components/ui/toggle"

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({
  size: "default",
  variant: "default",
})

const ToggleGroup = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Root> &
    VariantProps<typeof toggleVariants>
>(({ className, variant, size, children, ...props }, ref) => (
  <ToggleGroupPrimitive.Root
    ref={ref}
    className={cn("flex items-center justify-center gap-1", className)}
    {...props}
  >
    <ToggleGroupContext.Provider value={{ variant, size }}>
      {children}
    </ToggleGroupContext.Provider>
  </ToggleGroupPrimitive.Root>
))

ToggleGroup.displayName = ToggleGroupPrimitive.Root.displayName

const ToggleGroupItem = React.forwardRef<
  React.ElementRef<typeof ToggleGroupPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof ToggleGroupPrimitive.Item> &
    VariantProps<typeof toggleVariants>
>(({ className, children, variant, size, ...props }, ref) => {
  const context = React.useContext(ToggleGroupContext)

  return (
    <ToggleGroupPrimitive.Item
      ref={ref}
      className={cn(
        toggleVariants({
          variant: context.variant || variant,
          size: context.size || size,
        }),
        className
      )}
      {...props}
    >
      {children}
    </ToggleGroupPrimitive.Item>
  )
})

ToggleGroupItem.displayName = ToggleGroupPrimitive.Item.displayName

export { ToggleGroup, ToggleGroupItem }

client/src/pages/marketplace-listing.tsx.content:
import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { isUnauthorizedError } from "@/lib/authUtils";
import { apiRequest } from "@/lib/queryClient";
import { 
  ArrowLeft, 
  AlertCircle, 
  CheckCircle, 
  Package, 
  DollarSign, 
  MapPin,
  Clock,
  Shield,
  Eye,
  Info
} from "lucide-react";

const marketplaceListingSchema = z.object({
  title: z.string().min(5, "Title must be at least 5 characters"),
  description: z.string().min(20, "Description must be at least 20 characters"),
  price: z.string().min(1, "Price is required"),
  originalPrice: z.string().optional(),
  priceType: z.enum(["fixed", "negotiable", "obo", "trade"]),
  condition: z.enum(["new", "like_new", "good", "fair", "needs_repair"]),
  category: z.string().min(1, "Category is required"),
  subcategory: z.string().optional(),
  city: z.string().min(1, "City is required"),
  state: z.string().min(2, "State is required"),
  zipCode: z.string().min(5, "ZIP code is required"),
});

type MarketplaceListingForm = z.infer<typeof marketplaceListingSchema>;

export default function MarketplaceListing() {
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const form = useForm<MarketplaceListingForm>({
    resolver: zodResolver(marketplaceListingSchema),
    defaultValues: {
      title: "",
      description: "",
      price: "",
      originalPrice: "",
      priceType: "fixed",
      condition: "good",
      category: "",
      subcategory: "",
      city: "",
      state: "",
      zipCode: "",
    },
  });

  // Fetch marketplace categories
  const { data: categories = [], isLoading: categoriesLoading } = useQuery({
    queryKey: ["/api/marketplace/categories"],
    retry: false,
  });

  const createListingMutation = useMutation({
    mutationFn: async (data: MarketplaceListingForm) => {
      return apiRequest("POST", "/api/marketplace/listings", {
        ...data,
        sellerId: user?.id,
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/marketplace/listings"] });
      toast({
        title: "Listing Submitted Successfully!",
        description: "Your listing has been submitted for admin review. It will appear in the marketplace once approved.",
      });
      form.reset();
    },
    onError: (error) => {
      if (isUnauthorizedError(error)) {
        toast({
          title: "Unauthorized",
          description: "You are logged out. Logging in again...",
          variant: "destructive",
        });
        setTimeout(() => {
          window.location.href = "/api/login";
        }, 500);
        return;
      }
      toast({
        title: "Failed to Create Listing",
        description: "There was an error creating your listing. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: MarketplaceListingForm) => {
    createListingMutation.mutate(data);
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4">
        <Card className="max-w-md">
          <CardContent className="p-6 text-center">
            <AlertCircle className="h-12 w-12 text-orange-500 mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Login Required</h2>
            <p className="text-gray-600 mb-4">You need to be logged in to create marketplace listings.</p>
            <Button asChild className="bg-orange-600 hover:bg-orange-700">
              <Link href="/api/login">Log In</Link>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-white">
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Button variant="ghost" asChild>
            <Link href="/marketplace" className="flex items-center gap-2">
              <ArrowLeft className="h-4 w-4" />
              Back to Marketplace
            </Link>
          </Button>
        </div>

        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2 flex items-center gap-2">
            <Package className="h-8 w-8 text-orange-500" />
            Create Marketplace Listing
          </h1>
          <p className="text-gray-400">
            List your quality items for the TradeScout community to discover
          </p>
        </div>

        {/* Approval Notice */}
        <Alert className="mb-8 border-blue-500/20 bg-blue-500/10">
          <Info className="h-4 w-4 text-blue-400" />
          <AlertDescription className="text-blue-100">
            <strong>Approval Process:</strong> All listings require admin approval before going live. 
            This ensures quality standards and helps maintain our trusted marketplace environment. 
            You'll be notified once your listing is reviewed.
          </AlertDescription>
        </Alert>

        {/* Form */}
        <Card className="bg-navy-800 border-navy-600">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="h-5 w-5 text-green-500" />
              Listing Details
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Form {...form}>
              <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
                {/* Basic Information */}
                <div className="grid md:grid-cols-2 gap-6">
                  <FormField
                    control={form.control}
                    name="title"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Title</FormLabel>
                        <FormControl>
                          <Input placeholder="Enter item title" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="category"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Category</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue placeholder="Select category" />
                            </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                            {categoriesLoading ? (
                              <SelectItem value="loading">Loading...</SelectItem>
                            ) : (
                              (categories as any[]).map((category: any) => (
                                <SelectItem key={category.id} value={category.slug}>
                                  {category.name}
                                </SelectItem>
                              ))
                            )}
                          </SelectContent>
                        </Select>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                </div>

                <FormField
                  control={form.control}
                  name="description"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Description</FormLabel>
                      <FormControl>
                        <Textarea 
                          placeholder="Describe your item in detail. Include condition, features, and any relevant history..."
                          rows={4}
                          {...field} 
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Pricing & Condition */}
                <div className="grid md:grid-cols-3 gap-6">
                  <FormField
                    control={form.control}
                    name="price"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Price ($)</FormLabel>
                        <FormControl>
                          <Input placeholder="0.00" type="number" step="0.01" {...field} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />

                  <FormField
                    control={form.control}
                    name="priceType"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Price Type</FormLabel>
                        <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                          </FormControl>
