            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/social/ShareModal..content:
import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent } from "@/components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/hooks/useAuth";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import {
  Copy,
  Facebook,
  Twitter,
  Mail,
  MessageSquare,
  Share,
  ExternalLink,
  Check,
} from "lucide-react";

interface ShareModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  post: any;
}

export function ShareModal({ open, onOpenChange, post }: ShareModalProps) {
  const { user, isAuthenticated } = useAuth();
  const queryClient = useQueryClient();
  const { toast } = useToast();
  const [shareMessage, setShareMessage] = useState("");
  const [isCopied, setIsCopied] = useState(false);

  // Generate share URL
  const postUrl = `${window.location.origin}/community/post/${post.id}`;

  // Share mutation
  const shareMutation = useMutation({
    mutationFn: (data: { message?: string; shareType: string }) =>
      apiRequest('POST', `/api/social/posts/${post.id}/share`, data),
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Post shared successfully!",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/social/feed'] });
      onOpenChange(false);
      setShareMessage("");
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to share post",
        variant: "destructive",
      });
    },
  });

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(postUrl);
      setIsCopied(true);
      setTimeout(() => setIsCopied(false), 2000);
      toast({
        title: "Success",
        description: "Link copied to clipboard!",
      });
      // Track share
      shareMutation.mutate({ shareType: 'copy_link' });
    } catch (err) {
      toast({
        title: "Error",
        description: "Failed to copy link",
        variant: "destructive",
      });
    }
  };

  const handleSocialShare = (platform: string) => {
    const text = post.title ? `${post.title} - ${post.content.substring(0, 100)}...` : post.content.substring(0, 100);
    let shareUrl = "";

    switch (platform) {
      case 'facebook':
        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(postUrl)}`;
        break;
      case 'twitter':
        shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}&url=${encodeURIComponent(postUrl)}`;
        break;
      case 'email':
        shareUrl = `mailto:?subject=${encodeURIComponent(post.title || 'Check out this post')}&body=${encodeURIComponent(text + '\n\n' + postUrl)}`;
        break;
    }

    if (shareUrl) {
      window.open(shareUrl, '_blank', 'noopener,noreferrer');
      // Track share
      shareMutation.mutate({ shareType: platform });
    }
  };

  const handleInternalShare = () => {
    if (!isAuthenticated) {
      toast({
        title: "Login Required",
        description: "Please login to share posts",
        variant: "destructive",
      });
      return;
    }
    shareMutation.mutate({
      message: shareMessage,
      shareType: 'internal'
    });
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString();
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Share Post</DialogTitle>
          <DialogDescription>
            Share this post with your network or copy the link
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          {/* Post Preview */}
          <Card className="border-dashed">
            <CardContent className="p-4">
              <div className="flex items-start space-x-3">
                <Avatar className="h-8 w-8">
                  <AvatarImage src={post.author.profileImageUrl} />
                  <AvatarFallback className="bg-primary/10 text-primary text-xs">
                    {post.author.firstName?.[0]}{post.author.lastName?.[0]}
                  </AvatarFallback>
                </Avatar>
                <div className="flex-1 space-y-2">
                  <div className="flex items-center gap-2">
                    <span className="font-medium text-sm">
                      {post.author.firstName} {post.author.lastName}
                    </span>
                    <Badge variant="outline" className="text-xs">
                      {post.postType.replace('_', ' ')}
                    </Badge>
                    <span className="text-xs text-muted-foreground">
                      {formatDate(post.createdAt)}
                    </span>
                  </div>
                  {post.title && (
                    <h4 className="font-semibold text-sm">{post.title}</h4>
                  )}
                  <p className="text-sm text-muted-foreground line-clamp-3">
                    {post.content}
                  </p>
                  {post.tags && post.tags.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {post.tags.slice(0, 3).map((tag: string, index: number) => (
                        <Badge key={index} variant="outline" className="text-xs">
                          #{tag}
                        </Badge>
                      ))}
                      {post.tags.length > 3 && (
                        <span className="text-xs text-muted-foreground">
                          +{post.tags.length - 3} more
                        </span>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Copy Link */}
          <div className="space-y-2">
            <label className="text-sm font-medium">Share Link</label>
            <div className="flex space-x-2">
              <Input
                value={postUrl}
                readOnly
                className="flex-1"
              />
              <Button
                onClick={handleCopyLink}
                variant="outline"
                size="sm"
                className="flex items-center space-x-2"
              >
                {isCopied ? (
                  <Check className="h-4 w-4 text-green-500" />
                ) : (
                  <Copy className="h-4 w-4" />
                )}
                <span>{isCopied ? "Copied" : "Copy"}</span>
              </Button>
            </div>
          </div>

          {/* Social Sharing */}
          <div className="space-y-3">
            <label className="text-sm font-medium">Share on Social Media</label>
            <div className="flex space-x-3">
              <Button
                onClick={() => handleSocialShare('facebook')}
                variant="outline"
                size="sm"
                className="flex-1 flex items-center space-x-2"
              >
                <Facebook className="h-4 w-4 text-blue-600" />
                <span>Facebook</span>
              </Button>
              <Button
                onClick={() => handleSocialShare('twitter')}
                variant="outline"
                size="sm"
                className="flex-1 flex items-center space-x-2"
              >
                <Twitter className="h-4 w-4 text-blue-400" />
                <span>Twitter</span>
              </Button>
              <Button
                onClick={() => handleSocialShare('email')}
                variant="outline"
                size="sm"
                className="flex-1 flex items-center space-x-2"
              >
                <Mail className="h-4 w-4 text-gray-600" />
                <span>Email</span>
              </Button>
            </div>
          </div>

          {/* Internal Share */}
          {isAuthenticated && (
            <div className="space-y-3">
              <label className="text-sm font-medium">Share to Your Feed</label>
              <div className="space-y-3">
                <Textarea
                  placeholder="Add a comment about this post (optional)..."
                  value={shareMessage}
                  onChange={(e) => setShareMessage(e.target.value)}
                  rows={3}
                />
                <Button
                  onClick={handleInternalShare}
                  disabled={shareMutation.isPending}
                  className="w-full flex items-center space-x-2"
                >
                  <Share className="h-4 w-4" />
                  <span>
                    {shareMutation.isPending ? "Sharing..." : "Share to Your Feed"}
                  </span>
                </Button>
              </div>
            </div>
          )}

          {/* Share Stats */}
          {post.shareCount > 0 && (
            <div className="text-xs text-muted-foreground text-center">
              This post has been shared {post.shareCount} time{post.shareCount !== 1 ? 's' : ''}
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/admin/UserManageme.content:
import React, { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { queryClient, apiRequest } from '@/lib/queryClient';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { useToast } from '@/hooks/use-toast';
import { Search, UserPlus, Edit, Shield, Users, Crown, Eye, Building, Wrench, Car, Home, User, MoreHorizontal } from 'lucide-react';

interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  role: string;
  roles: string[];
  activeRole: string;
  profileImageUrl: string | null;
  emailVerified: boolean;
  addressVerified: boolean;
  createdAt: string;
  facebookId: string | null;
}

const AVAILABLE_ROLES = [
  { value: 'homeowner', label: 'Homeowner', icon: Home, color: 'bg-blue-500' },
  { value: 'contractor_user', label: 'Contractor', icon: Wrench, color: 'bg-orange-500' },
  { value: 'realtor', label: 'Realtor', icon: Building, color: 'bg-green-500' },
  { value: 'car_salesman', label: 'Car Salesman', icon: Car, color: 'bg-purple-500' },
  { value: 'helper', label: 'Helper', icon: Users, color: 'bg-cyan-500' },
  { value: 'moderator', label: 'Moderator', icon: Shield, color: 'bg-yellow-500' },
  { value: 'ops_admin', label: 'Admin', icon: Eye, color: 'bg-red-500' },
  { value: 'head_admin', label: 'Master Admin', icon: Crown, color: 'bg-gradient-to-r from-yellow-400 to-red-500' },
];

const ROLE_HIERARCHY = {
  'homeowner': 1,
  'helper': 2,
  'contractor_user': 3,
  'realtor': 4,
  'car_salesman': 4,
  'moderator': 5,
  'ops_admin': 6,
  'head_admin': 7
};

export default function UserManagement() {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [editingRoles, setEditingRoles] = useState<string[]>([]);
  const [newActiveRole, setNewActiveRole] = useState('');
  const { toast } = useToast();

  const { data: users, isLoading } = useQuery({
    queryKey: ['/api/admin/users'],
    retry: false,
  });

  const updateUserRoles = useMutation({
    mutationFn: async ({ userId, roles, activeRole }: { userId: string; roles: string[]; activeRole: string }) => {
      return apiRequest(`/api/admin/users/${userId}/roles`, {
        method: 'PATCH',
        body: { roles, activeRole }
      });
    },
    onSuccess: (data, variables) => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/users'] });
      toast({
        title: "Roles Updated",
        description: `Successfully updated user roles`,
      });
      setSelectedUser(null);
    },
    onError: (error) => {
      toast({
        title: "Update Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const impersonateUser = useMutation({
    mutationFn: async (userId: string) => {
      return apiRequest(`/api/admin/users/${userId}/impersonate`, {
        method: 'POST'
      });
    },
    onSuccess: () => {
      toast({
        title: "Impersonation Active",
        description: "You are now viewing the platform as this user",
      });
      setTimeout(() => window.location.reload(), 1000);
    },
    onError: (error) => {
      toast({
        title: "Impersonation Failed",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const filteredUsers = users?.filter((user: User) => 
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    `${user.firstName} ${user.lastName}`.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.roles?.some(role => role.toLowerCase().includes(searchTerm.toLowerCase()))
  ) || [];

  const getRoleInfo = (roleName: string) => {
    return AVAILABLE_ROLES.find(role => role.value === roleName) || 
           { value: roleName, label: roleName, icon: User, color: 'bg-gray-500' };
  };

  const handleRoleToggle = (role: string) => {
    if (editingRoles.includes(role)) {
      setEditingRoles(prev => prev.filter(r => r !== role));
    } else {
      setEditingRoles(prev => [...prev, role]);
    }
  };

  const handleSaveRoles = () => {
    if (selectedUser && editingRoles.length > 0) {
      const activeRole = newActiveRole || editingRoles[0];
      updateUserRoles.mutate({ 
        userId: selectedUser.id, 
        roles: editingRoles, 
        activeRole 
      });
    }
  };

  const openEditDialog = (user: User) => {
    setSelectedUser(user);
    setEditingRoles(user.roles || [user.role]);
    setNewActiveRole(user.activeRole || user.role);
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-8">
          <div className="animate-pulse">Loading users...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Users className="w-5 h-5" />
            User Management
          </CardTitle>
          <CardDescription>
            Manage user accounts, assign multiple roles, and control access levels
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 mb-6">
            <div className="flex-1 relative">
              <Search className="absolute left-3 top-3 w-4 h-4 text-gray-400" />
              <Input
                placeholder="Search users by email, name, or role..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
                data-testid="input-user-search"
              />
            </div>
            <Dialog>
              <DialogTrigger asChild>
                <Button data-testid="button-create-user">
                  <UserPlus className="w-4 h-4 mr-2" />
                  Create User
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Create New User</DialogTitle>
                </DialogHeader>
                <div className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    New user creation will be implemented here
                  </p>
                </div>
              </DialogContent>
            </Dialog>
          </div>

          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>User</TableHead>
                  <TableHead>Roles</TableHead>
                  <TableHead>Active Role</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredUsers.map((user: User) => {
                  const userRoles = user.roles || [user.role];
                  const activeRoleInfo = getRoleInfo(user.activeRole || user.role);

                  return (
                    <TableRow key={user.id} data-testid={`row-user-${user.id}`}>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          {user.profileImageUrl ? (
                            <img 
                              src={user.profileImageUrl} 
                              alt="Profile"
                              className="w-8 h-8 rounded-full object-cover"
                            />
                          ) : (
                            <div className="w-8 h-8 rounded-full bg-gray-200 flex items-center justify-center">
                              <User className="w-4 h-4 text-gray-500" />
                            </div>
                          )}
                          <div>
                            <div className="font-medium">{user.firstName} {user.lastName}</div>
                            <div className="text-sm text-muted-foreground">{user.email}</div>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-wrap gap-1">
                          {userRoles.map((role) => {
                            const roleInfo = getRoleInfo(role);
                            const Icon = roleInfo.icon;
                            return (
                              <Badge 
                                key={role} 
                                variant="secondary"
                                className={`${roleInfo.color} text-white text-xs`}
                              >
                                <Icon className="w-3 h-3 mr-1" />
                                {roleInfo.label}
                              </Badge>
                            );
                          })}
                        </div>
                      </TableCell>
                      <TableCell>
                        <Badge className={`${activeRoleInfo.color} text-white`}>
                          <activeRoleInfo.icon className="w-3 h-3 mr-1" />
                          {activeRoleInfo.label}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          {user.emailVerified && (
                            <Badge variant="outline" className="text-green-600 border-green-600">
                              Email ✓
                            </Badge>
                          )}
                          {user.addressVerified && (
                            <Badge variant="outline" className="text-blue-600 border-blue-600">
                              Address ✓
                            </Badge>
                          )}
                          {user.facebookId && (
                            <Badge variant="outline" className="text-blue-800 border-blue-800">
                              Facebook
                            </Badge>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => openEditDialog(user)}
                            data-testid={`button-edit-user-${user.id}`}
                          >
                            <Edit className="w-4 h-4" />
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => impersonateUser.mutate(user.id)}
                            data-testid={`button-impersonate-${user.id}`}
                          >
                            <Eye className="w-4 h-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Edit User Roles Dialog */}
      <Dialog open={!!selectedUser} onOpenChange={() => setSelectedUser(null)}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Edit User Roles</DialogTitle>
          </DialogHeader>
          {selectedUser && (
            <div className="space-y-6">
              <div className="flex items-center gap-3 p-4 bg-muted rounded-lg">
                {selectedUser.profileImageUrl ? (
                  <img 
                    src={selectedUser.profileImageUrl} 
                    alt="Profile"
