import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { TestTube, Bug, Settings, Eye, EyeOff, Trash2, RotateCcw } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { TestingErrorReportButton } from "@/components/TestingErrorReportButton";

export default function AdminTestingControls() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: settings = {}, isLoading } = useQuery({
    queryKey: ['/api/admin/testing-settings'],
  });

  const { data: reportStats = {}, isLoading: isLoadingStats } = useQuery({
    queryKey: ['/api/admin/error-report-stats'],
  });

  const settingsData = settings as any;
  const statsData = reportStats as any;

  const updateSettingsMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest("PATCH", "/api/admin/testing-settings", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/testing-settings'] });
      toast({
        title: "Settings Updated",
        description: "Testing controls have been updated successfully.",
      });
    },
  });

  const clearTestDataMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("DELETE", "/api/admin/clear-test-data");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/error-report-stats'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/error-reports'] });
      toast({
        title: "Test Data Cleared",
        description: "All test error reports have been removed.",
      });
    },
  });

  const generateTestDataMutation = useMutation({
    mutationFn: async () => {
      return apiRequest("POST", "/api/admin/generate-test-data");
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/error-report-stats'] });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/error-reports'] });
      toast({
        title: "Test Data Generated",
        description: "Sample error reports have been created for testing.",
      });
    },
  });

  const handleSettingChange = (key: string, value: boolean) => {
    updateSettingsMutation.mutate({ [key]: value });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-navy-900 text-white p-6">
        <div className="max-w-4xl mx-auto">
          <div className="animate-pulse space-y-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-navy-700 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-navy-900 text-white">
      <div className="max-w-4xl mx-auto p-6">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2 flex items-center gap-3">
            <TestTube className="h-8 w-8 text-orange-400" />
            Testing Controls
          </h1>
          <p className="text-gray-400">Manage testing features and bug reporting system settings</p>
        </div>

        {/* Bug Report System Controls */}
        <Card className="bg-navy-700 border-navy-600 mb-6">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Bug className="h-5 w-5 text-orange-400" />
              Bug Report System
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            {/* System Status */}
            <div className="flex items-center justify-between">
              <div>
                <Label className="text-gray-300 text-base font-semibold">Enable Bug Report System</Label>
                <p className="text-gray-400 text-sm">Show bug report buttons throughout the application</p>
              </div>
              <Switch
                checked={settingsData.bugReportEnabled ?? true}
                onCheckedChange={(checked) => handleSettingChange('bugReportEnabled', checked)}
              />
            </div>

            <Separator className="bg-navy-600" />

            {/* Testing Mode */}
            <div className="flex items-center justify-between">
              <div>
                <Label className="text-gray-300 text-base font-semibold">Testing Mode</Label>
                <p className="text-gray-400 text-sm">Show enhanced testing features and sample data generation</p>
              </div>
              <Switch
                checked={settingsData.testingModeEnabled ?? false}
                onCheckedChange={(checked) => handleSettingChange('testingModeEnabled', checked)}
              />
            </div>

            {/* Banner Display */}
            <div className="flex items-center justify-between">
              <div>
                <Label className="text-gray-300 text-base font-semibold">Show Testing Banner</Label>
                <p className="text-gray-400 text-sm">Display prominent testing banner on landing page</p>
              </div>
              <Switch
                checked={settingsData.showTestingBanner ?? false}
                onCheckedChange={(checked) => handleSettingChange('showTestingBanner', checked)}
              />
            </div>

            {/* Test Component Preview */}
            <div className="bg-navy-800 border border-navy-600 rounded-lg p-4">
              <Label className="text-gray-300 text-sm font-semibold mb-3 block">Testing Component Preview:</Label>
              <div className="space-y-3">
                <TestingErrorReportButton variant="prominent" />
                <TestingErrorReportButton variant="floating" />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Error Report Statistics */}
        <Card className="bg-navy-700 border-navy-600 mb-6">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <Settings className="h-5 w-5 text-orange-400" />
              Error Report Statistics
            </CardTitle>
          </CardHeader>
          <CardContent>
            {isLoadingStats ? (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className="animate-pulse bg-navy-600 h-16 rounded"></div>
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-navy-600 rounded-lg p-4 text-center">
                  <div className="text-2xl font-bold text-orange-400">{statsData.total || 0}</div>
                  <div className="text-gray-300 text-sm">Total Reports</div>
                </div>
                <div className="bg-navy-600 rounded-lg p-4 text-center">
                  <div className="text-2xl font-bold text-red-400">{statsData.open || 0}</div>
                  <div className="text-gray-300 text-sm">Open Issues</div>
                </div>
                <div className="bg-navy-600 rounded-lg p-4 text-center">
                  <div className="text-2xl font-bold text-yellow-400">{statsData.inProgress || 0}</div>
                  <div className="text-gray-300 text-sm">In Progress</div>
                </div>
                <div className="bg-navy-600 rounded-lg p-4 text-center">
                  <div className="text-2xl font-bold text-green-400">{statsData.resolved || 0}</div>
                  <div className="text-gray-300 text-sm">Resolved</div>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Testing Data Management */}
        <Card className="bg-navy-700 border-navy-600">
          <CardHeader>
            <CardTitle className="text-white flex items-center gap-2">
              <RotateCcw className="h-5 w-5 text-orange-400" />
              Testing Data Management
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex flex-wrap gap-3">
              <Button
                onClick={() => generateTestDataMutation.mutate()}
                disabled={generateTestDataMutation.isPending}
                className="bg-blue-600 hover:bg-blue-700 text-white"
              >
                <TestTube className="h-4 w-4 mr-2" />
                {generateTestDataMutation.isPending ? "Generating..." : "Generate Test Reports"}
              </Button>

              <Button
                onClick={() => clearTestDataMutation.mutate()}
                disabled={clearTestDataMutation.isPending}
                variant="destructive"
              >
                <Trash2 className="h-4 w-4 mr-2" />
                {clearTestDataMutation.isPending ? "Clearing..." : "Clear Test Data"}
              </Button>
            </div>

            <div className="bg-orange-500/10 border border-orange-500/20 rounded-lg p-4">
              <div className="flex items-start gap-3">
                <TestTube className="h-5 w-5 text-orange-400 mt-0.5" />
                <div>
                  <h4 className="text-orange-400 font-semibold">Testing Instructions</h4>
                  <ul className="text-orange-300 text-sm mt-2 space-y-1">
                    <li>• Enable "Testing Mode" to show enhanced bug report features</li>
                    <li>• Use "Generate Test Reports" to create sample data for demonstration</li>
                    <li>• Testing banner appears on landing page when enabled</li>
                    <li>• All test reports are clearly labeled and can be cleared separately</li>
                    <li>• Regular users won't see testing features unless enabled</li>
                  </ul>
                </div>
              </div>
            </div>

            {/* Quick Actions */}
            <div className="flex gap-2 flex-wrap">
              <Badge variant="outline" className="border-orange-500/50 text-orange-300">
                Admin Only Feature
              </Badge>
              <Badge variant="outline" className="border-blue-500/50 text-blue-300">
                Testing Environment
              </Badge>
              <Badge variant="outline" className="border-green-500/50 text-green-300">
                Removable Controls
              </Badge>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

shared/schema.ts.content:
import { sql } from 'drizzle-orm';
import {
  index,
  jsonb,
  pgTable,
  timestamp,
  varchar,
  text,
  integer,
  boolean,
  decimal,
  pgEnum,
} from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";
import { relations } from "drizzle-orm";

// Session storage table for Replit Auth
export const sessions = pgTable(
  "sessions",
  {
    sid: varchar("sid").primaryKey(),
    sess: jsonb("sess").notNull(),
    expire: timestamp("expire").notNull(),
  },
  (table) => [index("IDX_session_expire").on(table.expire)],
);

// User roles enum - Hierarchical structure
export const userRoleEnum = pgEnum('user_role', [
  // Customer roles
  'homeowner',
  'property_manager',
  'business_owner',

  // Service provider roles  
  'contractor_user',
  'helper',             // New role for workers/helpers
  'service_provider',   // Phase 1: Cleaners, movers, landscapers, etc.
  'vehicle_dealer',     // Phase 1: Vehicle dealers/sellers
  'accelerator_member',
  'realtor',
  'car_salesman',
  'insurance_agent',
  'mortgage_broker',

  // HOA & Community roles
  'hoa_admin',          // Phase 4: HOA administrators

  // Community roles
  'community_member',
  'community_moderator',
  'community_leader',

  // Platform staff roles (ascending hierarchy)
  'support_agent',
  'content_moderator',
  'territory_manager',
  'contractor_success',
  'content_seo',
  'analytics_specialist',
  'marketing_specialist',

  // Admin roles (ascending hierarchy)
  'moderator',           // Basic moderation powers
  'ops_admin',          // Operations and platform management
  'super_admin',        // Full platform control except user management
  'head_admin'          // Ultimate authority - can manage all users and admins
]);

// Story template categories for professional story generation
export const storyTemplateCategoryEnum = pgEnum('story_template_category', [
  'background',
  'skills', 
  'values',
  'approach',
  'innovation',
  'impact'
]);

// Story tone enum for narrative style
export const storyToneEnum = pgEnum('story_tone', [
  'professional',
  'friendly', 
  'inspiring',
  'authoritative'
]);

// Story length enum
export const storyLengthEnum = pgEnum('story_length', [
  'short',
  'medium',
  'long'
]);

// Trade categories enum for contractor specializations
export const tradeCategoryEnum = pgEnum('trade_category', [
  // Construction & General
  'general_contractor',
  'construction_manager',
  'project_manager',

  // Structural & Foundation
  'concrete_contractor',
  'foundation_specialist',
  'masonry_contractor',
  'structural_engineer',

  // Building Envelope
  'roofing_contractor',
  'siding_contractor',
  'window_installer',
  'door_installer',
  'insulation_contractor',

  // Electrical & Technology
  'electrician',
  'low_voltage_technician',
  'solar_installer',
  'security_system_installer',
  'smart_home_specialist',

  // Plumbing & HVAC
  'plumber',
  'hvac_contractor',
  'refrigeration_technician',
  'water_heater_specialist',
  'septic_contractor',

  // Interior Finishing
  'flooring_contractor',
  'tile_contractor',
  'carpet_installer',
  'painter',
  'drywall_contractor',
  'cabinet_maker',
  'countertop_installer',

  // Kitchen & Bath
  'kitchen_remodeler',
  'bathroom_remodeler',
  'appliance_installer',

  // Outdoor & Landscaping
  'landscaper',
  'hardscape_contractor',
  'pool_contractor',
  'fence_contractor',
  'deck_builder',
  'outdoor_lighting',

  // Specialty Services
  'home_inspector',
  'mold_remediation',
  'water_damage_restoration',
  'pest_control',
  'cleaning_service',
  'handyman',
  'maintenance_contractor'
]);

// Permission levels enum
export const permissionLevelEnum = pgEnum('permission_level', [
  'none',
  'read',
  'write', 
  'admin',
  'owner'
]);

// Social post types enum
export const postTypeEnum = pgEnum('post_type', [
  'general',
  'announcement',
  'question',
  'recommendation',
  'for_sale',
  'lost_found',
  'safety_alert',
  'event',
  'service_request',
  'neighborhood_news'
]);

// Reaction types enum
export const reactionTypeEnum = pgEnum('reaction_type', [
  'like',
  'love',
  'laugh',
  'wow',
  'sad',
  'angry',
  'helpful',
  'thanks'
]);

// Privacy levels enum
export const privacyLevelEnum = pgEnum('privacy_level', [
  'public',
  'neighborhood',
  'friends',
  'private'
]);

// Report reasons enum
export const reportReasonEnum = pgEnum('report_reason', [
  'spam',
  'harassment',
  'hate_speech',
  'violence',
  'misinformation',
  'inappropriate_content',
  'scam',
  'other'
]);

// Invitation status enum
export const invitationStatusEnum = pgEnum('invitation_status', [
  'pending',
  'accepted',
  'declined',
  'expired'
]);

// Invitation type enum
export const invitationTypeEnum = pgEnum('invitation_type', [
  'email',
  'referral_code',
  'direct_link'
]);

// Address verification status enum
export const addressVerificationStatusEnum = pgEnum('address_verification_status', [
  'pending',
  'submitted',
  'approved',
  'rejected',
  'expired'
]);

// Professional verification status enum
export const verificationStatusEnum = pgEnum('verification_status', [
  'pending',
  'under_review',
  'approved',
  'rejected',
  'expired',
  'suspended'
]);

// Users table
export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: varchar("email").unique().notNull(),
  password: varchar("password_hash"), // for local auth
  firstName: varchar("first_name"),
  lastName: varchar("last_name"),
  profileImageUrl: varchar("profile_image_url"),
  phone: varchar("phone"),
  address: text("address"),
  city: varchar("city"),
  state: varchar("state"),
  county: varchar("county"), // Add county field
  zipCode: varchar("zip_code"),
  role: userRoleEnum("role").default('homeowner'), // Primary role for backward compatibility
  roles: text("roles").array().default([]), // Multi-role support - array of role strings
  activeRole: varchar("active_role").default('homeowner'), // Currently active role for dashboard switching
  provider: varchar("provider").default('local'), // 'local', 'facebook', 'google'
  providerId: varchar("provider_id"), // social login ID
  facebookId: varchar("facebook_id"), // Add facebookId field
  googleId: varchar("google_id"), // Add googleId field
  emailVerified: boolean("email_verified").default(false),
  addressVerified: boolean("address_verified").default(false),
  addressVerificationDeadline: timestamp("address_verification_deadline"),
  verificationStatus: verificationStatusEnum("verification_status").default('pending'), // Add verificationStatus
  onboardingCompleted: boolean("onboarding_completed").default(false),
  referralCode: varchar("referral_code"),
  invitedBy: varchar("invited_by"),
  preferences: jsonb("preferences").$type<{
    emailNotifications?: boolean;
    smsNotifications?: boolean;
    marketingEmails?: boolean;
    completedTours?: string[]; // Track completed onboarding tours
    navigation?: {
      customOrder?: string[]; // Array of navigation items in user's preferred order
      hiddenFromSwipe?: string[]; // Navigation items to hide from swipe navigation
      enableSwipeNavigation?: boolean; // Whether swipe navigation is enabled
    };
    privacy?: {
      showProfile?: boolean;
      allowMessages?: boolean;
      shareActivity?: boolean;
    };
    dashboard?: {
      enabledWidgets?: string[]; // Which widgets to show on dashboard
      widgetOrder?: string[]; // Order of widgets
      layout?: 'single' | 'two-column' | 'three-column'; // Dashboard layout
    };
  }>(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Trusted devices table for master admin persistent sessions
export const trustedDevices = pgTable("trusted_devices", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id, { onDelete: 'cascade' }),
  deviceFingerprint: varchar("device_fingerprint").notNull(),
  deviceName: varchar("device_name"), // User-friendly name like "Chrome on Windows"
  userAgent: text("user_agent"),
  ipAddress: varchar("ip_address"),
  lastUsed: timestamp("last_used").defaultNow(),
  isActive: boolean("is_active").default(true),
  sessionToken: varchar("session_token").notNull().unique(),
  expiresAt: timestamp("expires_at").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
}, (table) => [
  index("idx_trusted_devices_user").on(table.userId),
  index("idx_trusted_devices_fingerprint").on(table.deviceFingerprint),
  index("idx_trusted_devices_session").on(table.sessionToken),
]);

// Realtor profiles
export const realtorProfiles = pgTable("realtor_profiles", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  licenseNumber: varchar("license_number").notNull(),
  brokerageName: varchar("brokerage_name").notNull(),
  mlsId: varchar("mls_id"),
  specializations: jsonb("specializations").$type<string[]>(), // residential, commercial, luxury, etc.
  yearsExperience: integer("years_experience"),
  transactionsCompleted: integer("transactions_completed").default(0),
  averageTransactionValue: decimal("average_transaction_value"),
  serviceAreas: jsonb("service_areas").$type<{
    counties: string[];
    cities: string[];
    zipCodes: string[];
  }>(),
  licenseState: varchar("license_state").notNull(),
  licenseExpiration: timestamp("license_expiration"),
  verificationStatus: verificationStatusEnum("verification_status").default('pending'),
  verificationDocuments: jsonb("verification_documents").$type<{
    licenseDocument?: string;
    brokerageAffiliation?: string;
    mlsCertificate?: string;
    additionalCertifications?: string[];
  }>(),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Car salesman profiles
export const carSalesmanProfiles = pgTable("car_salesman_profiles", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").notNull().references(() => users.id),
  dealershipName: varchar("dealership_name").notNull(),
  dealerLicense: varchar("dealer_license").notNull(),
  salesmanLicense: varchar("salesman_license"),
  specializations: jsonb("specializations").$type<string[]>(), // new, used, luxury, commercial, etc.
  yearsExperience: integer("years_experience"),
  vehiclesSold: integer("vehicles_sold").default(0),
  averageVehicleValue: decimal("average_vehicle_value"),
  brandsSpecialty: jsonb("brands_specialty").$type<string[]>(), // Ford, Toyota, BMW, etc.
  serviceAreas: jsonb("service_areas").$type<{
    counties: string[];
    cities: string[];
    zipCodes: string[];
  }>(),
  licenseState: varchar("license_state").notNull(),
  licenseExpiration: timestamp("license_expiration"),
  verificationStatus: verificationStatusEnum("verification_status").default('pending'),
  verificationDocuments: jsonb("verification_documents").$type<{
    dealerLicense?: string;
    salesmanLicense?: string;
    dealershipAffiliation?: string;
    additionalCertifications?: string[];
  }>(),
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// States table
export const states = pgTable("states", {
  id: varchar("id").primaryKey(),
  name: varchar("name").notNull(),
  code: varchar("code", { length: 2 }).notNull().unique(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Counties table with FIPS codes
export const counties = pgTable("counties", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  fips: varchar("fips", { length: 5 }).notNull().unique(),
  stateCode: varchar("state_code", { length: 2 }).notNull().references(() => states.code),
  population: integer("population"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Trade categories (hierarchical)
export const trades = pgTable("trades", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: varchar("name").notNull(),
  slug: varchar("slug").notNull().unique(),
  parentId: varchar("parent_id"),
  description: text("description"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Contractors table
export const contractors = pgTable("contractors", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id"),
  companyName: varchar("company_name").notNull(),
  slug: varchar("slug").notNull().unique(),
  phone: varchar("phone"),
  email: varchar("email"),
  website: varchar("website"),
  yearsInBusiness: integer("years_in_business"),
  licenseNumber: varchar("license_number"),
  insuranceDocUrl: varchar("insurance_doc_url"),
  about: text("about"),
  photos: jsonb("photos").$type<string[]>(),
  minJobSize: decimal("min_job_size"),
  availabilityWindow: varchar("availability_window"),
  pricingNotes: text("pricing_notes"),
  responseTimeSla: integer("response_time_sla"), // in hours
  isGeneralContractor: boolean("is_general_contractor").default(false),
  isResidentialContractor: boolean("is_residential_contractor").default(false),
  acceptsSubcontractWork: boolean("accepts_subcontract_work").default(false),
  verifiedLicensed: boolean("verified_licensed").default(false),
  verifiedInsured: boolean("verified_insured").default(false),
  lastVerified: timestamp("last_verified"),
  positiveRecommendations: integer("positive_recommendations").default(0),
  negativeRecommendations: integer("negative_recommendations").default(0),
  totalRecommendations: integer("total_recommendations").default(0),
  recommendationScore: decimal("recommendation_score", { precision: 5, scale: 2 }).default("0.00"), // positive minus negative
  recommendationPercentage: decimal("recommendation_percentage", { precision: 5, scale: 2 }).default("0.00"), // (positive/total)*100
  isActive: boolean("is_active").default(true),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Contractor-Trade relationships (many-to-many)
export const contractorTrades = pgTable("contractor_trades", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull(),
  tradeId: varchar("trade_id").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Contractor service areas (many-to-many with counties)
export const contractorCounties = pgTable("contractor_counties", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull(),
  countyId: varchar("county_id").notNull(),
  createdAt: timestamp("created_at").defaultNow(),
});

// Recommendations/Reviews
export const recommendations = pgTable("recommendations", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull(),
  userId: varchar("user_id").notNull(),
  recommendationType: varchar("recommendation_type").notNull(), // 'positive' or 'negative'
  comment: text("comment").notNull(),
  projectType: varchar("project_type"), // roofing, plumbing, etc.
  projectValue: decimal("project_value"), // dollar amount for context
  workQuality: varchar("work_quality"), // excellent, good, fair, poor
  timeliness: varchar("timeliness"), // on_time, slightly_late, very_late
  communication: varchar("communication"), // excellent, good, fair, poor
  wouldHireAgain: boolean("would_hire_again"),
  photoUrl: varchar("photo_url"),

  // Anti-abuse measures
  customerName: varchar("customer_name").notNull(),
  customerEmail: varchar("customer_email").notNull(),
  customerPhone: varchar("customer_phone"),
  ipAddress: varchar("ip_address"),
  userAgent: text("user_agent"),

  // Verification and moderation
  isVerified: boolean("is_verified").default(false),
  verificationMethod: varchar("verification_method"), // 'email', 'phone', 'admin'
  verifiedAt: timestamp("verified_at"),
  isPublic: boolean("is_public").default(false), // Default to private until verified
  moderationStatus: varchar("moderation_status").default('pending'), // pending, approved, rejected
  moderatedAt: timestamp("moderated_at"),
  moderatedBy: varchar("moderated_by"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Contractor leaderboard statistics tracking
export const contractorLeaderboardStats = pgTable("contractor_leaderboard_stats", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull().references(() => contractors.id),
  month: integer("month").notNull(), // 1-12
  year: integer("year").notNull(),
  monthlyPositiveRecommendations: integer("monthly_positive_recommendations").default(0),
  monthlyNegativeRecommendations: integer("monthly_negative_recommendations").default(0),
  monthlyTotalRecommendations: integer("monthly_total_recommendations").default(0),
  lifetimePositiveRecommendations: integer("lifetime_positive_recommendations").default(0),
  lifetimeNegativeRecommendations: integer("lifetime_negative_recommendations").default(0),
  lifetimeTotalRecommendations: integer("lifetime_total_recommendations").default(0),
  monthlyRecommendationScore: decimal("monthly_recommendation_score", { precision: 5, scale: 2 }), // Monthly (positive - negative)
  lifetimeRecommendationScore: decimal("lifetime_recommendation_score", { precision: 5, scale: 2 }), // Lifetime (positive - negative)
  monthlyRecommendationPercentage: decimal("monthly_recommendation_percentage", { precision: 5, scale: 2 }), // Monthly percentage
  lifetimeRecommendationPercentage: decimal("lifetime_recommendation_percentage", { precision: 5, scale: 2 }), // Lifetime percentage
  lastUpdated: timestamp("last_updated").defaultNow(),
  createdAt: timestamp("created_at").defaultNow(),
}, (table) => [
  index("contractor_leaderboard_month_year_idx").on(table.contractorId, table.month, table.year),
  index("leaderboard_monthly_ranking_idx").on(table.month, table.year, table.monthlyTotalRecommendations),
  index("leaderboard_lifetime_ranking_idx").on(table.lifetimeTotalRecommendations),
]);

// Leads management
export const leads = pgTable("leads", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id"), // homeowner
  contractorId: varchar("contractor_id"), // assigned contractor
  projectType: varchar("project_type").notNull(),
  description: text("description"),
  countyId: varchar("county_id").notNull(),
  tradeId: varchar("trade_id").notNull(),
  estimatedValue: decimal("estimated_value"),
  urgency: varchar("urgency"), // immediate, week, month, planning
  contactPreference: varchar("contact_preference"), // phone, email, text
  status: varchar("status").default('new'), // new, contacted, qualified, matched, closed
  routingType: varchar("routing_type"), // direct, top3, call_now
  calculatorData: jsonb("calculator_data"),
  utmData: jsonb("utm_data"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// Lead routing and assignment
export const leadAssignments = pgTable("lead_assignments", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  leadId: varchar("lead_id").notNull(),
  contractorId: varchar("contractor_id").notNull(),
  status: varchar("status").default('pending'), // pending, accepted, declined, expired
  assignedAt: timestamp("assigned_at").defaultNow(),
  respondedAt: timestamp("responded_at"),
  expiresAt: timestamp("expires_at"),
});

// Contractor verification documents
export const verificationDocuments = pgTable("verification_documents", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull(),
  type: varchar("type").notNull(), // license, insurance, id
  fileName: varchar("file_name").notNull(),
  fileUrl: varchar("file_url").notNull(),
  status: varchar("status").default('pending'), // pending, approved, rejected
  reviewNotes: text("review_notes"),
  reviewedBy: varchar("reviewed_by"),
  reviewedAt: timestamp("reviewed_at"),
  expiresAt: timestamp("expires_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Growth Pack downloads
export const growthPackDownloads = pgTable("growth_pack_downloads", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: varchar("email").notNull(),
  companyName: varchar("company_name"),
  primaryTrade: varchar("primary_trade"),
  serviceAreas: text("service_areas"),
  companySize: varchar("company_size"),
  hasConsented: boolean("has_consented").default(false),
  downloadToken: varchar("download_token").notNull().unique(),
  downloadedAt: timestamp("downloaded_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Accelerator memberships (one-time purchase, not subscription)
export const acceleratorMemberships = pgTable("accelerator_memberships", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  contractorId: varchar("contractor_id").notNull(),
  purchaseAmount: decimal("purchase_amount").notNull(),
  paymentIntentId: varchar("payment_intent_id"),
  status: varchar("status").default('active'), // active, paused, cancelled
  features: jsonb("features").$type<string[]>(),
  purchasedAt: timestamp("purchased_at").defaultNow(),
  expiresAt: timestamp("expires_at"), // if applicable
});

// Pricing data for quote calculators
export const pricingData = pgTable("pricing_data", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  service: varchar("service").notNull(), // painting, roofing, etc
  fips: varchar("fips").notNull(),
  serviceCode: varchar("service_code"),
  inputs: jsonb("inputs"), // input definitions and units
  baseLow: decimal("base_low"),
  baseHigh: decimal("base_high"),
  adjustmentFactors: jsonb("adjustment_factors"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

// System events and analytics
export const events = pgTable("events", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  eventType: varchar("event_type").notNull(),
  userId: varchar("user_id"),
