import { useState, useEffect } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetTrigger, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { useAuth } from "@/hooks/useAuth";
import QuoteForm from "./quote-form";
import { Users, Phone, Calculator, ArrowUp, X } from "lucide-react";
import { useMemo } from "react";
import { MessageCircle } from "lucide-react";

// Pages where the mobile CTA should appear
const CTA_PAGES = [
  '/quote',
  '/contractors/board',
];

// Different CTA types based on page
const getCTAConfig = (location: string) => {
  if (location.includes('/contractors/') && !location.includes('/board')) {
    return {
      type: 'contractor-profile',
      text: 'Contact This Contractor',
      icon: MessageCircle,
      color: 'bg-blue-500 hover:bg-blue-600'
    };
  }

  if (location.includes('/calculator') || location.includes('/quote')) {
    return {
      type: 'quote-calculator',
      text: 'Get 3 Free Estimates',
      icon: Calculator,
      color: 'bg-orange-500 hover:bg-orange-600'
    };
  }

  if (location.includes('/contractors/board')) {
    return {
      type: 'general',
      text: 'Get 3 Free Quotes',
      icon: Users,
      color: 'bg-orange-500 hover:bg-orange-600'
    };
  }

  return null; // Return null if no CTA should be shown
};

export default function MobileCTA() {
  const [location] = useLocation();
  const { isAuthenticated } = useAuth();
  const [isQuoteSheetOpen, setIsQuoteSheetOpen] = useState(false);
  const [showCTA, setShowCTA] = useState(false);
  const [isVisible, setIsVisible] = useState(true);

  // Check if CTA should be shown on current page
  const ctaConfig = getCTAConfig(location);

  // Handle scroll to show/hide CTA
  useEffect(() => {
    let lastScrollY = window.scrollY;
    let ticking = false;

    const updateScrollDirection = () => {
      const scrollY = window.scrollY;

      if (Math.abs(scrollY - lastScrollY) < 10) {
        ticking = false;
        return;
      }

      setIsVisible(scrollY < lastScrollY || scrollY < 100);
      lastScrollY = scrollY;
      ticking = false;
    };

    const requestTick = () => {
      if (!ticking) {
        requestAnimationFrame(updateScrollDirection);
        ticking = true;
      }
    };

    const onScroll = () => requestTick();

    window.addEventListener('scroll', onScroll);
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  // Show CTA after a brief delay if it should be displayed on the current page
  useEffect(() => {
    if (ctaConfig) {
      const timer = setTimeout(() => setShowCTA(true), 1000);
      return () => clearTimeout(timer);
    } else {
      setShowCTA(false);
    }
  }, [location, ctaConfig]);

  if (!showCTA || !ctaConfig) {
    return null;
  }

  const IconComponent = ctaConfig.icon;

  return (
    <>
      {/* Mobile CTA Button */}
      <div
        className={`fixed bottom-0 left-0 right-0 z-50 md:hidden transition-transform duration-300 ${
          isVisible ? 'translate-y-0' : 'translate-y-full'
        }`}
      >
        <div className="bg-navy-800/95 backdrop-blur-sm border-t border-navy-600 p-4">
          <Sheet open={isQuoteSheetOpen} onOpenChange={setIsQuoteSheetOpen}>
            <SheetTrigger asChild>
              <Button
                className={`w-full ${ctaConfig.color} text-white py-4 rounded-lg font-semibold glow-effect transition-all duration-300 shadow-lg`}
              >
                <IconComponent className="h-5 w-5 mr-2" />
                {ctaConfig.text}
              </Button>
            </SheetTrigger>

            <SheetContent
              side="bottom"
              className="bg-navy-800 border-navy-600 max-h-[90vh] overflow-y-auto"
            >
              <SheetHeader className="text-left mb-6">
                <SheetTitle className="text-white text-xl">
                  {ctaConfig.type === 'contractor-profile'
                    ? 'Contact This Contractor'
                    : 'Get Free Estimates'
                  }
                </SheetTitle>
              </SheetHeader>

              <QuoteForm
                onSuccess={() => setIsQuoteSheetOpen(false)}
                compact={true}
              />
            </SheetContent>
          </Sheet>
        </div>
      </div>

      {/* Scroll to top button (shows when CTA is hidden) */}
      {!isVisible && (
        <button
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
          className="fixed bottom-6 right-6 z-40 md:hidden w-12 h-12 bg-orange-500 hover:bg-orange-600 text-white rounded-full shadow-lg flex items-center justify-center transition-all duration-300 glow-effect"
          aria-label="Scroll to top"
        >
          <ArrowUp className="h-5 w-5" />
        </button>
      )}
    </>
  );
}

client/src/hooks/useAppLikeEffects.ts.content:
import { useEffect } from 'react';
import { useIsMobile } from './use-mobile';

export function useAppLikeEffects() {
  const isMobile = useIsMobile();

  useEffect(() => {
    if (!isMobile) return;

    // Prevent default browser behaviors for app-like experience
    const preventDefault = (e: TouchEvent) => {
      if (e.touches.length > 1) {
        e.preventDefault(); // Prevent pinch zoom
      }
    };

    const preventBounce = (e: TouchEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') {
        return; // Allow scrolling in input fields
      }

      const scrollTop = document.documentElement.scrollTop || document.body.scrollTop;
      const scrollHeight = document.documentElement.scrollHeight || document.body.scrollHeight;
      const clientHeight = document.documentElement.clientHeight || window.innerHeight;

      if (scrollTop === 0 && e.touches[0].clientY > e.touches[0].clientY) {
        e.preventDefault(); // Prevent overscroll at top
      }

      if (scrollTop + clientHeight >= scrollHeight && e.touches[0].clientY < e.touches[0].clientY) {
        e.preventDefault(); // Prevent overscroll at bottom
      }
    };

    // Add haptic feedback for interactions
    const addHapticFeedback = (selector: string) => {
      const elements = document.querySelectorAll(selector);
      elements.forEach(element => {
        element.addEventListener('touchstart', () => {
          if ('vibrate' in navigator) {
            navigator.vibrate(10); // Very light haptic feedback
          }
        });
      });
    };

    // Apply app-like behaviors
    document.addEventListener('touchmove', preventDefault, { passive: false });
    document.addEventListener('touchmove', preventBounce, { passive: false });

    // Add haptic feedback to interactive elements
    addHapticFeedback('button, .button, [role="button"]');

    // Set viewport height for mobile browsers
    const setVH = () => {
      const vh = window.innerHeight * 0.01;
      document.documentElement.style.setProperty('--vh', `${vh}px`);
    };

    setVH();
    window.addEventListener('resize', setVH);
    window.addEventListener('orientationchange', setVH);

    return () => {
      document.removeEventListener('touchmove', preventDefault);
      document.removeEventListener('touchmove', preventBounce);
      window.removeEventListener('resize', setVH);
      window.removeEventListener('orientationchange', setVH);
    };
  }, [isMobile]);

  useEffect(() => {
    // Register service worker for PWA functionality
    if ('serviceWorker' in navigator && isMobile) {
      navigator.serviceWorker.register('/sw.js')
        .then(registration => {
          console.log('SW registered: ', registration);
        })
        .catch(registrationError => {
          console.log('SW registration failed: ', registrationError);
        });
    }
  }, [isMobile]);
}

