          description: "Pricing varies by location due to labor costs, permits, and material availability. Enter your area for accurate estimates.",
          position: "bottom"
        },
        {
          id: "get-contractors",
          target: "[data-testid='find-contractors-button']",
          title: "Connect with Contractors",
          description: "After getting your estimate, you can immediately connect with qualified contractors in your area.",
          position: "top"
        }
      ];

    case 'search':
      return [
        {
          id: "search-intro",
          target: "[data-testid='contractor-search']",
          title: "Smart Contractor Search",
          description: "Find exactly the right contractor for your project using our advanced search and filtering system.",
          position: "bottom"
        },
        {
          id: "location-filter",
          target: "[data-testid='location-filter']",
          title: "Search by Location",
          description: "Start by selecting your state and county. This ensures you only see contractors who actually serve your area.",
          position: "bottom"
        },
        {
          id: "trade-filter",
          target: "[data-testid='trade-filter']",
          title: "Filter by Trade",
          description: "Narrow down to contractors who specialize in exactly what you need - from plumbing to roofing to electrical work.",
          position: "bottom"
