          target: "[data-testid='contractor-sorting']",
          title: "Sort Results",
          description: "Sort by recommendations, ratings, or experience. Contractors with more positive feedback appear higher in results.",
          position: "left"
        }
      ];

    default:
      return [];
  }
};

export function FeatureTour({ feature, autoStart = false, onComplete }: FeatureTourProps) {
  const steps = getFeatureSteps(feature);

  if (steps.length === 0) return null;

  return (
    <OnboardingTour
      steps={steps}
      tourKey={`feature-tour-${feature}`}
      autoStart={autoStart}
      onComplete={onComplete}
    />
  );
}

