  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { UserHeatmap } from "@/components/UserHeatmap";
import { Plus, Edit, Trash2, Gift, Settings, Megaphone, Users, Bell, Map, CheckCircle, Bug, Image, BarChart3, DollarSign, Wrench, MapPin, Clock, Bot, Shield, AlertTriangle, Eye, Database, Lock, Crown, Globe } from "lucide-react";
import { useLocation } from "wouter";



type SiteSetting = {
  id: string;
  category: string;
  key: string;
  value: any;
  description?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
};

type PrizeConfiguration = {
  id: string;
  name: string;
  description?: string;
  prizeType: string;
  value: string;
  vendor?: string;
  isActive: boolean;
  probability: string;
  terms?: string;
  expirationDays: number;
  createdAt: string;
  updatedAt: string;
};

type Advertisement = {
  id: string;
  title: string;
  content: string;
  imageUrl?: string;
  linkUrl?: string;
  placement: string;
  targetAudience: string;
  isActive: boolean;
  startDate?: string;
  endDate?: string;
  clickCount: number;
  viewCount: number;
  createdAt: string;
  updatedAt: string;
};

type ContractorSetting = {
  id: string;
  category: string;
  setting: string;
  value: any;
  description?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
};

export default function AdminPanel() {
  const { user, isAuthenticated } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [, setLocation] = useLocation();
  const [selectedTab, setSelectedTab] = useState("heatmap");
  const [editingItem, setEditingItem] = useState<any>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  // Check admin access
  if (!isAuthenticated || !user || !['owner', 'ops_admin'].includes(user.role || '')) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center">
        <Card className="max-w-md">
          <CardContent className="p-6 text-center">
            <h2 className="text-xl font-semibold mb-2">Access Denied</h2>
            <p className="text-gray-600">You need admin privileges to access this panel.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Fetch data for each tab
  const { data: prizes = [], isLoading: prizesLoading } = useQuery({
    queryKey: ["/api/admin/prizes"],
    retry: false,
  });

  const { data: advertisements = [], isLoading: adsLoading } = useQuery({
    queryKey: ["/api/admin/advertisements"],
    retry: false,
  });

  const { data: siteSettings = [], isLoading: settingsLoading } = useQuery({
    queryKey: ["/api/admin/site-settings"],
    retry: false,
  });

  const { data: contractorSettings = [], isLoading: contractorSettingsLoading } = useQuery({
    queryKey: ["/api/admin/contractor-settings"],
    retry: false,
  });

  // Mutations for CRUD operations
  const createMutation = useMutation({
    mutationFn: async ({ type, data }: { type: string; data: any }) => {
      return apiRequest("POST", `/api/admin/${type}`, data);
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: [`/api/admin/${variables.type}`] });
      setIsDialogOpen(false);
      setEditingItem(null);
      toast({
        title: "Success",
        description: "Item created successfully",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const updateMutation = useMutation({
    mutationFn: async ({ type, id, data }: { type: string; id: string; data: any }) => {
      return apiRequest("PUT", `/api/admin/${type}/${id}`, data);
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: [`/api/admin/${variables.type}`] });
      setIsDialogOpen(false);
      setEditingItem(null);
      toast({
        title: "Success",
        description: "Item updated successfully",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async ({ type, id }: { type: string; id: string }) => {
      return apiRequest("DELETE", `/api/admin/${type}/${id}`);
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: [`/api/admin/${variables.type}`] });
      toast({
        title: "Success",
        description: "Item deleted successfully",
      });
    },
    onError: (error) => {
      toast({
        title: "Error",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  const handleEdit = (item: any) => {
    setEditingItem(item);
    setIsDialogOpen(true);
  };

  const handleDelete = (type: string, id: string) => {
    if (confirm("Are you sure you want to delete this item?")) {
      deleteMutation.mutate({ type, id });
    }
  };

  const handleSubmit = (formData: any) => {
    const type = selectedTab === "contractor-settings" ? "contractor-settings" : selectedTab;

    if (editingItem) {
      updateMutation.mutate({ type, id: editingItem.id, data: formData });
    } else {
      createMutation.mutate({ type, data: formData });
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6">
      <div className="max-w-7xl mx-auto">
        <div className="mb-8">
          <h1 className="text-3xl font-bold mb-2 flex items-center gap-2">
            <Settings className="w-8 h-8 text-orange-500" />
            Admin Panel
          </h1>
          <p className="text-gray-400">Manage site features, prizes, advertisements, contractor settings, and AI monitoring</p>
        </div>

        <Tabs value={selectedTab} onValueChange={setSelectedTab} className="space-y-6">
          <TabsList className="grid w-full grid-cols-10 bg-slate-800">
            <TabsTrigger value="heatmap" className="flex items-center gap-2">
              <Map className="w-4 h-4" />
              User Heatmap
            </TabsTrigger>
            <TabsTrigger value="prizes" className="flex items-center gap-2">
              <Gift className="w-4 h-4" />
              Prizes
            </TabsTrigger>
            <TabsTrigger value="advertisements" className="flex items-center gap-2">
              <Megaphone className="w-4 h-4" />
              Ads
            </TabsTrigger>
            <TabsTrigger value="site-settings" className="flex items-center gap-2">
              <Settings className="w-4 h-4" />
              Site Settings
            </TabsTrigger>
            <TabsTrigger value="contractor-settings" className="flex items-center gap-2">
              <Settings className="w-4 h-4" />
              Contractor Settings
            </TabsTrigger>
            <TabsTrigger value="monitoring" className="flex items-center gap-2">
              <Bell className="w-4 h-4" />
              AI Monitoring
            </TabsTrigger>
            <TabsTrigger value="error-reports" className="flex items-center gap-2">
              <Bug className="w-4 h-4" />
              Error Reports
