                    onClick={() => toggleFileSelection(file.id)}
                  >
                    <CardContent className="p-4">
                      <div className="aspect-square bg-navy-600 rounded-lg mb-3 flex items-center justify-center overflow-hidden">
                        {file.thumbnail ? (
