  async togglePostLike(userId: string, postId: string): Promise<{ liked: boolean; likeCount: number }> {
    // Check if like exists
    const [existingLike] = await db
      .select()
      .from(postLikes)
      .where(eq(postLikes.userId, userId))
      .where(eq(postLikes.postId, postId));

    if (existingLike) {
      // Remove like
      await db
        .delete(postLikes)
        .where(eq(postLikes.id, existingLike.id));

      await db
        .update(communityPosts)
        .set({ 
          likeCount: sql`${communityPosts.likeCount} - 1`,
          updatedAt: new Date()
        })
        .where(eq(communityPosts.id, postId));

      const [post] = await db
        .select({ likeCount: communityPosts.likeCount })
        .from(communityPosts)
        .where(eq(communityPosts.id, postId));

      return { liked: false, likeCount: post.likeCount };
    } else {
      // Add like
      await db.insert(postLikes).values({ userId, postId });

      await db
        .update(communityPosts)
        .set({ 
          likeCount: sql`${communityPosts.likeCount} + 1`,
          updatedAt: new Date()
        })
        .where(eq(communityPosts.id, postId));

      const [post] = await db
        .select({ likeCount: communityPosts.likeCount })
        .from(communityPosts)
        .where(eq(communityPosts.id, postId));

      return { liked: true, likeCount: post.likeCount };
    }
  }

