  async getDailyDeals(filters?: {
    countyFips?: string;
    limit?: number;
    featured?: boolean;
    dealType?: string;
    activeOnly?: boolean;
  }): Promise<DailyDeal[]> {
    let query = db.select().from(dailyDeals);

    const conditions = [];

    if (filters?.countyFips) {
