import type { Express } from "express";
import { eq, desc, and, or, like, sql, count, inArray } from "drizzle-orm";
import { db } from "./db";
import { 
  socialPosts, 
  postReactions, 
  postComments, 
  commentReactions,
  postShares,
  contentReports,
  userFollows,
  neighborhoods,
  users
} from "@shared/schema";
import { isAuthenticated, requirePermission } from "./auth";
import { z } from "zod";
import type { User } from "@shared/schema";

export function registerSocialRoutes(app: Express) {

  // Get social feed with filters
  app.get("/api/social/feed", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const { 
        postType = 'all',
        location = 'neighborhood', 
        sortBy = 'recent',
        search = '',
        page = 1,
        limit = 10
      } = req.query;

      const offset = (parseInt(page) - 1) * parseInt(limit);

      // Build query conditions
      let whereConditions: any[] = [];

      // Post type filter
      if (postType !== 'all') {
        whereConditions.push(eq(socialPosts.postType, postType));
      }

      // Location filter (simplified for now)
      if (location === 'neighborhood') {
        // Filter by user's county/state
        const user = await db.select().from(users).where(eq(users.id, userId)).limit(1);
        if (user[0]?.county) {
          whereConditions.push(eq(socialPosts.county, user[0].county));
        }
      }

      // Search filter
      if (search) {
        whereConditions.push(
          or(
            like(socialPosts.content, `%${search}%`),
            sql`${socialPosts.tags} @> ${JSON.stringify([search])}`
          )
        );
      }

      // Base query
      let query = db
        .select({
          post: socialPosts,
          author: {
            id: users.id,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
            role: users.role,
          },
          reactionCount: sql<number>`count(distinct ${postReactions.id})`,
          commentCount: sql<number>`count(distinct ${postComments.id})`,
          shareCount: sql<number>`count(distinct ${postShares.id})`,
        })
        .from(socialPosts)
        .leftJoin(users, eq(socialPosts.authorId, users.id))
        .leftJoin(postReactions, eq(socialPosts.id, postReactions.postId))
        .leftJoin(postComments, eq(socialPosts.id, postComments.postId))
        .leftJoin(postShares, eq(socialPosts.id, postShares.postId))
        .where(
          and(
            eq(socialPosts.isArchived, false),
            ...whereConditions
          )
        )
        .groupBy(socialPosts.id, users.id);

      // Apply sorting - temporarily return empty for now
      const posts: any[] = [];

      // Get user reactions for each post
      const postIds = posts.map(p => p.post.id);
      const userReactions = postIds.length > 0 ? await db
        .select()
        .from(postReactions)
        .where(
          and(
            inArray(postReactions.postId, postIds),
            eq(postReactions.userId, userId)
          )
        ) : [];

      // Get all reactions for each post
      const allReactions = postIds.length > 0 ? await db
        .select()
        .from(postReactions)
        .where(inArray(postReactions.postId, postIds)) : [];

      // Combine data
      const postsWithReactions = posts.map(({ post, author, reactionCount, commentCount, shareCount }) => ({
        ...post,
        author,
        reactions: allReactions.filter(r => r.postId === post.id),
        userReaction: userReactions.find(r => r.postId === post.id),
        _count: {
          reactions: parseInt(reactionCount.toString()),
          comments: parseInt(commentCount.toString()),
          shares: parseInt(shareCount.toString()),
        },
      }));

      res.json(postsWithReactions);
    } catch (error) {
      console.error("Error fetching social feed:", error);
      res.status(500).json({ message: "Failed to fetch social feed" });
    }
  });

  // Create new post
  app.post("/api/social/posts", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const user = req.user as User;

      const postData = {
        ...req.body,
        authorId: userId,
        county: user.county,
        state: user.state,
      };

      const [post] = await db
        .insert(socialPosts)
        .values(postData)
        .returning();

      res.json(post);
    } catch (error) {
      console.error("Error creating post:", error);
      res.status(500).json({ message: "Failed to create post" });
    }
  });

  // Get single post
  app.get("/api/social/posts/:postId", async (req, res) => {
    try {
      const { postId } = req.params;

      const [post] = await db
        .select({
          post: socialPosts,
          author: {
            id: users.id,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
            role: users.role,
          },
        })
        .from(socialPosts)
        .leftJoin(users, eq(socialPosts.authorId, users.id))
        .where(eq(socialPosts.id, postId))
        .limit(1);

      if (!post) {
        return res.status(404).json({ message: "Post not found" });
      }

      // Get reactions and comments count
      const [reactionCount] = await db
        .select({ count: count() })
        .from(postReactions)
        .where(eq(postReactions.postId, postId));

      const [commentCount] = await db
        .select({ count: count() })
        .from(postComments)
        .where(eq(postComments.postId, postId));

      const [shareCount] = await db
        .select({ count: count() })
        .from(postShares)
        .where(eq(postShares.postId, postId));

      const postWithCounts = {
        ...post.post,
        author: post.author,
        _count: {
          reactions: reactionCount.count,
          comments: commentCount.count,
          shares: shareCount.count,
        },
      };

      res.json(postWithCounts);
    } catch (error) {
      console.error("Error fetching post:", error);
      res.status(500).json({ message: "Failed to fetch post" });
    }
  });

  // React to post
  app.post("/api/social/posts/:postId/reactions", isAuthenticated, async (req: any, res) => {
    try {
      const { postId } = req.params;
      const { reactionType } = req.body;
      const userId = req.user.id;

      // Check if user already reacted
      const [existingReaction] = await db
        .select()
        .from(postReactions)
        .where(
          and(
            eq(postReactions.postId, postId),
            eq(postReactions.userId, userId)
          )
        )
        .limit(1);

      if (existingReaction) {
        // Update existing reaction
        await db
          .update(postReactions)
          .set({ reactionType })
          .where(eq(postReactions.id, existingReaction.id));
      } else {
        // Create new reaction
        await db
          .insert(postReactions)
          .values({
            postId,
            userId,
            reactionType,
          });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error reacting to post:", error);
      res.status(500).json({ message: "Failed to react to post" });
    }
  });

  // Remove reaction from post
  app.delete("/api/social/posts/:postId/reactions", isAuthenticated, async (req: any, res) => {
    try {
      const { postId } = req.params;
      const userId = req.user.id;

      await db
        .delete(postReactions)
        .where(
          and(
            eq(postReactions.postId, postId),
            eq(postReactions.userId, userId)
          )
        );

      res.json({ success: true });
    } catch (error) {
      console.error("Error removing reaction:", error);
      res.status(500).json({ message: "Failed to remove reaction" });
    }
  });

  // Get comments for a post
  app.get("/api/social/posts/:postId/comments", async (req, res) => {
    try {
      const { postId } = req.params;

      const comments = await db
        .select({
          comment: postComments,
          author: {
            id: users.id,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
            role: users.role,
          },
          reactionCount: sql<number>`count(distinct ${commentReactions.id})`,
        })
        .from(postComments)
        .leftJoin(users, eq(postComments.authorId, users.id))
        .leftJoin(commentReactions, eq(postComments.id, commentReactions.commentId))
        .where(
          and(
            eq(postComments.postId, postId),
            sql`${postComments.parentCommentId} IS NULL` // Only top-level comments
          )
        )
        .groupBy(postComments.id, users.id)
        .orderBy(desc(postComments.createdAt));

      // Get replies for each comment
      const commentIds = comments.map(c => c.comment.id);
      const replies = commentIds.length > 0 ? await db
        .select({
          comment: postComments,
          author: {
            id: users.id,
            firstName: users.firstName,
            lastName: users.lastName,
            profileImageUrl: users.profileImageUrl,
            role: users.role,
          },
        })
        .from(postComments)
        .leftJoin(users, eq(postComments.authorId, users.id))
        .where(inArray(postComments.parentCommentId, commentIds))
        .orderBy(postComments.createdAt) : [];

      // Organize replies under their parent comments
      const commentsWithReplies = comments.map(({ comment, author, reactionCount }) => ({
        ...comment,
        author,
        replies: replies.filter(r => r.comment.parentCommentId === comment.id).map(r => ({
          ...r.comment,
          author: r.author,
          reactions: [],
          _count: { reactions: 0, replies: 0 }
        })),
        reactions: [],
        _count: { 
          reactions: parseInt(reactionCount.toString()),
          replies: replies.filter(r => r.comment.parentCommentId === comment.id).length
        }
      }));

      res.json(commentsWithReplies);
    } catch (error) {
      console.error("Error fetching comments:", error);
      res.status(500).json({ message: "Failed to fetch comments" });
    }
  });

  // Create comment
  app.post("/api/social/posts/:postId/comments", isAuthenticated, async (req: any, res) => {
    try {
      const { postId } = req.params;
      const userId = req.user.id;
      const { content, parentCommentId } = req.body;

      const [comment] = await db
        .insert(postComments)
        .values({
          postId,
          authorId: userId,
          content,
          parentCommentId: parentCommentId || null,
        })
        .returning();

      res.json(comment);
    } catch (error) {
      console.error("Error creating comment:", error);
      res.status(500).json({ message: "Failed to create comment" });
    }
  });

  // Share post
  app.post("/api/social/posts/:postId/share", isAuthenticated, async (req: any, res) => {
    try {
      const { postId } = req.params;
      const userId = req.user.id;
      const { shareMessage, privacyLevel } = req.body;

      // Check if post exists
      const [post] = await db
        .select()
        .from(socialPosts)
        .where(eq(socialPosts.id, postId))
        .limit(1);

      if (!post) {
        return res.status(404).json({ message: "Post not found" });
      }

      // Create share record
      const [share] = await db
        .insert(postShares)
        .values({
          postId,
          userId,
          shareMessage: shareMessage || null,
          privacyLevel: privacyLevel || 'neighborhood',
        })
        .returning();

      // Update share count
      await db
        .update(socialPosts)
        .set({
          shareCount: sql`${socialPosts.shareCount} + 1`,
          updatedAt: new Date(),
        })
        .where(eq(socialPosts.id, postId));

      res.json(share);
    } catch (error) {
      console.error("Error sharing post:", error);
      res.status(500).json({ message: "Failed to share post" });
    }
  });

  // Pin/unpin post (moderators only)
  app.patch("/api/social/posts/:postId/pin", isAuthenticated, requirePermission('canModerateContent'), async (req: any, res) => {
    try {
      const { postId } = req.params;
      const { isPinned } = req.body;

      await db
        .update(socialPosts)
        .set({
          isPinned: isPinned,
          updatedAt: new Date(),
        })
        .where(eq(socialPosts.id, postId));

      res.json({ success: true });
    } catch (error) {
      console.error("Error pinning post:", error);
      res.status(500).json({ message: "Failed to pin post" });
    }
  });

  // Delete post
  app.delete("/api/social/posts/:postId", isAuthenticated, async (req: any, res) => {
    try {
      const { postId } = req.params;
      const userId = req.user.id;

      // Check if user is the author or has moderation permissions
      const [post] = await db
        .select()
        .from(socialPosts)
        .where(eq(socialPosts.id, postId))
        .limit(1);

      if (!post) {
        return res.status(404).json({ message: "Post not found" });
      }

      // Check permissions
      const user = req.user as User;
      const isAuthor = post.authorId === userId;
      const canModerate = user.role && ['moderator', 'ops_admin', 'super_admin', 'head_admin', 'community_moderator', 'community_leader'].includes(user.role);

      if (!isAuthor && !canModerate) {
        return res.status(403).json({ message: "Not authorized to delete this post" });
      }

      // Delete post (cascade will handle related records)
      await db
        .delete(socialPosts)
        .where(eq(socialPosts.id, postId));

      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting post:", error);
      res.status(500).json({ message: "Failed to delete post" });
    }
  });

  // React to comment
  app.post("/api/social/comments/:commentId/reactions", isAuthenticated, async (req: any, res) => {
    try {
      const { commentId } = req.params;
      const { reactionType } = req.body;
      const userId = req.user.id;

      // Check if user already reacted
      const [existingReaction] = await db
        .select()
        .from(commentReactions)
        .where(
          and(
            eq(commentReactions.commentId, commentId),
            eq(commentReactions.userId, userId)
          )
        )
        .limit(1);

      if (existingReaction) {
        // Update existing reaction
        await db
          .update(commentReactions)
          .set({ reactionType })
          .where(eq(commentReactions.id, existingReaction.id));
      } else {
        // Create new reaction
        await db
          .insert(commentReactions)
          .values({
            commentId,
            userId,
            reactionType,
          });
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error reacting to comment:", error);
      res.status(500).json({ message: "Failed to react to comment" });
    }
  });

  // Remove reaction from comment
  app.delete("/api/social/comments/:commentId/reactions", isAuthenticated, async (req: any, res) => {
    try {
      const { commentId } = req.params;
      const userId = req.user.id;

      await db
        .delete(commentReactions)
        .where(
          and(
            eq(commentReactions.commentId, commentId),
            eq(commentReactions.userId, userId)
          )
        );

      res.json({ success: true });
    } catch (error) {
      console.error("Error removing reaction:", error);
      res.status(500).json({ message: "Failed to remove reaction" });
    }
  });

  // Submit content report
  app.post("/api/social/reports", isAuthenticated, async (req: any, res) => {
    try {
      const userId = req.user.id;
      const reportData = {
        ...req.body,
        reporterId: userId,
        status: 'pending',
      };

      const [report] = await db
        .insert(contentReports)
        .values(reportData)
        .returning();

      res.json(report);
    } catch (error) {
      console.error("Error submitting report:", error);
      res.status(500).json({ message: "Failed to submit report" });
    }
  });

  // Get trending topics/hashtags
  app.get("/api/social/trending", async (req, res) => {
    try {
      // Return empty array since social posts table doesn't exist yet
      res.json([]);
    } catch (error) {
      console.error("Error fetching trending topics:", error);
      res.json([]); // Return empty array on error
    }
  });

  // Get neighborhood stats
  app.get("/api/social/neighborhood-stats", isAuthenticated, async (req: any, res) => {
    try {
      const user = req.user as User;

      // Get stats for user's neighborhood/county
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      const [postsToday] = await db
        .select({ count: count() })
        .from(socialPosts)
        .where(
          and(
            eq(socialPosts.county, user.county || ''),
            sql`${socialPosts.createdAt} >= ${today}`
          )
        );

      const [activeMembers] = await db
        .select({ count: count() })
        .from(users)
        .where(eq(users.county, user.county || ''));

      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const [newMembers] = await db
        .select({ count: count() })
        .from(users)
        .where(
          and(
            eq(users.county, user.county || ''),
            sql`${users.createdAt} >= ${thirtyDaysAgo}`
          )
        );

      const stats = {
        postsToday: postsToday.count,
        activeMembers: activeMembers.count,
        newMembers: newMembers.count,
      };

      res.json(stats);
    } catch (error) {
      console.error("Error fetching neighborhood stats:", error);
      res.json({
        postsToday: 0,
        activeMembers: 0,
        newMembers: 0,
      });
    }
  });
}

