import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { StoryGenerator } from "@/components/StoryGenerator";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Link } from "wouter";
import { 
  ArrowLeft, 
  FileText, 
  Eye, 
  Share2, 
  Edit,
  Trash2,
  Copy,
  Star
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

interface GeneratedStory {
  id: string;
  title: string;
  content: string;
  templateId: string;
  isPublic: boolean;
  isPinned: boolean;
  viewCount: number;
  shareCount: number;
  createdAt: string;
  updatedAt: string;
}

export default function StoryGeneratorPage() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [selectedStory, setSelectedStory] = useState<GeneratedStory | null>(null);

  // Fetch user's saved stories
  const { data: savedStories = [], isLoading: isLoadingStories } = useQuery({
    queryKey: ["/api/stories"],
    retry: false,
  });

  // Save story mutation
  const saveStoryMutation = useMutation({
    mutationFn: async (storyData: any) => {
      return await apiRequest("/api/stories", "POST", storyData);
    },
    onSuccess: () => {
      toast({
        title: "Story Saved",
        description: "Your professional story has been saved successfully.",
        variant: "default",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/stories"] });
    },
    onError: (error) => {
      console.error("Save story error:", error);
      toast({
        title: "Save Failed",
        description: "Failed to save your story. Please try again.",
        variant: "destructive",
      });
    },
  });

  // Delete story mutation
  const deleteStoryMutation = useMutation({
    mutationFn: async (storyId: string) => {
      return await apiRequest(`/api/stories/${storyId}`, "DELETE");
    },
    onSuccess: () => {
      toast({
        title: "Story Deleted",
        description: "Your story has been removed successfully.",
        variant: "default",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/stories"] });
      setSelectedStory(null);
    },
    onError: (error) => {
      console.error("Delete story error:", error);
      toast({
        title: "Delete Failed",
        description: "Failed to delete the story. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleStoryGenerated = async (story: any) => {
    // Auto-save generated stories
    await saveStoryMutation.mutateAsync({
      title: story.title,
      content: story.content,
      templateId: story.templateId,
      userInputs: story.userInputs || {},
      isPublic: false,
      isPinned: false,
    });
  };

  const handleCopyStory = (content: string) => {
    navigator.clipboard.writeText(content);
    toast({
      title: "Copied!",
      description: "Story content copied to clipboard.",
      variant: "default",
    });
  };

  const handleDeleteStory = (storyId: string) => {
    if (confirm("Are you sure you want to delete this story?")) {
      deleteStoryMutation.mutate(storyId);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-navy-900 to-navy-800 flex items-center justify-center">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <p className="text-center text-gray-600">Please log in to access the story generator.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-navy-900 to-navy-800 p-4">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center gap-4 mb-4">
            <Link href="/contractor-dashboard">
              <Button variant="outline" size="sm" className="border-gray-600 text-gray-300 hover:bg-gray-700">
                <ArrowLeft className="h-4 w-4 mr-2" />
                Back to Dashboard
              </Button>
            </Link>
          </div>
          <div className="text-center">
            <h1 className="text-4xl font-bold text-white mb-4">Professional Story Generator</h1>
            <p className="text-gray-300 text-lg max-w-2xl mx-auto">
              Create compelling professional narratives to enhance your profile and connect with potential clients. 
              Choose from different story templates and let AI help craft your unique story.
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Story Generator */}
          <div className="lg:col-span-2">
            <Card className="bg-navy-700 border-navy-600">
              <CardHeader>
                <CardTitle className="text-white flex items-center gap-2">
                  <FileText className="h-5 w-5" />
                  Generate Your Story
                </CardTitle>
              </CardHeader>
              <CardContent>
                <StoryGenerator />
              </CardContent>
            </Card>
          </div>

          {/* Saved Stories */}
          <div>
            <Card className="bg-navy-700 border-navy-600">
              <CardHeader>
                <CardTitle className="text-white">Your Stories</CardTitle>
              </CardHeader>
              <CardContent>
                {isLoadingStories ? (
                  <div className="space-y-3">
                    {[1, 2, 3].map(i => (
                      <div key={i} className="animate-pulse">
                        <div className="h-4 bg-gray-600 rounded mb-2"></div>
                        <div className="h-3 bg-gray-700 rounded w-3/4"></div>
                      </div>
                    ))}
                  </div>
                ) : (savedStories as GeneratedStory[]).length === 0 ? (
                  <div className="text-center py-8">
                    <FileText className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-400 mb-4">No stories yet</p>
                    <p className="text-gray-500 text-sm">Generate your first professional story using the form</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {(savedStories as GeneratedStory[]).map((story: GeneratedStory) => (
                      <div 
                        key={story.id}
                        className={`p-3 border rounded-lg cursor-pointer transition-colors ${
                          selectedStory?.id === story.id 
                            ? 'border-blue-500 bg-blue-900/20' 
                            : 'border-gray-600 hover:border-gray-500'
                        }`}
                        onClick={() => setSelectedStory(story)}
                      >
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <h4 className="text-white font-medium text-sm mb-1">
                              {story.title}
                            </h4>
                            <p className="text-gray-400 text-xs mb-2">
                              {formatDate(story.createdAt)}
                            </p>
                            <div className="flex items-center gap-2 text-xs">
                              {story.isPinned && (
                                <Badge variant="outline" className="border-yellow-500 text-yellow-500">
                                  <Star className="h-3 w-3 mr-1" />
                                  Pinned
                                </Badge>
                              )}
                              {story.isPublic && (
                                <Badge variant="outline" className="border-green-500 text-green-500">
                                  Public
                                </Badge>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Story Actions */}
            {selectedStory && (
              <Card className="bg-navy-700 border-navy-600 mt-4">
                <CardHeader>
                  <CardTitle className="text-white text-lg">{selectedStory.title}</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="space-y-4">
                    <div className="text-gray-300 text-sm leading-relaxed">
                      {selectedStory.content}
                    </div>

                    <div className="flex items-center gap-2 text-xs text-gray-400">
                      <Eye className="h-3 w-3" />
                      {selectedStory.viewCount} views
                      <Share2 className="h-3 w-3 ml-2" />
                      {selectedStory.shareCount} shares
                    </div>

                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        variant="outline"
                        className="border-gray-600 text-gray-300 hover:bg-gray-700"
                        onClick={() => handleCopyStory(selectedStory.content)}
                      >
                        <Copy className="h-3 w-3 mr-1" />
                        Copy
                      </Button>
                      <Button
                        size="sm"
                        variant="outline"
                        className="border-red-600 text-red-400 hover:bg-red-900/20"
                        onClick={() => handleDeleteStory(selectedStory.id)}
                        disabled={deleteStoryMutation.isPending}
                      >
                        <Trash2 className="h-3 w-3 mr-1" />
                        Delete
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

server/websocket.ts.content:
import { WebSocketServer, WebSocket } from 'ws';
import { Server } from 'http';
import { storage } from './storage';

interface WebSocketClient {
  ws: WebSocket;
  userId?: string;
  sessionId?: string;
  conversationId?: string;
}

// In-memory store for rooms and their associated clients
const rooms: Map<string, Set<WebSocket>> = new Map();

class WebSocketManager {
  private wss: WebSocketServer;
  private clients: Map<string, WebSocketClient> = new Map();

  constructor(server: Server) {
    this.wss = new WebSocketServer({
      server,
      path: '/ws',
      verifyClient: (info: any) => {
        // Only allow connections in production environments
        const isDevelopment = process.env.NODE_ENV !== 'production';
        if (isDevelopment) {
          return false; // Block all WebSocket connections in development
        }
        return true;
      },
      // Handle protocols properly
      handleProtocols: (protocols: Set<string>) => {
        return protocols.size > 0 ? Array.from(protocols)[0] : '';
      }
    });

    this.wss.on('connection', this.handleConnection.bind(this));
    this.wss.on('error', (error) => {
      console.error('WebSocket server error:', error);
    });

    console.log('WebSocket server initialized on /ws');
  }

  private handleConnection(ws: WebSocket, request: any) {
    const clientId = this.generateClientId();
    const client: WebSocketClient = { ws };

    this.clients.set(clientId, client);
    console.log(`WebSocket client connected: ${clientId}`);

    // Handle incoming messages
    ws.on('message', async (data) => {
      try {
        const message = JSON.parse(data.toString());
        await this.handleMessage(clientId, message);
      } catch (error) {
        console.error('Error handling WebSocket message:', error);
        // Send error response to client
        this.sendToClient(clientId, {
          type: 'error',
          message: 'Failed to process message'
        });
      }
    });

    // Handle client disconnect
    ws.on('close', (code, reason) => {
      this.clients.delete(clientId);
      // Remove client from any rooms they were in
      rooms.forEach((clientsInRoom, roomId) => {
        clientsInRoom.delete(ws);
        if (clientsInRoom.size === 0) {
          rooms.delete(roomId);
        }
      });
      console.log(`WebSocket client disconnected: ${clientId}, code: ${code}, reason: ${reason}`);
    });

    // Handle errors
    ws.on('error', (error) => {
      console.error(`WebSocket error for client ${clientId}:`, error);
      this.clients.delete(clientId);
      // Remove client from any rooms they were in
      rooms.forEach((clientsInRoom, roomId) => {
        clientsInRoom.delete(ws);
        if (clientsInRoom.size === 0) {
          rooms.delete(roomId);
        }
      });
    });

    // Send initial connection confirmation
    this.sendToClient(clientId, {
      type: 'connection_established',
      clientId,
      timestamp: new Date().toISOString()
    });
  }

  private async handleMessage(clientId: string, message: any) {
    const client = this.clients.get(clientId);
    if (!client) return;

    switch (message.type) {
      case 'authenticate':
        // Authenticate user and associate with WebSocket
        client.userId = message.userId;
        client.sessionId = message.sessionId;

        // Send unread notification count
        if (client.userId) {
          const notifications = await storage.getUserNotifications(client.userId, true);
          this.sendToClient(clientId, {
            type: 'notification_count',
            count: notifications.length
          });
        }
        break;

      case 'ping':
        this.sendToClient(clientId, { type: 'pong' });
        break;

      case 'join_conversation':
        // Join a conversation room for real-time messages
        client.conversationId = message.conversationId;
        const roomId = `conversation_${message.conversationId}`;
        if (!rooms.has(roomId)) {
          rooms.set(roomId, new Set());
        }
        rooms.get(roomId)!.add(client.ws);
        break;

      case 'leave_conversation':
        // Leave conversation room
        const leaveRoomId = `conversation_${client.conversationId}`;
        if (rooms.has(leaveRoomId)) {
          rooms.get(leaveRoomId)!.delete(client.ws);
          if (rooms.get(leaveRoomId)!.size === 0) {
            rooms.delete(leaveRoomId);
          }
        }
        delete client.conversationId;
        break;

      case 'chat_message':
        // Handle chat messages
        handleChatMessage(client.ws, message);
        break;

      default:
        console.log('Unknown WebSocket message type:', message.type);
    }
  }

  private sendToClient(clientId: string, message: any) {
    const client = this.clients.get(clientId);
    if (client && client.ws.readyState === WebSocket.OPEN) {
      client.ws.send(JSON.stringify(message));
    }
  }

  // Public methods for sending notifications
  public async sendNotificationToUser(userId: string, notification: any) {
    const userClients = Array.from(this.clients.entries())
      .filter(([_, client]) => client.userId === userId);

    for (const [clientId, client] of userClients) {
      if (client.ws.readyState === WebSocket.OPEN) {
        this.sendToClient(clientId, {
          type: 'new_notification',
          notification
        });
      }
    }
  }

  public async sendMessageToConversation(conversationId: string, message: any) {
    const roomId = `conversation_${conversationId}`;
    broadcastToRoom(roomId, {
      type: 'new_message',
      message,
      timestamp: new Date()
    });
  }

  public async sendTransactionUpdate(userId: string, transaction: any) {
    const userClients = Array.from(this.clients.entries())
      .filter(([_, client]) => client.userId === userId);

    for (const [clientId, client] of userClients) {
      if (client.ws.readyState === WebSocket.OPEN) {
        this.sendToClient(clientId, {
          type: 'transaction_update',
          transaction
        });
      }
    }
  }

  public async broadcastListingUpdate(listing: any) {
    // Broadcast to all connected clients about new listings
    for (const [clientId, client] of Array.from(this.clients.entries())) {
      if (client.ws.readyState === WebSocket.OPEN) {
        this.sendToClient(clientId, {
          type: 'listing_update',
          listing
        });
      }
    }
  }

  private generateClientId(): string {
    return Math.random().toString(36).substring(2, 15) +
           Math.random().toString(36).substring(2, 15);
  }

  // Get connected users count
  public getConnectedUsersCount(): number {
    return Array.from(this.clients.values())
      .filter(client => client.userId).length;
  }

  // Get online status for a user
  public isUserOnline(userId: string): boolean {
    return Array.from(this.clients.values())
      .some(client => client.userId === userId && client.ws.readyState === WebSocket.OPEN);
  }
}

export { WebSocketManager };

// Helper function to broadcast messages to a specific room
export const broadcastToRoom = (roomId: string, message: any) => {
  if (rooms.has(roomId)) {
    const clients = rooms.get(roomId)!;
    clients.forEach(client => {
      if (client.readyState === WebSocket.OPEN) {
        client.send(JSON.stringify(message));
      }
    });
  }
};

// Handler for incoming chat messages
export const handleChatMessage = (ws: WebSocket, data: any) => {
  const { conversationId, message, senderId } = data;

  // TODO: Store message in database
  console.log(`Received message from ${senderId} in conversation ${conversationId}: ${message}`);

  // Broadcast to conversation participants
  broadcastToRoom(`conversation_${conversationId}`, {
    type: 'new_message',
    message,
    senderId,
    timestamp: new Date()
  });
};

client/src/components/PWAInstallPrompt.t.content:
import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Download, X, Smartphone } from 'lucide-react';
import { useIsMobile } from '@/hooks/use-mobile';

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export function PWAInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [showPrompt, setShowPrompt] = useState(false);
  const [isInstalled, setIsInstalled] = useState(false);
  const isMobile = useIsMobile();

  useEffect(() => {
    // Check if already installed
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsInstalled(true);
      return;
    }

    // Listen for the beforeinstallprompt event
    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e as BeforeInstallPromptEvent);

      // Show prompt after a short delay and only on mobile
      if (isMobile) {
        setTimeout(() => setShowPrompt(true), 3000);
      }
    };

    window.addEventListener('beforeinstallprompt', handler);

    // Listen for app installed event
    window.addEventListener('appinstalled', () => {
      setIsInstalled(true);
      setShowPrompt(false);
    });

    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('appinstalled', () => {});
    };
  }, [isMobile]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const choiceResult = await deferredPrompt.userChoice;

      if (choiceResult.outcome === 'accepted') {
        setShowPrompt(false);
      }

      setDeferredPrompt(null);
    }
  };

  const handleDismiss = () => {
    setShowPrompt(false);
    // Don't show again for this session
    sessionStorage.setItem('pwa-prompt-dismissed', 'true');
  };

  // Don't show if already installed, not mobile, or previously dismissed
  if (isInstalled || !isMobile || !showPrompt || sessionStorage.getItem('pwa-prompt-dismissed')) {
    return null;
  }

  return (
    <div className="fixed bottom-4 left-4 right-4 z-50 animate-in slide-in-from-bottom duration-300">
      <Card className="bg-gradient-to-r from-orange-500 to-orange-600 border-none text-white shadow-2xl">
        <CardContent className="p-4">
          <div className="flex items-start justify-between gap-3">
            <div className="flex items-center gap-3 flex-1">
              <div className="bg-white/20 p-2 rounded-lg">
                <Smartphone className="h-6 w-6" />
              </div>
              <div className="flex-1">
                <h3 className="font-semibold text-sm mb-1">Install TradeScout App</h3>
                <p className="text-xs text-orange-100 leading-relaxed">
                  Get the full app experience with faster loading, offline access, and home screen convenience
                </p>
              </div>
            </div>
            <Button
              variant="ghost"
              size="sm"
              onClick={handleDismiss}
              className="text-white hover:bg-white/20 h-8 w-8 p-0 flex-shrink-0"
            >
              <X className="h-4 w-4" />
            </Button>
          </div>

          <div className="flex gap-2 mt-3">
            <Button
              onClick={handleInstall}
              className="bg-white text-orange-600 hover:bg-orange-50 flex-1 text-sm font-medium"
              size="sm"
            >
              <Download className="h-4 w-4 mr-2" />
              Install App
            </Button>
            <Button
              onClick={handleDismiss}
              variant="ghost"
              className="text-white hover:bg-white/20 text-sm"
              size="sm"
            >
              Maybe Later
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

