    console.log("✅ Handmade marketplace data seeded successfully!");

  } catch (error) {
    console.error("❌ Error seeding handmade data:", error);
    throw error;
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  seedHandmadeData()
    .then(() => process.exit(0))
    .catch((error) => {
      console.error(error);
      process.exit(1);
    });
}

export { seedHandmadeData };

