                          </p>
                        </div>
                        <Badge className={payout.status === 'completed' ? 'bg-emerald-500' : 'bg-yellow-500'}>
                          {payout.status}
                        </Badge>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <Calendar className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                    <h3 className="text-xl font-semibold text-white mb-2">No payouts yet</h3>
                    <p className="text-gray-400">Payouts are processed monthly once you reach $50</p>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

client/src/pages/admin-address-verificat.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { CheckCircle, XCircle, Clock, FileText, Mail, Phone, UserCheck, Calendar } from "lucide-react";

interface AddressVerification {
  id: string;
  userId: string;
  fullAddress: string;
  city: string;
  state: string;
  zipCode: string;
  verificationMethod: string;
  status: 'pending' | 'submitted' | 'approved' | 'rejected' | 'expired';
  submittedAt?: string;
  reviewedAt?: string;
  approvedAt?: string;
  deadline: string;
  adminNotes?: string;
  postcardSentAt?: string;
  postcardVerifiedAt?: string;
  createdAt: string;
}

interface User {
  id: string;
  email: string;
  firstName?: string;
  lastName?: string;
  addressVerified: boolean;
}

interface VerificationWithUser {
  verification: AddressVerification;
  user: User;
}

export default function AdminAddressVerifications() {
  const [statusFilter, setStatusFilter] = useState("all");
  const [selectedVerification, setSelectedVerification] = useState<VerificationWithUser | null>(null);
  const [reviewStatus, setReviewStatus] = useState<string>("");
  const [adminNotes, setAdminNotes] = useState("");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Get address verifications
  const { data: verifications, isLoading } = useQuery({
    queryKey: ['/api/admin/address-verifications', statusFilter],
    queryFn: () => apiRequest(`/api/admin/address-verifications?status=${statusFilter}`),
  });

  // Update verification mutation
  const updateVerificationMutation = useMutation({
    mutationFn: async ({ id, status, adminNotes }: { id: string; status: string; adminNotes: string }) => {
      return await apiRequest(`/api/admin/address-verifications/${id}`, 'PUT', { status, adminNotes });
    },
    onSuccess: () => {
      toast({
        title: "Verification Updated",
        description: "The address verification has been updated successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/address-verifications'] });
      setSelectedVerification(null);
      setReviewStatus("");
      setAdminNotes("");
    },
    onError: (error: any) => {
      toast({
        title: "Update Failed",
        description: error.message || "Failed to update verification",
        variant: "destructive",
      });
    },
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'approved':
        return <CheckCircle className="w-4 h-4 text-green-600" />;
      case 'rejected':
        return <XCircle className="w-4 h-4 text-red-600" />;
      case 'expired':
        return <XCircle className="w-4 h-4 text-orange-600" />;
      default:
        return <Clock className="w-4 h-4 text-yellow-600" />;
    }
  };

  const getStatusBadge = (status: string) => {
    const variants = {
      pending: "secondary",
      submitted: "default",
      approved: "default",
      rejected: "destructive",
      expired: "destructive",
    } as const;

    const colors = {
      pending: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200",
      submitted: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200",
      approved: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200",
      rejected: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200",
      expired: "bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-200",
    };

    return (
      <Badge className={colors[status as keyof typeof colors] || colors.pending}>
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    );
  };

  const getMethodIcon = (method: string) => {
    switch (method) {
      case 'postcard':
        return <Mail className="w-4 h-4" />;
      case 'phone_verification':
        return <Phone className="w-4 h-4" />;
      default:
        return <FileText className="w-4 h-4" />;
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  const getDaysRemaining = (deadline: string) => {
    const now = new Date();
    const deadlineDate = new Date(deadline);
    const daysRemaining = Math.ceil((deadlineDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
    return daysRemaining;
  };

  const handleReview = () => {
    if (!selectedVerification || !reviewStatus) return;

    updateVerificationMutation.mutate({
      id: selectedVerification.verification.id,
      status: reviewStatus,
      adminNotes,
    });
  };

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600 dark:text-gray-400">Loading address verifications...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Address Verifications</h1>
        <p className="text-gray-600 dark:text-gray-400 mt-2">
          Manage user address verification requests and monitor platform compliance.
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {['pending', 'submitted', 'approved', 'rejected'].map((status) => {
          const count = verifications?.filter((v: VerificationWithUser) => v.verification.status === status).length || 0;
          return (
            <Card key={status}>
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-gray-600 dark:text-gray-400 capitalize">{status}</p>
                    <p className="text-2xl font-bold">{count}</p>
                  </div>
                  {getStatusIcon(status)}
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filter Verifications</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4">
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-48">
                <SelectValue placeholder="Filter by status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="submitted">Submitted</SelectItem>
                <SelectItem value="approved">Approved</SelectItem>
                <SelectItem value="rejected">Rejected</SelectItem>
                <SelectItem value="expired">Expired</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Verifications Table */}
      <Card>
        <CardHeader>
          <CardTitle>Address Verification Requests</CardTitle>
          <CardDescription>
            Review and approve user address verification submissions.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>User</TableHead>
                  <TableHead>Address</TableHead>
                  <TableHead>Method</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Deadline</TableHead>
                  <TableHead>Submitted</TableHead>
                  <TableHead>Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {verifications?.map((item: VerificationWithUser) => {
                  const { verification, user } = item;
                  const daysRemaining = getDaysRemaining(verification.deadline);
                  const isOverdue = daysRemaining < 0;

                  return (
                    <TableRow key={verification.id}>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          <UserCheck className="w-4 h-4 text-gray-400" />
                          <div>
                            <p className="font-medium">{user.firstName} {user.lastName}</p>
                            <p className="text-sm text-gray-500">{user.email}</p>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="max-w-xs">
                          <p className="font-medium">{verification.fullAddress}</p>
                          <p className="text-sm text-gray-500">
                            {verification.city}, {verification.state} {verification.zipCode}
                          </p>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          {getMethodIcon(verification.verificationMethod)}
                          <span className="capitalize">
                            {verification.verificationMethod?.replace('_', ' ')}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell>
                        {getStatusBadge(verification.status)}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center space-x-2">
                          <Calendar className="w-4 h-4 text-gray-400" />
                          <div>
                            <p className="text-sm">{formatDate(verification.deadline)}</p>
                            <p className={`text-xs ${isOverdue ? 'text-red-600' : daysRemaining <= 3 ? 'text-orange-600' : 'text-gray-500'}`}>
                              {isOverdue ? `${Math.abs(daysRemaining)} days overdue` : `${daysRemaining} days left`}
                            </p>
                          </div>
                        </div>
                      </TableCell>
                      <TableCell>
                        {verification.submittedAt ? formatDate(verification.submittedAt) : '-'}
                      </TableCell>
                      <TableCell>
                        <Dialog>
                          <DialogTrigger asChild>
                            <Button 
                              variant="outline" 
                              size="sm"
                              onClick={() => {
                                setSelectedVerification(item);
                                setReviewStatus(verification.status);
                                setAdminNotes(verification.adminNotes || "");
                              }}
                            >
                              Review
                            </Button>
                          </DialogTrigger>
                          <DialogContent className="sm:max-w-[600px]">
                            <DialogHeader>
                              <DialogTitle>Review Address Verification</DialogTitle>
                              <DialogDescription>
                                Review and update the status of this address verification request.
                              </DialogDescription>
                            </DialogHeader>

                            {selectedVerification && (
                              <div className="space-y-4">
                                {/* User Info */}
                                <div className="grid grid-cols-2 gap-4">
                                  <div>
                                    <Label className="text-sm font-medium">User</Label>
                                    <p className="text-sm">
                                      {selectedVerification.user.firstName} {selectedVerification.user.lastName}
                                    </p>
                                    <p className="text-sm text-gray-500">{selectedVerification.user.email}</p>
                                  </div>
                                  <div>
                                    <Label className="text-sm font-medium">Current Status</Label>
                                    <div className="mt-1">
                                      {getStatusBadge(selectedVerification.verification.status)}
                                    </div>
                                  </div>
                                </div>

                                {/* Address Info */}
                                <div>
                                  <Label className="text-sm font-medium">Address</Label>
                                  <div className="mt-1 p-3 bg-gray-50 dark:bg-gray-800 rounded-md">
                                    <p>{selectedVerification.verification.fullAddress}</p>
                                    <p className="text-sm text-gray-500">
                                      {selectedVerification.verification.city}, {selectedVerification.verification.state} {selectedVerification.verification.zipCode}
                                    </p>
                                  </div>
                                </div>

                                {/* Verification Details */}
                                <div className="grid grid-cols-2 gap-4">
                                  <div>
                                    <Label className="text-sm font-medium">Method</Label>
                                    <p className="text-sm capitalize">
                                      {selectedVerification.verification.verificationMethod?.replace('_', ' ')}
                                    </p>
                                  </div>
                                  <div>
                                    <Label className="text-sm font-medium">Deadline</Label>
                                    <p className="text-sm">{formatDate(selectedVerification.verification.deadline)}</p>
                                  </div>
                                </div>

                                {/* Review Form */}
                                <div className="space-y-4">
                                  <div>
                                    <Label htmlFor="status">Update Status</Label>
                                    <Select value={reviewStatus} onValueChange={setReviewStatus}>
                                      <SelectTrigger>
                                        <SelectValue placeholder="Select status" />
                                      </SelectTrigger>
                                      <SelectContent>
                                        <SelectItem value="pending">Pending</SelectItem>
                                        <SelectItem value="approved">Approved</SelectItem>
                                        <SelectItem value="rejected">Rejected</SelectItem>
                                      </SelectContent>
                                    </Select>
                                  </div>

                                  <div>
                                    <Label htmlFor="notes">Admin Notes</Label>
                                    <Textarea
                                      id="notes"
                                      placeholder="Add any notes about this verification..."
                                      value={adminNotes}
                                      onChange={(e) => setAdminNotes(e.target.value)}
                                    />
                                  </div>
                                </div>
                              </div>
                            )}

                            <DialogFooter>
                              <Button 
                                onClick={handleReview}
                                disabled={updateVerificationMutation.isPending || !reviewStatus}
                              >
                                {updateVerificationMutation.isPending ? 'Updating...' : 'Update Verification'}
                              </Button>
                            </DialogFooter>
                          </DialogContent>
                        </Dialog>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>

            {(!verifications || verifications.length === 0) && (
              <div className="text-center py-8">
                <p className="text-gray-500 dark:text-gray-400">No address verifications found.</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/ui/input-otp.tsx.content:
import * as React from "react"
import { OTPInput, OTPInputContext } from "input-otp"
import { Dot } from "lucide-react"

import { cn } from "@/lib/utils"

const InputOTP = React.forwardRef<
  React.ElementRef<typeof OTPInput>,
  React.ComponentPropsWithoutRef<typeof OTPInput>
>(({ className, containerClassName, ...props }, ref) => (
  <OTPInput
    ref={ref}
    containerClassName={cn(
      "flex items-center gap-2 has-[:disabled]:opacity-50",
      containerClassName
    )}
    className={cn("disabled:cursor-not-allowed", className)}
    {...props}
  />
))
InputOTP.displayName = "InputOTP"

const InputOTPGroup = React.forwardRef<
  React.ElementRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ className, ...props }, ref) => (
  <div ref={ref} className={cn("flex items-center", className)} {...props} />
))
InputOTPGroup.displayName = "InputOTPGroup"

const InputOTPSlot = React.forwardRef<
  React.ElementRef<"div">,
  React.ComponentPropsWithoutRef<"div"> & { index: number }
>(({ index, className, ...props }, ref) => {
  const inputOTPContext = React.useContext(OTPInputContext)
  const { char, hasFakeCaret, isActive } = inputOTPContext.slots[index]

  return (
    <div
      ref={ref}
      className={cn(
        "relative flex h-10 w-10 items-center justify-center border-y border-r border-input text-sm transition-all first:rounded-l-md first:border-l last:rounded-r-md",
        isActive && "z-10 ring-2 ring-ring ring-offset-background",
        className
      )}
      {...props}
    >
      {char}
      {hasFakeCaret && (
        <div className="pointer-events-none absolute inset-0 flex items-center justify-center">
          <div className="h-4 w-px animate-caret-blink bg-foreground duration-1000" />
        </div>
      )}
    </div>
  )
})
InputOTPSlot.displayName = "InputOTPSlot"

const InputOTPSeparator = React.forwardRef<
  React.ElementRef<"div">,
  React.ComponentPropsWithoutRef<"div">
>(({ ...props }, ref) => (
  <div ref={ref} role="separator" {...props}>
    <Dot />
  </div>
))
InputOTPSeparator.displayName = "InputOTPSeparator"

export { InputOTP, InputOTPGroup, InputOTPSlot, InputOTPSeparator }

client/src/pages/daily-deals-enhanced.ts.content:
import { useState, useEffect } from "react";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { HelpBubble, GuidedTour } from "@/components/ui/help-bubble";
import { useHelpSystem } from "@/hooks/useHelpSystem";
import { 
  Clock, 
  MapPin, 
  Star, 
  Heart, 
  Share2, 
  Tag, 
  TrendingUp,
  Sparkles,
  Target,
  Gift
} from "lucide-react";

interface DailyDeal {
  id: string;
  title: string;
  description: string;
  dealType: string;
  originalPrice: string;
  discountPrice: string;
  discountPercentage: number;
  countyFips: string;
  serviceArea: string[];
  startDate: string;
  endDate: string;
  isActive: boolean;
  maxRedemptions: number;
  currentRedemptions: number;
  views: number;
  clicks: number;
  saves: number;
  featured: boolean;
  tags: string[];
  providerId: string;
  providerType: string;
  priority: number;
}

export default function DailyDealsEnhanced() {
  const [savedDeals, setSavedDeals] = useState<string[]>([]);
  const [selectedCategory, setSelectedCategory] = useState('all');

  const { 
    activeTour, 
    startTour, 
    markTourCompleted, 
    skipTour, 
    tours, 
    shouldShowTour 
  } = useHelpSystem();

  // Auto-start tour for new users
  useEffect(() => {
    if (shouldShowTour('daily-deals')) {
      const timer = setTimeout(() => {
        startTour('daily-deals');
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [shouldShowTour, startTour]);

  const { data: deals = [], isLoading } = useQuery({
    queryKey: ['/api/daily-deals'],
    queryFn: async () => {
      const response = await fetch('/api/daily-deals');
      if (!response.ok) throw new Error('Failed to fetch deals');
      return response.json();
    },
  });

  const handleSaveDeal = (dealId: string) => {
    setSavedDeals(prev => 
      prev.includes(dealId) 
        ? prev.filter(id => id !== dealId)
        : [...prev, dealId]
    );
  };

  const getTimeRemaining = (endDate: string) => {
    const end = new Date(endDate);
    const now = new Date();
    const diff = end.getTime() - now.getTime();

    if (diff <= 0) return 'Expired';

    const hours = Math.floor(diff / (1000 * 60 * 60));
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days} days left`;
    return `${hours} hours left`;
  };

  if (isLoading) {
    return (
      <div className="min-h-screen gradient-bg p-6">
        <div className="max-w-7xl mx-auto">
          <div className="animate-pulse space-y-6">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="h-64 bg-slate-700 rounded-lg"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen gradient-bg p-6" data-testid="daily-deals-page">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="text-center mb-12">
          <div className="flex items-center justify-center space-x-3 mb-6">
            <Sparkles className="w-8 h-8 text-yellow-400" />
            <h1 className="text-4xl md:text-5xl font-bold text-white">Daily Deals</h1>
            <HelpBubble
              id="daily-deals-overview"
              title="Daily Deals & LuckyBucks System"
              content="Discover exclusive deals from local contractors and suppliers. Every purchase earns you LuckyBucks that can be used for future discounts!"
              illustration="lightbulb"
              variant="tip"
              trigger="hover"
              position="bottom"
            />
          </div>
          <p className="text-xl text-slate-300 mb-6 max-w-3xl mx-auto">
            Exclusive discounts on home improvement services and materials. Limited time offers from verified local professionals.
          </p>

          {/* Stats */}
          <div className="flex justify-center space-x-6 mb-8">
            <div className="text-center">
              <div className="text-2xl font-bold text-yellow-400">{deals.length}</div>
              <div className="text-sm text-slate-400">Active Deals</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-400">50%</div>
              <div className="text-sm text-slate-400">Avg Savings</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-400">2.4k</div>
              <div className="text-sm text-slate-400">Happy Customers</div>
            </div>
          </div>
        </div>

        {/* LuckyBucks Banner */}
        <Card className="bg-gradient-to-r from-yellow-500/20 to-orange-500/20 border-yellow-500/30 mb-8">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-yellow-400 rounded-full flex items-center justify-center">
                  <Sparkles className="w-6 h-6 text-yellow-900" />
                </div>
                <div>
                  <h3 className="text-xl font-bold text-white mb-1">Earn LuckyBucks with Every Purchase!</h3>
                  <p className="text-slate-300">Get 5% back in LuckyBucks on all deal purchases. Use them for future discounts!</p>
                </div>
              </div>
              <HelpBubble
                id="luckybucks-system"
                title="LuckyBucks Rewards"
                content="LuckyBucks are our loyalty points system. Earn 5% back on every purchase and use them like cash for future deals. They never expire!"
                illustration="star"
                variant="success"
                trigger="hover"
                position="left"
              />
            </div>
          </CardContent>
        </Card>

        {/* Category Filter */}
        <div className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-semibold text-white">Browse by Category</h2>
            <HelpBubble
              id="category-filter"
              title="Deal Categories"
              content="Filter deals by type: service discounts offer reduced rates on contractor work, while product sales feature discounted materials and supplies."
              illustration="target"
              variant="info"
              trigger="hover"
              position="bottom"
            />
          </div>
          <div className="flex flex-wrap gap-3">
            {['all', 'service_discount', 'product_sale', 'featured'].map((category) => (
              <Button
                key={category}
                variant={selectedCategory === category ? 'default' : 'outline'}
                onClick={() => setSelectedCategory(category)}
                className={selectedCategory === category ? 'bg-orange-500 hover:bg-orange-600' : ''}
              >
                {category === 'all' ? 'All Deals' : 
                 category === 'service_discount' ? 'Service Discounts' :
                 category === 'product_sale' ? 'Product Sales' : 'Featured Deals'}
              </Button>
            ))}
          </div>
        </div>

        {/* Deals Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12 daily-deals-grid">
          {deals
            .filter((deal: DailyDeal) => selectedCategory === 'all' || deal.dealType === selectedCategory || (selectedCategory === 'featured' && deal.featured))
            .map((deal: DailyDeal) => (
            <Card key={deal.id} className="bg-slate-800/50 border-slate-600 hover:border-orange-500/50 transition-all duration-300 deal-card" data-testid={`deal-${deal.id}`}>
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between mb-2">
                  <Badge 
                    className={deal.featured ? 'bg-yellow-500 text-yellow-900' : 'bg-blue-500/20 text-blue-400'}
                  >
                    {deal.featured ? (
                      <>
                        <Star className="w-3 h-3 mr-1" />
                        Featured
                      </>
                    ) : (
                      deal.dealType === 'service_discount' ? 'Service Deal' : 'Product Sale'
                    )}
                  </Badge>
                  <div className="flex items-center space-x-1">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleSaveDeal(deal.id)}
                      className="h-8 w-8 p-0 hover:bg-slate-700"
                    >
                      <Heart className={`w-4 h-4 ${savedDeals.includes(deal.id) ? 'fill-red-500 text-red-500' : 'text-slate-400'}`} />
                    </Button>
                    <Button variant="ghost" size="sm" className="h-8 w-8 p-0 hover:bg-slate-700">
                      <Share2 className="w-4 h-4 text-slate-400" />
                    </Button>
                  </div>
                </div>
                <CardTitle className="text-white text-lg leading-tight">{deal.title}</CardTitle>
              </CardHeader>

              <CardContent className="space-y-4">
                <p className="text-slate-300 text-sm leading-relaxed">{deal.description}</p>

                {/* Pricing */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-2">
                      <span className="text-2xl font-bold text-green-400">${deal.discountPrice}</span>
                      <span className="text-lg text-slate-400 line-through">${deal.originalPrice}</span>
                    </div>
                    <Badge className="bg-green-500/20 text-green-400">
                      {deal.discountPercentage}% OFF
                    </Badge>
                  </div>
                  <div className="text-sm text-green-400">
                    You save ${(parseFloat(deal.originalPrice) - parseFloat(deal.discountPrice)).toFixed(2)}
                  </div>
                </div>

                {/* Location & Time */}
                <div className="space-y-2 text-sm">
                  <div className="flex items-center text-slate-400">
                    <MapPin className="w-4 h-4 mr-2" />
                    <span>{deal.serviceArea.join(', ')}</span>
                  </div>
                  <div className="flex items-center text-slate-400">
                    <Clock className="w-4 h-4 mr-2" />
                    <span className="text-orange-400">{getTimeRemaining(deal.endDate)}</span>
                  </div>
                </div>

                {/* Progress Bar */}
                <div className="space-y-1">
                  <div className="flex justify-between text-sm">
                    <span className="text-slate-400">Claimed</span>
                    <span className="text-slate-400">{deal.currentRedemptions}/{deal.maxRedemptions}</span>
                  </div>
                  <div className="w-full bg-slate-700 rounded-full h-2">
                    <div 
                      className="bg-orange-500 h-2 rounded-full transition-all duration-300"
                      style={{ width: `${(deal.currentRedemptions / deal.maxRedemptions) * 100}%` }}
                    />
                  </div>
                </div>

                {/* Action Button */}
                <Button 
                  className="w-full bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white"
                  data-testid={`claim-deal-${deal.id}`}
                >
                  <Gift className="w-4 h-4 mr-2" />
                  Claim Deal
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Call to Action */}
        <Card className="bg-gradient-to-r from-blue-600/20 to-purple-600/20 border-blue-500/30">
          <CardContent className="p-8 text-center">
            <Target className="w-12 h-12 text-blue-400 mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-white mb-4">Want to Offer Deals?</h2>
            <p className="text-slate-300 mb-6 max-w-2xl mx-auto">
              Join TradeScout as a contractor or supplier and reach thousands of potential customers with exclusive daily deals.
            </p>
            <Button className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3">
              Become a Deal Provider
            </Button>
          </CardContent>
        </Card>

        {/* Guided Tour */}
        <GuidedTour
          steps={tours['daily-deals'] || []}
          isActive={activeTour === 'daily-deals'}
          onComplete={() => markTourCompleted('daily-deals')}
          onSkip={() => skipTour('daily-deals')}
        />
      </div>
    </div>
  );
}

server/routes/contractor-signup.ts.content:
import { Router } from "express";
import { z } from "zod";
import { storage } from "../storage";

const router = Router();

const contractorSignupSchema = z.object({
  companyName: z.string().min(2),
  email: z.string().email(),
  phone: z.string().min(10),
  website: z.string().optional(),
  primaryState: z.string().min(1),
  primaryCounty: z.string().min(1),
  serviceRadius: z.string().min(1),
  yearsInBusiness: z.number().min(0),
  licenseNumber: z.string().min(1),
  insuranceProvider: z.string().min(1),
  primaryTrade: z.string().min(1),
  specialties: z.array(z.string()).min(1),
  about: z.string().min(50),
  preferredContact: z.enum(["phone", "email", "both"]),
  agreeToTerms: z.boolean().refine(val => val === true),
  agreeToVerification: z.boolean().refine(val => val === true)
});

// Handle contractor signup
router.post('/api/contractor-signup', async (req, res) => {
  try {
    console.log('Contractor signup request received:', req.body);

    const validatedData = contractorSignupSchema.parse(req.body);

    // Import storage dynamically to avoid circular dependency
    const { storage } = await import('../storage');

    // Create a contractor application record
    const application = await storage.createContractorApplication({
      companyName: validatedData.companyName,
      email: validatedData.email,
      phone: validatedData.phone,
      website: validatedData.website,
      primaryState: validatedData.primaryState,
      primaryCounty: validatedData.primaryCounty,
      serviceRadius: validatedData.serviceRadius,
      yearsInBusiness: validatedData.yearsInBusiness,
      licenseNumber: validatedData.licenseNumber,
      insuranceProvider: validatedData.insuranceProvider,
      primaryTrade: validatedData.primaryTrade,
      specialties: validatedData.specialties,
      about: validatedData.about,
      preferredContact: validatedData.preferredContact,
      agreeToTerms: validatedData.agreeToTerms,
      agreeToVerification: validatedData.agreeToVerification,
    });

    console.log('Contractor application saved to database:', application.id);

    // TODO: Send email notifications
    // 1. Send email notification to admin
    // 2. Send confirmation email to contractor

    res.json({ 
      success: true, 
      message: 'Application submitted successfully! We will review your application and contact you within 24-48 hours.',
      applicationId: application.id
    });

  } catch (error) {
    console.error('Contractor signup error:', error);

    if (error instanceof z.ZodError) {
      return res.status(400).json({
        success: false,
        message: 'Invalid form data',
        errors: error.errors
      });
    }

    res.status(500).json({
      success: false,
      message: 'Application submission failed'
    });
  }
});

export { router as contractorSignupRouter };

client/src/components/admin/AICodeFixing.content:
import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Bot, CheckCircle, XCircle, Clock, Zap, FileCode, Shield } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface CodeFix {
  id: string;
  issueId: string;
  description: string;
  filePath: string;
  originalCode: string;
  fixedCode: string;
  confidence: number;
  status: 'pending' | 'applied' | 'failed' | 'rejected';
  timestamp: Date;
  aiReasoning: string;
}

export function AICodeFixingDashboard() {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: fixes, isLoading } = useQuery({
    queryKey: ["/api/ai/fixes"],
    refetchInterval: 10000, // Refresh every 10 seconds
  });

  const applyFixMutation = useMutation({
    mutationFn: async (fixId: string) => {
      const response = await fetch(`/api/ai/apply-fix/${fixId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to apply fix');
      return response.json();
    },
    onSuccess: (data) => {
      if (data.success) {
        toast({
          title: "Fix Applied",
          description: "The AI-generated code fix has been applied successfully.",
        });
      } else {
        toast({
          title: "Fix Failed",
          description: "Failed to apply the fix. Check logs for details.",
          variant: "destructive",
        });
      }
      queryClient.invalidateQueries({ queryKey: ["/api/ai/fixes"] });
    },
  });

  const autoFixMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch('/api/ai/auto-fix', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' }
      });
      if (!response.ok) throw new Error('Failed to auto-apply fixes');
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Auto-Fix Complete",
        description: "All high-confidence fixes have been applied automatically.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/ai/fixes"] });
    },
  });

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'pending': return <Clock className="h-4 w-4 text-yellow-500" />;
      case 'applied': return <CheckCircle className="h-4 w-4 text-green-500" />;
      case 'failed': return <XCircle className="h-4 w-4 text-red-500" />;
      case 'rejected': return <XCircle className="h-4 w-4 text-gray-500" />;
      default: return <Clock className="h-4 w-4" />;
    }
  };

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.9) return 'bg-green-500';
    if (confidence >= 0.7) return 'bg-yellow-500';
    return 'bg-red-500';
  };

  const pendingFixes = fixes?.fixes?.filter((fix: CodeFix) => fix.status === 'pending') || [];
  const appliedFixes = fixes?.fixes?.filter((fix: CodeFix) => fix.status === 'applied') || [];
  const highConfidencePending = pendingFixes.filter((fix: CodeFix) => fix.confidence >= 0.9);

  if (isLoading) {
    return (
      <Card className="bg-navy-800 border-navy-600">
        <CardContent className="p-6">
          <div className="flex items-center space-x-2">
            <Bot className="h-5 w-5 animate-spin text-blue-500" />
            <span className="text-white">Loading AI Code Fixing Dashboard...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <Card className="bg-gradient-to-r from-blue-600 to-purple-600 border-none text-white">
        <CardContent className="p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <Bot className="h-8 w-8" />
              <div>
                <h2 className="text-2xl font-bold">AI Code Fixing</h2>
                <p className="opacity-90">Autonomous bug detection and code repair</p>
              </div>
            </div>
            <div className="flex space-x-2">
              <Button
                onClick={() => autoFixMutation.mutate()}
                disabled={autoFixMutation.isPending || highConfidencePending.length === 0}
                className="bg-white text-blue-600 hover:bg-gray-100"
              >
                <Zap className="h-4 w-4 mr-2" />
                Auto-Fix ({highConfidencePending.length})
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card className="bg-navy-700 border-navy-600">
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <Clock className="h-5 w-5 text-yellow-500" />
              <div>
                <p className="text-gray-300 text-sm">Pending Fixes</p>
                <p className="text-2xl font-bold text-white">{pendingFixes.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-navy-700 border-navy-600">
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <CheckCircle className="h-5 w-5 text-green-500" />
              <div>
                <p className="text-gray-300 text-sm">Applied Fixes</p>
                <p className="text-2xl font-bold text-white">{appliedFixes.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-navy-700 border-navy-600">
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <Shield className="h-5 w-5 text-blue-500" />
              <div>
                <p className="text-gray-300 text-sm">High Confidence</p>
                <p className="text-2xl font-bold text-white">{highConfidencePending.length}</p>
              </div>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-navy-700 border-navy-600">
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <FileCode className="h-5 w-5 text-purple-500" />
              <div>
                <p className="text-gray-300 text-sm">Total Fixes</p>
                <p className="text-2xl font-bold text-white">{fixes?.fixes?.length || 0}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Fixes List */}
      <Tabs defaultValue="pending" className="space-y-4">
        <TabsList className="bg-navy-700 border-navy-600">
          <TabsTrigger value="pending" className="data-[state=active]:bg-navy-600">
            Pending ({pendingFixes.length})
          </TabsTrigger>
          <TabsTrigger value="applied" className="data-[state=active]:bg-navy-600">
            Applied ({appliedFixes.length})
          </TabsTrigger>
          <TabsTrigger value="all" className="data-[state=active]:bg-navy-600">
            All Fixes
          </TabsTrigger>
        </TabsList>

        <TabsContent value="pending">
          <ScrollArea className="h-96">
            <div className="space-y-4">
              {pendingFixes.map((fix: CodeFix) => (
                <Card key={fix.id} className="bg-navy-700 border-navy-600">
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-2 mb-2">
                          {getStatusIcon(fix.status)}
                          <h4 className="text-white font-medium">{fix.description}</h4>
                          <Badge className={`text-white ${getConfidenceColor(fix.confidence)}`}>
                            {(fix.confidence * 100).toFixed(0)}% confidence
                          </Badge>
                        </div>
                        <p className="text-gray-300 text-sm mb-2">{fix.filePath}</p>
                        <p className="text-gray-400 text-xs">{fix.aiReasoning}</p>
                      </div>
                      <Button
                        onClick={() => applyFixMutation.mutate(fix.id)}
                        disabled={applyFixMutation.isPending}
                        size="sm"
                        className="bg-green-600 hover:bg-green-700"
                      >
                        Apply Fix
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
              {pendingFixes.length === 0 && (
                <Card className="bg-navy-700 border-navy-600">
                  <CardContent className="p-8 text-center">
                    <Bot className="h-12 w-12 mx-auto text-gray-500 mb-4" />
                    <p className="text-gray-300">No pending fixes available</p>
                  </CardContent>
                </Card>
              )}
            </div>
          </ScrollArea>
        </TabsContent>

        <TabsContent value="applied">
          <ScrollArea className="h-96">
            <div className="space-y-4">
              {appliedFixes.map((fix: CodeFix) => (
                <Card key={fix.id} className="bg-navy-700 border-navy-600">
                  <CardContent className="p-4">
                    <div className="flex items-start space-x-3">
                      {getStatusIcon(fix.status)}
                      <div className="flex-1">
                        <h4 className="text-white font-medium">{fix.description}</h4>
                        <p className="text-gray-300 text-sm">{fix.filePath}</p>
                        <p className="text-gray-400 text-xs">
                          Applied {new Date(fix.timestamp).toLocaleString()}
                        </p>
                      </div>
                      <Badge className="bg-green-600">Applied</Badge>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </ScrollArea>
        </TabsContent>

        <TabsContent value="all">
          <ScrollArea className="h-96">
            <div className="space-y-4">
              {fixes?.fixes?.map((fix: CodeFix) => (
                <Card key={fix.id} className="bg-navy-700 border-navy-600">
                  <CardContent className="p-4">
                    <div className="flex items-start justify-between">
                      <div className="flex items-start space-x-3 flex-1">
                        {getStatusIcon(fix.status)}
                        <div className="flex-1">
                          <h4 className="text-white font-medium">{fix.description}</h4>
                          <p className="text-gray-300 text-sm">{fix.filePath}</p>
                          <p className="text-gray-400 text-xs">
                            {new Date(fix.timestamp).toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <div className="flex space-x-2">
                        <Badge className={`text-white ${getConfidenceColor(fix.confidence)}`}>
                          {(fix.confidence * 100).toFixed(0)}%
                        </Badge>
                        <Badge variant="outline">{fix.status}</Badge>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </ScrollArea>
        </TabsContent>
      </Tabs>
    </div>
  );
}

