@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Scroll-aware navigation */
body.scrolled nav {
  backdrop-filter: blur(20px);
  background: rgba(30, 41, 59, 0.98);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
}

/* Smooth scrolling for page transitions */
html {
  scroll-behavior: smooth;
}

/* Page layout with proper header offset */
.main-content {
  min-height: calc(100vh - var(--header-height));
  padding-top: 0;
}

/* Hero section with parallax capability */
.hero-section {
  transition: transform 0.1s ease-out;
}

/* Scroll area enhancements */
.scroll-area-viewport {
  scroll-padding-top: var(--header-height);
}

/* Enhanced card animations */
.card-enhanced {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-enhanced:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
}

/* Gradient background with scroll effects */
.gradient-bg {
  background: linear-gradient(135deg, 
    hsl(213, 35%, 8%) 0%, 
    hsl(211, 24%, 14%) 25%, 
    hsl(210, 21%, 20%) 50%, 
    hsl(209, 18%, 27%) 75%, 
    hsl(208, 16%, 35%) 100%);
  background-attachment: fixed;
}

/* Responsive scroll adjustments */
@media (max-width: 768px) {
  :root {
    --header-height: 56px;
    --page-padding: 60px;
  }
}

:root {
  /* Trade Scout Brand Colors */
  --bg-primary: hsl(213, 35%, 8%);
  --bg-secondary: hsl(211, 24%, 14%);
  --bg-tertiary: hsl(210, 21%, 20%);
  --bg-quaternary: hsl(209, 18%, 27%);

  --text-primary: hsl(210, 20%, 89%);
  --text-secondary: hsl(210, 14%, 71%);
  --text-muted: hsl(210, 10%, 62%);

  --orange-primary: hsl(15, 100%, 60%);
  --orange-secondary: hsl(15, 79%, 54%);
  --orange-tertiary: hsl(15, 100%, 65%);

  --success: hsl(142, 76%, 46%);
  --warning: hsl(38, 92%, 50%);
  --error: hsl(0, 84%, 60%);

  --border-primary: hsl(210, 18%, 27%);
  --border-secondary: hsl(209, 14%, 37%);

  --shadow-card: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.2);
  --shadow-glow: 0 4px 6px -1px rgba(0, 0, 0, 0.3), 0 2px 4px -1px rgba(0, 0, 0, 0.2);

  --header-height: 64px;
  --page-padding: 80px;

  /* shadcn/ui compatibility */
  --background: var(--bg-primary);
  --foreground: var(--text-primary);
  --card: var(--bg-secondary);
  --card-foreground: var(--text-primary);
  --popover: var(--bg-secondary);
  --popover-foreground: var(--text-primary);
  --primary: var(--orange-primary);
  --primary-foreground: hsl(0, 0%, 100%);
  --secondary: var(--bg-tertiary);
  --secondary-foreground: var(--text-primary);
  --muted: var(--bg-tertiary);
  --muted-foreground: var(--text-muted);
  --accent: var(--bg-quaternary);
  --accent-foreground: var(--text-primary);
  --destructive: var(--error);
  --destructive-foreground: hsl(0, 0%, 100%);
  --border: var(--border-primary);
  --input: var(--bg-tertiary);
  --ring: var(--orange-primary);

  --radius: 0.75rem;
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
  }

  /* Custom gradient background */
  .gradient-bg {
    background: linear-gradient(135deg, hsl(211, 24%, 14%) 0%, hsl(213, 35%, 8%) 100%);
    min-height: 100vh;
  }

  /* Card shadow utility */
  .card-shadow {
    box-shadow: var(--shadow-card);
  }

  /* Mobile-friendly touch targets */
  .touch-target {
    min-height: 44px;
    min-width: 44px;
    padding: 12px;
  }

  /* Smooth scrolling for better mobile experience */
  html {
    scroll-behavior: smooth;
  }

  /* Enhanced mobile tap highlights */
  * {
    -webkit-tap-highlight-color: rgba(255, 107, 53, 0.2);
  }

  /* Mobile-friendly scrollbars and layout */
  * {
    box-sizing: border-box;
  }

  html, body {
    overflow-x: auto; /* Allow horizontal scroll if needed */
    width: 100%;
  }

  /* Enhanced header navigation styling */
  .nav-button {
    @apply transition-all duration-200 ease-in-out;
  }

  .nav-button:hover {
    @apply transform translate-y-[-1px] shadow-sm;
  }

  /* Navigation scrollbar styling */
  .nav-scrollbar::-webkit-scrollbar {
    height: 2px;
  }

  .nav-scrollbar::-webkit-scrollbar-track {
    background: rgba(148, 163, 184, 0.1);
  }

  .nav-scrollbar::-webkit-scrollbar-thumb {
    background: rgba(251, 146, 60, 0.5);
    border-radius: 2px;
  }

  .nav-scrollbar::-webkit-scrollbar-thumb:hover {
    background: rgba(251, 146, 60, 0.8);
  }

  /* Mobile-optimized input fields */
  @media (max-width: 768px) {
    input, textarea, select {
      font-size: 16px; /* Prevents zoom on iOS */
    }
  }

  /* App-like mobile styles */
  @media (max-width: 768px) {
    /* Remove default browser chrome on mobile */
    html {
      -webkit-text-size-adjust: 100%;
      -ms-text-size-adjust: 100%;
    }

    /* App-like scrolling */
    body {
      -webkit-overflow-scrolling: touch;
      overscroll-behavior: none;
    }

    /* Remove pull-to-refresh on Chrome mobile */
    body {
      overscroll-behavior-y: contain;
    }

    /* App-like button interactions */
    button, .button {
      -webkit-tap-highlight-color: transparent;
      -webkit-touch-callout: none;
      -webkit-user-select: none;
      user-select: none;
      touch-action: manipulation;
    }

    /* App-like card interactions */
    .card-interactive {
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    .card-interactive:active {
      transform: scale(0.98);
      box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
    }

    /* Smooth scrolling for mobile */
    * {
      scroll-behavior: smooth;
    }

    /* Hide scrollbars on mobile for cleaner look */
    .hide-scrollbar {
      -ms-overflow-style: none;
      scrollbar-width: none;
    }

    .hide-scrollbar::-webkit-scrollbar {
      display: none;
    }
  }

  /* PWA splash screen support */
  @media (display-mode: standalone) {
    body {
      padding-top: env(safe-area-inset-top);
      padding-bottom: env(safe-area-inset-bottom);
      padding-left: env(safe-area-inset-left);
      padding-right: env(safe-area-inset-right);
    }
  }

  /* App-like page transitions */
  .page-transition {
    animation: slideInRight 0.3s ease-out;
  }

  @keyframes slideInRight {
    from {
      transform: translateX(100%);
      opacity: 0;
    }
    to {
      transform: translateX(0);
      opacity: 1;
    }
  }

  .page-transition-back {
    animation: slideInLeft 0.3s ease-out;
  }

  @keyframes slideInLeft {
    from {
      transform: translateX(-100%);
      opacity: 0;
    }
    to {
      transform: translateX(0);
      opacity: 1;
    }
  }

  /* Mobile bottom navigation safe area */
  .mobile-nav-spacer {
    height: calc(64px + env(safe-area-inset-bottom));
  }

  /* Engagement animations */
  .pulse-glow {
    animation: pulseGlow 2s ease-in-out infinite;
  }

  @keyframes pulseGlow {
    0%, 100% { box-shadow: 0 0 5px rgba(255, 107, 53, 0.3); }
    50% { box-shadow: 0 0 20px rgba(255, 107, 53, 0.6); }
  }

  .notification-bounce {
    animation: notificationBounce 0.6s ease-out;
  }

  @keyframes notificationBounce {
    0% { transform: scale(0.3) translateY(-50px); opacity: 0; }
    50% { transform: scale(1.05); }
    70% { transform: scale(0.9); }
    100% { transform: scale(1) translateY(0); opacity: 1; }
  }

  /* Progress bar animation */
  .progress-fill {
    transition: width 0.3s ease-in-out;
  }

  /* Line clamp utilities */
  .line-clamp-1 {
    overflow: hidden;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 1;
  }

  .line-clamp-2 {
    overflow: hidden;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .line-clamp-3 {
    overflow: hidden;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
  }

  /* Navigation enhancements */
  .nav-glass {
    background: rgba(13, 22, 36, 0.85);
    backdrop-filter: blur(12px);
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  }

  .nav-item-glow {
    position: relative;
    overflow: hidden;
  }

  .nav-item-glow::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(255, 107, 53, 0.1),
      transparent
    );
    transition: left 0.5s;
  }

  .nav-item-glow:hover::before {
    left: 100%;
  }

  /* Menu item active state animation */
  .menu-item-active {
    animation: menuItemPulse 0.3s ease-out;
  }

  @keyframes menuItemPulse {
    0% { transform: scale(1); }
    50% { transform: scale(1.02); }
    100% { transform: scale(1); }
  }

  /* Tooltip enhancements */
  .tooltip-arrow {
    filter: drop-shadow(0 -2px 4px rgba(0, 0, 0, 0.2));
  }

  /* Card hover enhancements */
  .card-enhanced {
    transition: all 0.3s ease;
  }

  .card-enhanced:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.4);
  }

  /* Loading skeleton animation */
  .skeleton {
    background: linear-gradient(90deg, rgba(255,255,255,0.1) 25%, rgba(255,255,255,0.2) 50%, rgba(255,255,255,0.1) 75%);
    background-size: 200% 100%;
    animation: loading 1.5s infinite;
  }

  @keyframes loading {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }

  /* Glow effect for CTAs */
  .glow-effect {
    transition: box-shadow 0.3s ease;
  }

  .glow-effect:hover {
    box-shadow: var(--shadow-glow);
  }

  /* Mobile sticky positioning */
  .sticky-bottom {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 50;
  }

  /* Hide scrollbar for Chrome, Safari and Opera */
  body::-webkit-scrollbar {
    display: none;
  }

  /* Hide scrollbar for IE, Edge and Firefox */
  body {
    -ms-overflow-style: none;  /* IE and Edge */
    scrollbar-width: none;  /* Firefox */
  }

  /* Prevent horizontal scroll issues */
  html, body {
    overflow-x: auto; /* Allow horizontal scroll if needed */
    max-width: 100vw;
  }

  /* Ensure all containers respect viewport width */
  * {
    box-sizing: border-box;
  }

  .max-w-7xl, .max-w-6xl, .max-w-5xl, .max-w-4xl, .max-w-3xl, .max-w-2xl, .max-w-xl {
    max-width: calc(100vw - 2rem);
  }

  /* Mobile-first responsive utilities */
  @media (max-width: 768px) {
    /* Compact grid layouts */
    .grid {
      gap: 0.5rem !important;
    }

    /* Full width on mobile */
    .w-full-mobile {
      width: 100% !important;
    }

    /* Compact spacing */
    .space-y-8 > * + * {
      margin-top: 1rem !important;
    }

    .space-y-6 > * + * {
      margin-top: 0.75rem !important;
    }

    .space-y-4 > * + * {
      margin-top: 0.5rem !important;
    }

    /* Responsive text */
    .text-4xl {
      font-size: 2rem !important;
    }

    .text-3xl {
      font-size: 1.75rem !important;
    }

    .text-2xl {
      font-size: 1.5rem !important;
    }

    .text-xl {
      font-size: 1.125rem !important;
    }

    /* Mobile navigation */
    .nav-glass {
      padding: 0.5rem 1rem;
    }

    /* Compact cards */
    .card-content {
      padding: 0.75rem !important;
    }

    /* Mobile-friendly buttons */
    .button {
      padding: 0.5rem 0.875rem;
      font-size: 0.875rem;
    }

    /* Fix image responsiveness */
    img {
      max-width: 100%;
      height: auto;
    }

    /* Prevent text overflow */
    .truncate-mobile {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }
}

@layer components {
