  background: hsl(209, 18%, 27%);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: hsl(208, 16%, 35%);
}

/* Swipe navigation styles */
.swipe-container {
  touch-action: pan-y;
  overflow-x: hidden;
  max-width: 100vw;
  width: 100%;
}

.swipe-indicator {
  position: fixed;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1000;
  background: rgba(0, 0, 0, 0.7);
  border-radius: 50%;
  padding: 12px;
  backdrop-filter: blur(10px);
