import { useState, useEffect } from "react";
import { AuthModal } from "./auth-modal";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Lock, Star, Shield } from "lucide-react";
import { useAuth } from "@/hooks/useAuth";

interface GuestGateProps {
  children: React.ReactNode;
  action: string; // e.g., "contact this contractor", "get quotes", "save contractors"
  title?: string;
  description?: string;
}

export function GuestGate({ 
  children, 
  action, 
  title = "Create Account to Continue",
  description = "To ensure authentic interactions and protect our contractors, you need an account to proceed."
}: GuestGateProps) {
  const { isAuthenticated } = useAuth();
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [isGuestMode, setIsGuestMode] = useState(false);

  useEffect(() => {
    const guestMode = localStorage.getItem('guestMode');
    setIsGuestMode(guestMode === 'true');
  }, []);

  // If user is authenticated, show content
  if (isAuthenticated) {
    return <>{children}</>;
  }

  // If user is in guest mode, show the gate
  if (isGuestMode) {
    return (
      <div className="space-y-4">
        {/* Guest limitation notice */}
        <Card className="bg-gradient-to-r from-orange-500/10 to-orange-600/10 border-orange-500/30">
          <CardContent className="p-6">
            <div className="flex items-start space-x-4">
              <div className="flex-shrink-0">
                <Lock className="w-6 h-6 text-orange-400" />
              </div>
              <div className="flex-1">
                <h3 className="text-lg font-semibold text-white mb-2">{title}</h3>
                <p className="text-gray-300 mb-4">{description}</p>

                <div className="space-y-2 mb-4 text-sm text-gray-400">
                  <div className="flex items-center space-x-2">
                    <Shield className="w-4 h-4" />
                    <span>Verified contractor interactions</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Star className="w-4 h-4" />
                    <span>Personalized recommendations</span>
                  </div>
                  <div className="flex items-center space-x-2">
                    <Lock className="w-4 h-4" />
                    <span>Secure quote requests</span>
                  </div>
                </div>

                <Button 
                  onClick={() => setShowAuthModal(true)}
                  className="bg-orange-500 hover:bg-orange-600 text-white"
                >
                  Create Free Account to {action}
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Show limited version of content */}
        <div className="opacity-50 pointer-events-none">
          {children}
        </div>

        {/* Authentication Modal */}
        <AuthModal 
          isOpen={showAuthModal}
          onClose={() => setShowAuthModal(false)}
          title={`Create Account to ${action}`}
          description="Join thousands of homeowners and contractors on TradeScout"
          trigger="guest_gate"
          showGuestOption={false}
        />
      </div>
    );
  }

  // If user is not in guest mode, show content normally (they'll be redirected to auth)
  return <>{children}</>;
}

client/src/components/social/PostCard.ts.content:
import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { CommentsSection } from "./CommentsSection";
import { ShareModal } from "./ShareModal";
import { ReportModal } from "./ReportModal";
import { useAuth } from "@/hooks/useAuth";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import {
  Heart,
  MessageCircle,
  Share2,
  MoreHorizontal,
  Pin,
  BookmarkPlus,
  Flag,
  Calendar,
  MapPin,
  Users,
  TrendingUp
} from "lucide-react";

interface PostCardProps {
  post: any;
}

export function PostCard({ post }: PostCardProps) {
  const { user, isAuthenticated } = useAuth();
  const queryClient = useQueryClient();
  const { toast } = useToast();

  const [showComments, setShowComments] = useState(false);
  const [showShareModal, setShowShareModal] = useState(false);
  const [showReportModal, setShowReportModal] = useState(false);
  const [isLiked, setIsLiked] = useState(post.isLiked || false);
  const [likeCount, setLikeCount] = useState(post.likeCount || 0);

  // Like/unlike mutation
  const likeMutation = useMutation({
    mutationFn: () => apiRequest('POST', `/api/social/posts/${post.id}/like`),
    onSuccess: () => {
      setIsLiked(!isLiked);
      setLikeCount(prev => isLiked ? prev - 1 : prev + 1);
      queryClient.invalidateQueries({ queryKey: ['/api/social/feed'] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update like",
        variant: "destructive",
      });
    },
  });

  // Save/bookmark mutation
  const saveMutation = useMutation({
    mutationFn: () => apiRequest('POST', `/api/social/posts/${post.id}/save`),
    onSuccess: () => {
      toast({
        title: "Success",
        description: "Post saved successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to save post",
        variant: "destructive",
      });
    },
  });

  const handleLike = () => {
    if (!isAuthenticated) {
      toast({
        title: "Login Required",
        description: "Please login to like posts",
        variant: "destructive",
      });
      return;
    }
    likeMutation.mutate();
  };

  const handleShare = () => {
    setShowShareModal(true);
  };

  const handleSave = () => {
    if (!isAuthenticated) {
      toast({
        title: "Login Required",
        description: "Please login to save posts",
        variant: "destructive",
      });
      return;
    }
    saveMutation.mutate();
  };

  const handleReport = () => {
    if (!isAuthenticated) {
      toast({
        title: "Login Required",
        description: "Please login to report posts",
        variant: "destructive",
      });
      return;
    }
    setShowReportModal(true);
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));

    if (diffInHours < 1) return "Just now";
    if (diffInHours < 24) return `${diffInHours}h ago`;
    if (diffInHours < 168) return `${Math.floor(diffInHours / 24)}d ago`;
    return date.toLocaleDateString();
  };

  const getPostTypeColor = (type: string) => {
    const colors = {
      general: "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300",
      projects: "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300",
      recommendations: "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300",
      questions: "bg-orange-100 text-orange-800 dark:bg-orange-900 dark:text-orange-300",
      marketplace: "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300",
      events: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300",
    };
    return colors[type as keyof typeof colors] || colors.general;
  };

  const getPostTypeIcon = (type: string) => {
    const icons = {
      projects: TrendingUp,
      events: Calendar,
      marketplace: Users,
      default: MessageCircle,
    };
    const IconComponent = icons[type as keyof typeof icons] || icons.default;
    return <IconComponent className="h-4 w-4" />;
  };

  return (
    <Card className="hover:shadow-md transition-shadow">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="flex items-center space-x-3">
            <Avatar className="h-10 w-10">
              <AvatarImage src={post.author.profileImageUrl} />
              <AvatarFallback className="bg-primary/10 text-primary">
                {post.author.firstName?.[0]}{post.author.lastName?.[0]}
              </AvatarFallback>
            </Avatar>

            <div className="flex-1">
              <div className="flex items-center gap-2">
                <h4 className="font-semibold text-sm">
                  {post.author.firstName} {post.author.lastName}
                </h4>
                {post.author.isVerified && (
                  <Badge variant="secondary" className="text-xs px-1.5 py-0.5">
                    Verified
                  </Badge>
                )}
              </div>

              <div className="flex items-center gap-2 text-xs text-muted-foreground">
                <span>{formatDate(post.createdAt)}</span>
                {post.location && (
                  <>
                    <span>•</span>
                    <div className="flex items-center gap-1">
                      <MapPin className="h-3 w-3" />
                      <span>{post.location}</span>
                    </div>
                  </>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Badge className={`text-xs ${getPostTypeColor(post.postType)}`}>
              <div className="flex items-center gap-1">
                {getPostTypeIcon(post.postType)}
                <span className="capitalize">{post.postType.replace('_', ' ')}</span>
              </div>
            </Badge>

            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                  <MoreHorizontal className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={handleSave}>
                  <BookmarkPlus className="h-4 w-4 mr-2" />
                  Save post
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handleReport}>
                  <Flag className="h-4 w-4 mr-2" />
                  Report post
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Post Title */}
        {post.title && (
          <h3 className="text-lg font-semibold leading-tight">{post.title}</h3>
        )}

        {/* Post Content */}
        <div className="prose prose-sm max-w-none">
          <p className="text-gray-900 dark:text-gray-100 whitespace-pre-wrap">
            {post.content}
          </p>
        </div>

        {/* Post Images */}
        {post.imageUrls && post.imageUrls.length > 0 && (
          <div className={`grid gap-2 ${post.imageUrls.length === 1 ? 'grid-cols-1' : 'grid-cols-2'}`}>
            {post.imageUrls.slice(0, 4).map((url: string, index: number) => (
              <div key={index} className="relative">
                <img
                  src={url}
                  alt={`Post image ${index + 1}`}
                  className="w-full h-48 object-cover rounded-lg"
                  loading="lazy"
                />
                {post.imageUrls.length > 4 && index === 3 && (
                  <div className="absolute inset-0 bg-black/50 rounded-lg flex items-center justify-center">
                    <span className="text-white font-semibold">
                      +{post.imageUrls.length - 4} more
                    </span>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* Post Tags */}
        {post.tags && post.tags.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {post.tags.map((tag: string, index: number) => (
              <Badge key={index} variant="outline" className="text-xs">
                #{tag}
              </Badge>
            ))}
          </div>
        )}

        {/* Engagement Bar */}
        <div className="flex items-center justify-between pt-2 border-t border-gray-100 dark:border-gray-800">
          <div className="flex items-center space-x-4">
            <Button
              variant="ghost"
              size="sm"
              onClick={handleLike}
              className={`flex items-center space-x-2 ${
                isLiked ? 'text-red-500 hover:text-red-600' : 'text-muted-foreground hover:text-red-500'
              }`}
              disabled={likeMutation.isPending}
            >
              <Heart className={`h-4 w-4 ${isLiked ? 'fill-current' : ''}`} />
              <span>{likeCount}</span>
            </Button>

            <Button
              variant="ghost"
              size="sm"
              onClick={() => setShowComments(!showComments)}
              className="flex items-center space-x-2 text-muted-foreground hover:text-primary"
            >
              <MessageCircle className="h-4 w-4" />
              <span>{post.commentCount || 0}</span>
            </Button>

            <Button
              variant="ghost"
              size="sm"
              onClick={handleShare}
              className="flex items-center space-x-2 text-muted-foreground hover:text-primary"
            >
              <Share2 className="h-4 w-4" />
              <span>Share</span>
            </Button>
          </div>

          {/* Engagement Stats */}
          {(likeCount > 0 || post.commentCount > 0 || post.shareCount > 0) && (
            <div className="text-xs text-muted-foreground">
              {likeCount > 0 && <span>{likeCount} likes</span>}
              {post.commentCount > 0 && (
                <>
                  {likeCount > 0 && <span> • </span>}
                  <span>{post.commentCount} comments</span>
                </>
              )}
              {post.shareCount > 0 && (
                <>
                  {(likeCount > 0 || post.commentCount > 0) && <span> • </span>}
                  <span>{post.shareCount} shares</span>
                </>
              )}
            </div>
          )}
        </div>

        {/* Comments Section */}
        {showComments && (
          <div className="border-t border-gray-100 dark:border-gray-800 pt-4">
