import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Mail, MessageSquare, Users, DollarSign, Calendar, Search } from "lucide-react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { useToast } from "@/hooks/use-toast";

// Contact form schema
const contactFormSchema = z.object({
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  email: z.string().email("Valid email is required"),
  phone: z.string().optional(),
  company: z.string().optional(),
  status: z.enum(["lead", "prospect", "customer", "inactive"]),
  assignedToUserId: z.string().optional(),
  notes: z.string().optional(),
});

// Deal form schema
const dealFormSchema = z.object({
  title: z.string().min(1, "Title is required"),
  value: z.string().optional(),
  stage: z.enum(["lead", "qualified", "proposal", "negotiation", "closed_won", "closed_lost"]),
  contactId: z.string().min(1, "Contact is required"),
  assignedToUserId: z.string().optional(),
  description: z.string().optional(),
  expectedCloseDate: z.string().optional(),
});

// Activity form schema
const activityFormSchema = z.object({
  type: z.enum(["call", "email", "meeting", "note", "task", "internal_message"]),
  subject: z.string().min(1, "Subject is required"),
  description: z.string().min(1, "Description is required"),
  contactId: z.string().optional(),
  dealId: z.string().optional(),
});

export default function CrmDashboard() {
  const [searchTerm, setSearchTerm] = useState("");
  const [contactDialogOpen, setContactDialogOpen] = useState(false);
  const [dealDialogOpen, setDealDialogOpen] = useState(false);
  const [activityDialogOpen, setActivityDialogOpen] = useState(false);
  const [selectedContact, setSelectedContact] = useState<any>(null);
  const [selectedDeal, setSelectedDeal] = useState<any>(null);

  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch CRM data
  const { data: contacts = [], isLoading: contactsLoading } = useQuery({
    queryKey: ["/api/crm/contacts", searchTerm],
    queryFn: () => searchTerm ? 
      fetch(`/api/crm/contacts?search=${encodeURIComponent(searchTerm)}`).then(res => res.json()) :
      fetch("/api/crm/contacts").then(res => res.json()),
  });

  const { data: deals = [], isLoading: dealsLoading } = useQuery({
    queryKey: ["/api/crm/deals"],
    queryFn: () => fetch("/api/crm/deals").then(res => res.json()),
  });

  const { data: activities = [], isLoading: activitiesLoading } = useQuery({
    queryKey: ["/api/crm/activities"],
    queryFn: () => fetch("/api/crm/activities").then(res => res.json()),
  });

  // Forms
  const contactForm = useForm({
    resolver: zodResolver(contactFormSchema),
    defaultValues: {
      firstName: "",
      lastName: "",
      email: "",
      phone: "",
      company: "",
      status: "lead" as const,
      assignedToUserId: "",
      notes: "",
    },
  });

  const dealForm = useForm({
    resolver: zodResolver(dealFormSchema),
    defaultValues: {
      title: "",
      value: "",
      stage: "lead" as const,
      contactId: "",
      assignedToUserId: "",
      description: "",
      expectedCloseDate: "",
    },
  });

  const activityForm = useForm({
    resolver: zodResolver(activityFormSchema),
    defaultValues: {
      type: "note" as const,
      subject: "",
      description: "",
      contactId: "",
      dealId: "",
    },
  });

  // Mutations
  const createContactMutation = useMutation({
    mutationFn: (data: any) => fetch("/api/crm/contacts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    }).then(res => res.json()),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/contacts"] });
      toast({ title: "Success", description: "Contact created successfully" });
      setContactDialogOpen(false);
      contactForm.reset();
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to create contact", variant: "destructive" });
    },
  });

  const createDealMutation = useMutation({
    mutationFn: (data: any) => fetch("/api/crm/deals", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    }).then(res => res.json()),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/deals"] });
      toast({ title: "Success", description: "Deal created successfully" });
      setDealDialogOpen(false);
      dealForm.reset();
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to create deal", variant: "destructive" });
    },
  });

  const createActivityMutation = useMutation({
    mutationFn: (data: any) => fetch("/api/crm/activities", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    }).then(res => res.json()),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/activities"] });
      toast({ title: "Success", description: "Activity logged successfully" });
      setActivityDialogOpen(false);
      activityForm.reset();
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to log activity", variant: "destructive" });
    },
  });

  const sendInternalMessageMutation = useMutation({
    mutationFn: (data: any) => fetch("/api/crm/internal-message", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    }).then(res => res.json()),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/crm/activities"] });
      toast({ title: "Success", description: "Internal message sent successfully" });
    },
    onError: () => {
      toast({ title: "Error", description: "Failed to send internal message", variant: "destructive" });
    },
  });

  // Form handlers
  const onContactSubmit = (data: any) => {
    createContactMutation.mutate(data);
  };

  const onDealSubmit = (data: any) => {
    createDealMutation.mutate(data);
  };

  const onActivitySubmit = (data: any) => {
    createActivityMutation.mutate(data);
  };

  // Stats calculations
  const contactStats = {
    total: Array.isArray(contacts) ? contacts.length : 0,
    leads: Array.isArray(contacts) ? contacts.filter((c: any) => c.status === "lead").length : 0,
    prospects: Array.isArray(contacts) ? contacts.filter((c: any) => c.status === "prospect").length : 0,
    customers: Array.isArray(contacts) ? contacts.filter((c: any) => c.status === "customer").length : 0,
  };

  const dealStats = {
    total: Array.isArray(deals) ? deals.length : 0,
    totalValue: Array.isArray(deals) ? deals.reduce((sum: number, deal: any) => sum + (parseFloat(deal.value) || 0), 0) : 0,
    won: Array.isArray(deals) ? deals.filter((d: any) => d.stage === "closed_won").length : 0,
    lost: Array.isArray(deals) ? deals.filter((d: any) => d.stage === "closed_lost").length : 0,
  };

  const recentActivities = Array.isArray(activities) ? activities.slice(0, 10) : [];

  return (
    <div className="space-y-8">
      {/* Header */}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">CRM Dashboard</h1>
          <p className="text-muted-foreground">Manage contacts, deals, and customer relationships</p>
        </div>
        <div className="flex gap-2">
          <Dialog open={contactDialogOpen} onOpenChange={setContactDialogOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="h-4 w-4 mr-2" />
                Add Contact
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
              <DialogHeader>
                <DialogTitle>Add New Contact</DialogTitle>
              </DialogHeader>
              <Form {...contactForm}>
                <form onSubmit={contactForm.handleSubmit(onContactSubmit)} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={contactForm.control}
                      name="firstName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>First Name *</FormLabel>
                          <FormControl>
                            <Input {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={contactForm.control}
                      name="lastName"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Last Name *</FormLabel>
                          <FormControl>
                            <Input {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={contactForm.control}
                      name="email"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Email *</FormLabel>
                          <FormControl>
                            <Input type="email" {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={contactForm.control}
                      name="phone"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Phone</FormLabel>
                          <FormControl>
                            <Input {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <FormField
                      control={contactForm.control}
                      name="company"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Company</FormLabel>
                          <FormControl>
                            <Input {...field} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={contactForm.control}
                      name="status"
                      render={({ field }) => (
                        <FormItem>
