import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Bug, ExternalLink, Clock, CheckCircle, XCircle, AlertTriangle, User, Calendar, Globe, Smartphone, Monitor } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import type { ErrorReport } from "@shared/schema";

export default function AdminErrorReports() {
  const [selectedReport, setSelectedReport] = useState<ErrorReport | null>(null);
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterType, setFilterType] = useState("all");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const { data: reports = [], isLoading } = useQuery({
    queryKey: ['/api/admin/error-reports'],
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: any }) => {
      return apiRequest("PATCH", `/api/admin/error-reports/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/error-reports'] });
      toast({
        title: "Report Updated",
        description: "The error report has been updated successfully.",
      });
    },
  });

  const filteredReports = reports.filter((report: ErrorReport) => {
    if (filterStatus !== "all" && report.status !== filterStatus) return false;
    if (filterType !== "all" && report.errorType !== filterType) return false;
    return true;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'open': return 'bg-red-500/20 text-red-500';
      case 'in_progress': return 'bg-yellow-500/20 text-yellow-500';
      case 'resolved': return 'bg-green-500/20 text-green-500';
      case 'closed': return 'bg-gray-500/20 text-gray-500';
      case 'duplicate': return 'bg-blue-500/20 text-blue-500';
      default: return 'bg-gray-500/20 text-gray-500';
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'low': return 'bg-green-500/20 text-green-500';
      case 'medium': return 'bg-yellow-500/20 text-yellow-500';
      case 'high': return 'bg-orange-500/20 text-orange-500';
      case 'critical': return 'bg-red-500/20 text-red-500';
      default: return 'bg-gray-500/20 text-gray-500';
    }
  };

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'bug': return <Bug className="h-4 w-4" />;
      case 'performance': return <Clock className="h-4 w-4" />;
      case 'ui_issue': return <Monitor className="h-4 w-4" />;
      case 'feature_request': return <AlertTriangle className="h-4 w-4" />;
      case 'automatic_screenshot': return <Smartphone className="h-4 w-4" />;
      default: return <Bug className="h-4 w-4" />;
    }
  };

  const renderScreenshot = (attachments: any) => {
    if (!attachments || !Array.isArray(attachments) || attachments.length === 0) {
      return null;
    }

    const screenshot = attachments.find((att: any) => att.type === 'screenshot');
    if (!screenshot || !screenshot.data) {
      return null;
    }

    return (
      <div className="mt-4">
        <Label className="text-sm font-medium text-gray-300 mb-2 block">Screenshot</Label>
        <div className="border border-gray-600 rounded-lg overflow-hidden">
          <img 
            src={screenshot.data} 
            alt="Bug report screenshot" 
            className="w-full h-auto max-h-96 object-contain bg-gray-800"
            style={{ imageRendering: 'auto' }}
          />
        </div>
        <Button
          variant="outline"
          size="sm"
          className="mt-2"
          onClick={() => {
            const link = document.createElement('a');
            link.href = screenshot.data;
            link.download = `bug-report-screenshot-${selectedReport?.id}.jpeg`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
          }}
        >
          Download Screenshot
        </Button>
      </div>
    );
  };

  const handleStatusChange = (reportId: string, newStatus: string) => {
    updateMutation.mutate({
      id: reportId,
      data: { status: newStatus }
    });
  };

  const handlePriorityChange = (reportId: string, newPriority: string) => {
    updateMutation.mutate({
      id: reportId,
      data: { priority: newPriority }
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-navy-900 text-white p-6">
        <div className="max-w-6xl mx-auto">
          <div className="animate-pulse space-y-4">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="h-32 bg-navy-700 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-navy-900 text-white">
      <div className="max-w-6xl mx-auto p-6">
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2">Error Reports</h1>
          <p className="text-gray-400">Manage bug reports and user feedback</p>
        </div>

        {/* Filters */}
        <div className="flex gap-4 mb-6">
          <Select value={filterStatus} onValueChange={setFilterStatus}>
            <SelectTrigger className="w-48 bg-navy-700 border-navy-600 text-white">
              <SelectValue placeholder="Filter by status" />
            </SelectTrigger>
            <SelectContent className="bg-navy-700 border-navy-600">
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="open">Open</SelectItem>
              <SelectItem value="in_progress">In Progress</SelectItem>
              <SelectItem value="resolved">Resolved</SelectItem>
              <SelectItem value="closed">Closed</SelectItem>
              <SelectItem value="duplicate">Duplicate</SelectItem>
            </SelectContent>
          </Select>

          <Select value={filterType} onValueChange={setFilterType}>
            <SelectTrigger className="w-48 bg-navy-700 border-navy-600 text-white">
              <SelectValue placeholder="Filter by type" />
            </SelectTrigger>
            <SelectContent className="bg-navy-700 border-navy-600">
              <SelectItem value="all">All Types</SelectItem>
              <SelectItem value="bug">Bug/Error</SelectItem>
              <SelectItem value="ui_issue">UI Issue</SelectItem>
              <SelectItem value="performance">Performance</SelectItem>
              <SelectItem value="feature_request">Feature Request</SelectItem>
              <SelectItem value="other">Other</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Reports List */}
        <div className="space-y-4">
          {filteredReports.map((report: ErrorReport) => (
            <Card key={report.id} className="bg-navy-700 border-navy-600">
              <CardContent className="p-6">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      {getTypeIcon(report.errorType)}
                      <h3 className="text-lg font-semibold text-white">{report.title}</h3>
                      <Badge className={getStatusColor(report.status)}>
                        {report.status.replace('_', ' ').toUpperCase()}
                      </Badge>
                      <Badge className={getPriorityColor(report.priority)}>
                        {report.priority.toUpperCase()}
                      </Badge>
                    </div>

                    <p className="text-gray-300 mb-3 line-clamp-2">{report.description}</p>

                    <div className="flex items-center gap-4 text-sm text-gray-400">
                      <div className="flex items-center gap-1">
                        <Calendar className="h-4 w-4" />
                        {new Date(report.createdAt).toLocaleDateString()}
                      </div>
                      {report.userEmail && (
                        <div className="flex items-center gap-1">
                          <User className="h-4 w-4" />
                          {report.userEmail}
                        </div>
                      )}
                      {report.currentUrl && (
                        <div className="flex items-center gap-1">
                          <Globe className="h-4 w-4" />
                          <span className="truncate max-w-40">{new URL(report.currentUrl).pathname}</span>
                        </div>
                      )}
                      {report.browserInfo?.mobile && (
                        <div className="flex items-center gap-1">
                          <Smartphone className="h-4 w-4" />
                          Mobile
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2 ml-4">
                    <Select
                      value={report.status}
                      onValueChange={(value) => handleStatusChange(report.id, value)}
                    >
                      <SelectTrigger className="w-32 bg-navy-600 border-navy-500 text-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-navy-700 border-navy-600">
                        <SelectItem value="open">Open</SelectItem>
                        <SelectItem value="in_progress">In Progress</SelectItem>
                        <SelectItem value="resolved">Resolved</SelectItem>
                        <SelectItem value="closed">Closed</SelectItem>
                        <SelectItem value="duplicate">Duplicate</SelectItem>
                      </SelectContent>
                    </Select>

                    <Select
                      value={report.priority}
                      onValueChange={(value) => handlePriorityChange(report.id, value)}
                    >
                      <SelectTrigger className="w-28 bg-navy-600 border-navy-500 text-white">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-navy-700 border-navy-600">
                        <SelectItem value="low">Low</SelectItem>
                        <SelectItem value="medium">Medium</SelectItem>
                        <SelectItem value="high">High</SelectItem>
                        <SelectItem value="critical">Critical</SelectItem>
                      </SelectContent>
                    </Select>

                    <Button
                      onClick={() => setSelectedReport(report)}
                      variant="outline"
                      size="sm"
                      className="border-navy-500 text-gray-300"
                    >
                      <ExternalLink className="h-4 w-4 mr-1" />
                      View
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>

        {filteredReports.length === 0 && (
          <Card className="bg-navy-700 border-navy-600">
            <CardContent className="p-8 text-center">
              <Bug className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-semibold text-white mb-2">No Reports Found</h3>
              <p className="text-gray-300">No error reports match your current filters.</p>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Report Detail Modal */}
      {selectedReport && (
        <Dialog open={!!selectedReport} onOpenChange={() => setSelectedReport(null)}>
          <DialogContent className="sm:max-w-[700px] bg-navy-800 border-navy-600 max-h-[80vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle className="text-white flex items-center gap-2">
                {getTypeIcon(selectedReport.errorType)}
                {selectedReport.title}
              </DialogTitle>
            </DialogHeader>

            <div className="space-y-6">
              <div className="flex gap-2">
                <Badge className={getStatusColor(selectedReport.status)}>
                  {selectedReport.status.replace('_', ' ').toUpperCase()}
                </Badge>
                <Badge className={getPriorityColor(selectedReport.priority)}>
                  {selectedReport.priority.toUpperCase()}
                </Badge>
                <Badge variant="outline" className="border-navy-500 text-gray-300">
                  {selectedReport.errorType.replace('_', ' ').toUpperCase()}
                </Badge>
              </div>

              <div>
                <h4 className="text-sm font-semibold text-gray-300 mb-2">Description</h4>
                <p className="text-white bg-navy-700 p-3 rounded border border-navy-600">
                  {selectedReport.description}
                </p>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <h4 className="text-sm font-semibold text-gray-300 mb-2">User Information</h4>
                  <div className="space-y-1 text-sm text-gray-400">
                    <p>Email: {selectedReport.userEmail || 'Anonymous'}</p>
                    <p>User ID: {selectedReport.userId || 'N/A'}</p>
                    <p>Date: {new Date(selectedReport.createdAt).toLocaleString()}</p>
                  </div>
                </div>

                <div>
                  <h4 className="text-sm font-semibold text-gray-300 mb-2">Technical Details</h4>
                  <div className="space-y-1 text-sm text-gray-400">
                    <p>Browser: {selectedReport.browserInfo?.name} {selectedReport.browserInfo?.version}</p>
                    <p>Platform: {selectedReport.browserInfo?.platform}</p>
                    <p>Mobile: {selectedReport.browserInfo?.mobile ? 'Yes' : 'No'}</p>
                  </div>
                </div>
              </div>

              {selectedReport.currentUrl && (
                <div>
                  <h4 className="text-sm font-semibold text-gray-300 mb-2">Page URL</h4>
                  <p className="text-blue-400 text-sm break-all bg-navy-700 p-2 rounded border border-navy-600">
                    {selectedReport.currentUrl}
                  </p>
                </div>
              )}

              {/* Screenshot Display */}
              {renderScreenshot(selectedReport.attachments)}

              {selectedReport.adminNotes && (
                <div>
                  <h4 className="text-sm font-semibold text-gray-300 mb-2">Admin Notes</h4>
                  <p className="text-white bg-navy-700 p-3 rounded border border-navy-600">
                    {selectedReport.adminNotes}
                  </p>
                </div>
              )}
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
}

client/src/pages/moderation-center.tsx.content:
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  Eye,
  ThumbsUp,
  ThumbsDown,
  Clock,
  Users,
  MapPin,
  Flag,
  Scale,
  Shield
} from "lucide-react";
import type { ModerationReport, ModerationVote, UserModerationReputation } from "@shared/schema";

interface ModerationReportWithVotes extends ModerationReport {
  votes?: ModerationVote[];
  canVote?: boolean;
}

export default function ModerationCenter() {
  const [selectedContentType, setSelectedContentType] = useState<string>("all");
  const [selectedStatus, setSelectedStatus] = useState<string>("pending");
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch user's moderation reputation
  const { data: userReputation } = useQuery<UserModerationReputation>({
    queryKey: ["/api/moderation/reputation"],
  });

  // Fetch moderation reports
  const { data: reports = [], isLoading: reportsLoading } = useQuery<ModerationReportWithVotes[]>({
    queryKey: ["/api/moderation/reports", { 
      status: selectedStatus === "all" ? undefined : selectedStatus,
      contentType: selectedContentType === "all" ? undefined : selectedContentType
    }],
  });

  // Vote on report mutation
  const voteMutation = useMutation({
    mutationFn: async ({ reportId, vote }: { reportId: string; vote: string }) => {
      return apiRequest("POST", `/api/moderation/reports/${reportId}/vote`, { vote });
    },
    onSuccess: () => {
      toast({
        title: "Vote Submitted",
        description: "Your vote has been recorded successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/moderation/reports"] });
    },
    onError: (error: Error) => {
      toast({
        title: "Vote Failed",
        description: error.message || "Failed to submit vote",
        variant: "destructive",
      });
    },
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case "pending": return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200";
      case "resolved": return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200";
      case "escalated": return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200";
      default: return "bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200";
    }
  };

  const getContentTypeIcon = (contentType: string) => {
    switch (contentType) {
      case "contractor_profile": return <Users className="h-4 w-4" />;
      case "handmade_product": return <Shield className="h-4 w-4" />;
      case "food_listing": return <AlertTriangle className="h-4 w-4" />;
      case "social_post": return <Flag className="h-4 w-4" />;
      default: return <Eye className="h-4 w-4" />;
    }
  };

  const getVoteIcon = (vote: string) => {
    switch (vote) {
      case "remove": return <XCircle className="h-4 w-4 text-red-500" />;
      case "keep": return <CheckCircle className="h-4 w-4 text-green-500" />;
      case "needs_review": return <Eye className="h-4 w-4 text-blue-500" />;
      default: return <Clock className="h-4 w-4" />;
    }
  };

  const handleVote = (reportId: string, vote: string) => {
    voteMutation.mutate({ reportId, vote });
  };

  if (!userReputation) {
    return (
      <div className="container mx-auto px-4 py-8">
        <Alert>
          <AlertTriangle className="h-4 w-4" />
          <AlertDescription>
            Loading your moderation reputation...
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  if (!userReputation.canVote) {
    return (
      <div className="container mx-auto px-4 py-8">
        <Alert>
          <XCircle className="h-4 w-4" />
          <AlertDescription>
            You are not currently eligible to participate in community moderation. 
            This may be due to account age, address verification status, or moderation history.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Community Moderation Center</h1>
        <p className="text-gray-600 dark:text-gray-400 mt-2">
          Help keep our community safe by reviewing and voting on reported content
        </p>
      </div>

      {/* User Reputation Card */}
      <Card className="mb-6">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Scale className="h-5 w-5" />
            Your Moderation Reputation
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold text-blue-600">{userReputation.reputationScore}</div>
              <div className="text-sm text-gray-500">Reputation Score</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-green-600">{userReputation.totalVotesCast}</div>
              <div className="text-sm text-gray-500">Votes Cast</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-purple-600">{userReputation.totalReportsSubmitted}</div>
              <div className="text-sm text-gray-500">Reports Submitted</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-orange-600">
                {userReputation.totalReportsSubmitted > 0 
                  ? Math.round((userReputation.accurateReports / userReputation.totalReportsSubmitted) * 100)
                  : 0}%
              </div>
              <div className="text-sm text-gray-500">Report Accuracy</div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Filters */}
      <div className="mb-6">
        <Tabs defaultValue="pending" onValueChange={setSelectedStatus}>
          <TabsList>
            <TabsTrigger value="all">All Reports</TabsTrigger>
            <TabsTrigger value="pending">Pending</TabsTrigger>
            <TabsTrigger value="resolved">Resolved</TabsTrigger>
            <TabsTrigger value="escalated">Escalated</TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {/* Reports List */}
      {reportsLoading ? (
        <div className="space-y-4">
          {[...Array(3)].map((_, i) => (
            <Card key={i} className="animate-pulse">
              <CardContent className="p-6">
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                <div className="h-4 bg-gray-200 rounded w-1/2"></div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : reports.length === 0 ? (
        <Card>
          <CardContent className="p-8 text-center">
            <Flag className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-2">
              No Reports Found
            </h3>
            <p className="text-gray-600 dark:text-gray-400">
              There are no reports to review in this category.
            </p>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-6">
          {reports.map((report) => (
            <Card key={report.id} className="overflow-hidden">
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    {getContentTypeIcon(report.contentType)}
                    <div>
                      <CardTitle className="text-lg">
                        {report.contentType.replace('_', ' ').toUpperCase()} Report
                      </CardTitle>
                      <CardDescription className="flex items-center gap-2 mt-1">
                        <MapPin className="h-3 w-3" />
                        {report.contentCounty}, {report.contentState}
                        <Separator orientation="vertical" className="h-4" />
                        <Clock className="h-3 w-3" />
                        {new Date(report.createdAt).toLocaleDateString()}
                      </CardDescription>
                    </div>
                  </div>
                  <Badge className={getStatusColor(report.status)}>
                    {report.status}
                  </Badge>
                </div>
              </CardHeader>

              <CardContent>
                <div className="space-y-4">
                  {/* Report Details */}
                  <div>
                    <h4 className="font-semibold mb-2">Reason for Report:</h4>
                    <p className="text-gray-700 dark:text-gray-300">{report.reason}</p>
                  </div>

                  {report.description && (
                    <div>
                      <h4 className="font-semibold mb-2">Additional Details:</h4>
                      <p className="text-gray-700 dark:text-gray-300">{report.description}</p>
                    </div>
                  )}

                  {/* Voting Statistics */}
                  <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
                    <h4 className="font-semibold mb-3">Community Votes</h4>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      <div className="text-center">
                        <div className="text-xl font-bold">{report.totalVotes}</div>
                        <div className="text-sm text-gray-500">Total Votes</div>
                      </div>
                      <div className="text-center">
                        <div className="text-xl font-bold text-red-600">{report.removeVotes}</div>
                        <div className="text-sm text-gray-500">Remove</div>
                      </div>
                      <div className="text-center">
                        <div className="text-xl font-bold text-green-600">{report.keepVotes}</div>
                        <div className="text-sm text-gray-500">Keep</div>
                      </div>
                      <div className="text-center">
                        <div className="text-xl font-bold text-blue-600">{report.reviewVotes}</div>
                        <div className="text-sm text-gray-500">Review</div>
                      </div>
                    </div>

                    {/* Progress Bar */}
                    <div className="mt-4">
                      <div className="flex items-center justify-between text-sm text-gray-600 mb-1">
                        <span>Progress to Decision</span>
                        <span>{report.totalVotes} / {report.votesRequired} votes</span>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-2">
                        <div 
                          className="bg-blue-600 h-2 rounded-full" 
                          style={{ width: `${Math.min((report.totalVotes / report.votesRequired) * 100, 100)}%` }}
                        ></div>
                      </div>
                    </div>
                  </div>

                  {/* Voting Buttons */}
                  {report.status === "pending" && (
                    <div className="border-t pt-4">
                      <h4 className="font-semibold mb-3">Cast Your Vote</h4>
                      <div className="flex gap-3">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleVote(report.id, "remove")}
                          disabled={voteMutation.isPending}
                          className="flex items-center gap-2 border-red-200 text-red-700 hover:bg-red-50"
                        >
                          <XCircle className="h-4 w-4" />
                          Remove Content
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleVote(report.id, "keep")}
                          disabled={voteMutation.isPending}
                          className="flex items-center gap-2 border-green-200 text-green-700 hover:bg-green-50"
                        >
                          <CheckCircle className="h-4 w-4" />
                          Keep Content
                        </Button>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleVote(report.id, "needs_review")}
                          disabled={voteMutation.isPending}
                          className="flex items-center gap-2 border-blue-200 text-blue-700 hover:bg-blue-50"
                        >
                          <Eye className="h-4 w-4" />
                          Needs Review
                        </Button>
                      </div>
                    </div>
                  )}

                  {/* Final Action */}
                  {report.finalAction && (
                    <div className="border-t pt-4">
                      <div className="flex items-center gap-2 text-sm">
                        <span className="font-semibold">Final Action:</span>
                        <Badge variant="secondary">{report.finalAction.replace('_', ' ')}</Badge>
                        {report.actionReason && (
                          <span className="text-gray-600">- {report.actionReason}</span>
                        )}
                      </div>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

